/* 平成17年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h17.committeeSessions.push(...[{"id":"h17-20051102-8","meetingId":"h17-cm11","date":"2005年11月2日","dateIso":"2005-11-02","committee":"建設委員会","time":"午前１０時０２分～午前１１時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"しながわ水族館イルカショープールの改修","agenda":"しながわ水族館イルカショープールの改修","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"それとも何か普通ですと、両者、こちらが設置者ですから、こちらでやるものと。それからあとは要望・意見なんですけれども、ぜひサンシャインは専門だからわかっているとは思いますけど、気をつけてやってください。","respondent":"藤田道路公園課長","answer":"継続した良好な運営ができるような改修工事を行っているものでございまして、そうした中で、サンシャインのほうが実施をするという形のものです。シックハウス等の関係につきましては、十分に留意しながら、工事を進めていきたいと考えております。","id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"もう一つは、かかったわけですけれども、ウィルスですから、どこからか来たんですよね。必要によっては、それに対処する対応をしておかなきゃいけないと思うんですけれども、その辺はどうなんでしょう。","respondent":"藤田道路公園課長","answer":"１０月６日以前、２週間から３週間前に何らかの形で池の中にそういったコイが放たれてしまったのではないかと考えています。そういったことが原因であろうと考えてございまして、現地で、あるいはホームページでの告知をしています。","id":"exchange-002"},{"speaker":"土井委員","kind":"質問・要望","question":"だからそこら辺も含めて、全体に注意を喚起するようにしておいていただきたいことが１点です。みんなに任せてあるわけですから、みんなの池ですから、これからきっちりしてくださいよということにしておいてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"今いる生物を処分をしてという流れになると、相当大きな清掃費用というのがかかっていくのかなと思うんですけれども、どこから出てくるのですか。どれぐらいかかって、どこからお金が出てくるのか、説明を求めました。","respondent":"藤田道路公園課長","answer":"その中で、東京都のほうでは公園の池で、戸越公園も含めてことしは５件ほど出ております。東京都から費用については出てくるような話も聞いてありますけれども、その辺についてはよく検証しながら進めていきたいと考えています。","id":"exchange-004"}]},{"id":"topic-02","title":"の東京港第７次改訂港湾計画（案）","agenda":"の東京港第７次改訂港湾計画（案）","exchanges":[{"speaker":"土井委員","kind":"質問","question":"ここでの説明はそれでいいんだけれども、その後のというところですが、委員会の中における我々の立場というんですか、都は何を聞きたいのか。変なことを言っておしかりを受けると、品川区が怒られると困るから、ちょっと聞いておきたいんですが。","respondent":"阿部都市計画課長","answer":"港湾問題都区連絡協議会につきましては、東京都と品川区、区議会、それぞれが委員という形になってあります。その中で説明を受けて、あるいは委員として了承するという、そういう話になってくるのかと考えています。","id":"exchange-005"},{"speaker":"菊地委員","kind":"意見","question":"今の土井委員の話と似たような話なんですけれども、こういうものを決めていくときに、区としての意見というのは多分、第７次改訂というから、最初の素案か何かできたときに東京都が意見を聴取したりするのかもしれないんですけれども…","respondent":"阿部都市計画課長","answer":"土井委員に対して説明不足でございましたけれども、区のほうは区と区議会の議長を含めまして、建設委員の方が委員。大田区、この臨港５区でそれぞれの区ごとに開催をして、協議の場を持っていくという形になってあります。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"区としての意見というのは、最初の時点で挙げてありますよというお話なのかどうか説明を求めました。","respondent":"阿部都市計画課長","answer":"最初の段階ではなくて、今回が計画案を示された段階ですので、この計画案に対して、区が意見を提出していくということです。","id":"exchange-007"},{"speaker":"林（和）委員","kind":"質問","question":"この計画案について品川区ではどういうふうに考えているんか尋ねました。","respondent":"阿部都市計画課長","answer":"首都圏全体の生活を支える重要な港だと考えていますので、東京港の港湾計画案にありますように国際競争力の強化は非常に大事だと考えています。そういう意味では、今回の東京都の案に対して、区としては適切な意見・案の方向だろうという認識はあります。","id":"exchange-008"}]},{"id":"topic-03","title":"の平成１７年１１月都営住宅（世帯向・単身者向一般住宅および若年世帯向定期使用住宅等）の募集","agenda":"の平成１７年１１月都営住宅（世帯向・単身者向一般住宅および若年世帯向定期使用住宅等）の募集","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"１つだけ聞かせてもらいたいんですけれども、若年ファミリー向ができてから、三、四年たちますかね。これは１０年間の期間限定ということですけれども、何か意見として挙がっていることがあるんか尋ねました。","respondent":"浜脇住宅課長","answer":"倍率は４０倍ということですので、本当に１０年後にこの方々が返還しなければいけないんですけれども、言われております。","id":"exchange-009"},{"speaker":"菊地委員","kind":"意見","question":"今の部分で、１０年後、移れる経済状態にありませんといったときに、そのまま継続できる仕組みではないわけですよね。その際は強制的な退去みたいな感じになっちゃうのか、ちょっとそこだけお願いしますとの意見を述べました。","respondent":"浜脇住宅課長","answer":"まだ１０年たっていないんですけれども、ここをこうしろだとから、私どももこういうふうに持っていくという情報は持ってございません。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"２番の定期使用住宅（若年ファミリー向）というのと、４番の若年ファミリー向というのは、定期使用という意味なんですけれども、どういうことなのか、ちょっと教えていただきたいです。","respondent":"浜脇住宅課長","answer":"これについては先ほどの１０年後、４０歳未満が１０年以降、十分に住めるという状況になっています。資格がなくなる場合もありますけれども、このままいけば、そのまま住んでいけるということに違いがあると思われます。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"若年ファミリー向という場合には、三、四年前に始まったというお話があったんですが、両方ともそうなんですか。なぜ上のほうが１０年で、若年ファミリー向の１３戸が４０歳未満でずっと継続して入れるという、この制度の仕組みがよくわからないんですけど。","respondent":"浜脇住宅課長","answer":"ちょっと今、何年前から始まったというのが定かでないんですが、大体四、五年前というのが、私の覚えている範囲です。若年の４０歳未満で、１０年の入居制限がないということは、分けたと思われます。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"今、もう既に空きがあって、すぐ入れるということの戸数は１つもないんか尋ねました。","respondent":"浜脇住宅課長","answer":"都の場合にはある程度、空き家が発生するということを聞いておりますので、一般に当選するとかなりの確率で入れるということで、ある程度予測のついた数字が入っていると伺っています。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/825107?Template=document&Id=3832#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":12139,"voices":52}},{"id":"h17-20051102-9","meetingId":"h17-cm11","date":"2005年11月2日","dateIso":"2005-11-02","committee":"文教委員会","time":"午後１時０５分～午後２時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"平成１７年陳情第４号、区立小学校に関する陳情","agenda":"平成１７年陳情第４号、区立小学校に関する陳情","exchanges":[{"speaker":"松澤委員","kind":"意見","question":"その結論でいいのかどうか、ちょっと困っているんで、皆さんもそうだと思うのねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、どうしてなんだろうという非常に疑問がわくわけで、もう少し広い形で取り組んでいただきたかったなというふうに思っております。それから、本日これ以上長引くということはあまりよろしくないと思いますので、今回結論をとっていただきたいなというふうに希望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"山村委員","kind":"質問・要望","question":"私もいろいろと前回質問させていただいて、実際のところ、勘違いと思い込みを起こした陳情じゃないかと私は前回の説明から思っております。結局求められていることは、ご自身でやれるわけですから、結論を出したほうがいいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"南委員","kind":"意見","question":"２回議論して、委員長のほうで直接ご本人とお話しいただいたということで、委員長のご苦労もあると思いますので、お礼を申し上げたいと思います。そういうふうな方向でぜひ結論を出すか、あるいは継続かというところでお諮りほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"若林委員","kind":"確認","question":"その辺についてちょっとこの場で確認をさせてほしいと求めました。採択すると、こういうことでこういう効力が出て、趣旨はこうで、不採択は不採択か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"率直に言って、今の時代にナイロンというのは、やっぱり素材としては考慮すべきじゃないかというのが私の感じとしても思うところなんですね。非常に困っています、決め方でとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"大沢副委員長","kind":"意見","question":"委員長のほうのご努力、そして委員の皆さん方のお話、議論がありました。その中でも、やはりこれ以上議論を重ねるというよりは、今日ある程度の方向性だけは出しておくことが必要じゃないかと考えますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270991?Template=document&Id=4552#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":4102,"voices":19}},{"id":"h17-20051104-6","meetingId":"h17-cm11","date":"2005年11月4日","dateIso":"2005-11-04","committee":"区民委員会","time":"午後４時２２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/678828?Template=document&Id=2440#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":2630,"voices":7}},{"id":"h17-20051104-7","meetingId":"h17-cm11","date":"2005年11月4日","dateIso":"2005-11-04","committee":"厚生委員会","time":"午後１時０４分～午後４時５５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"の１、請願・陳情審査","agenda":"の１、請願・陳情審査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"都立病院改革マスタープランの６項目のご説明のところで、今回の都立病院の公社移管の目的がどう示されているのか、わかる範囲で教えていただきたい。それから、区民の利用状況がわかったら教えていただきたいのと、どのような影響があるのかわかる範囲で結構なので教えてほしいと求めました。","respondent":"谷田部健康課長","answer":"公社病院については、将来的には地域医療システム化の進展等を踏まえながら、順次完全な民営化を図ることを前提に経営形態を検討するとなっています。それから転送制度、逆紹介制度、地域医療への支援・拡充というところでの公社化のもともとの背景と私どもはとらえてあります。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区のところでも、多分公社化に関して意見を求められていたり、話し合いの場についているのではないかと思うので、特に区への影響とか、その辺については論議されているのか尋ねました。","respondent":"谷田部健康課長","answer":"公社化検討委員会がありまして、その中で私どもの関係部長がオブザーバー参加ということで、情報提供はその都度受けているです。今回一次医療と二次医療がより密接な連携を持つことによって、それぞれのところで十分な管理ができるのではないかという期待は一方で持ってあります。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"それから、産科のところで少子化の中で分娩数が増えているということも以前に伺って、地域において荏原病院の存在が重要であると考えています。そこが一番心配されているのではないかと思うんですけれども、その辺についてご意見はいかがか尋ねました。","respondent":"谷田部健康課長","answer":"現在の診療科もすべて継続します」ということが書かれてあります。それから「がん治療に一層積極的に取り組みます」ということで、新たに放射線治療を開始します」ということが書かれてあります。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"紹介状なしの一般診療が７０％ぐらい占めているというお話を伺いましたけれども、その辺が違っていたら言ってほしいと求めました。この辺が一次医療と二次医療の連携とか、充実はもちろんですけれども、今までどおり受けられるような地元の病院であってほしいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"川西委員","kind":"質問・要望","question":"二つ目は、そういう点で一般区民の方が理解するためには、一口か二口で言うと本当は何なのかということを教えてほしいと求めました。そういうことが便利にしてきた人たちにとって解決される問題が移管されてもあるのかどうか説明を求めました。","respondent":"谷田部健康課長","answer":"一言で説明するのは大変難しい問題がございまして、例えば東京都の公社化検討委員会がまとめた資料によりますと、ちょっと読ませていただきます。新荏原病院においても、医療連携を一層推進していくために確実に紹介、返送、逆紹介を実施することで…","id":"exchange-005"},{"speaker":"山路委員","kind":"意見","question":"陳情事項の２番目、紹介状なしでも受診できる現行診療システムの維持など」ということですけれども、現状はこのままになっているわけですね。そこを説明していただけますかとの意見を述べました。","respondent":"谷田部健康課長","answer":"原則として、４７.５％の方が何らかの形で紹介をされて荏原病院に来ているということでございまして、紹介状がなくても今までどおり診察をする。５２.５％が紹介状がなくても診察をしているですので、現行の方法で今後も診察を行っていくというのが東京都の考えです。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"目黒区、世田谷区が入っているとなっていたのですけれども、この中には品川区も入っていたのでしょうか。それから、今回公社化にすることによって、東京都の財政は荏原病院に関してどういうふうに変化するかわかったら教えていただけないか尋ねました。","respondent":"谷田部健康課長","answer":"運営協議会のことですけれども、私どもが手元にある公社化検討委員会のまとめは９月にされまして、その中に運営協議会の設置という項目があります。委員長の諮問機関として設置し、運営方針、運営協議会を委員長の諮問機関として設置し。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどから紹介状なしでも受診できるということで、答弁もありましたけれども、その辺の実態はどうなるのか教えていただきたい。今まで夜勤は３人体制でやっていたのが２人体制になっていくとか、二名で、職員体制がどうなっていくのかわかりましたら説明を求めました。","respondent":"谷田部健康課長","answer":"東部地域病院では４,２００円ということで、この値段がつけられているそうです。それぞれ運営する側の責任でやるわけですので、職員体制がどうなるかというのは、区としてはお答えできない部分だろうと思ってあります。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どうなるかわからないということですけれども、１,３００円が４,２００円になったら、これは患者サービスとは言えないのではないかと思います。この辺の検証もぜひしてほしいと求めましたし、今の都立病院をそのまま維持充実させていただきたいという要望をさせていただいて終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今年１２月に都議会で存続にかかる決議が行われると言われていますので、ぜひこの場で結論を出してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"須藤委員","kind":"質問・要望","question":"今日、初めて見させていただいた陳情なので、内容的にもう少し精査をさせていただきたいと思うので、継続してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"本多委員","kind":"意見","question":"陳情は二つの項目が出されておりますけれども、２番目についてはこれまでの質疑、説明で十分これからも維持できるという把握ができました。１番目の陳情項目については、抜本的なところですので、品川区議会として、この委員会として本日結論を出すべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"川西委員","kind":"質問","question":"私は先ほど質問をいたしましたように、医療行政について未熟ですので、もう少し出された方の意向、それからいろいろなことを含めて継続でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"山路委員","kind":"意見","question":"荏原病院の移管の件ですけれども、都議会のほうでもいろいろ審議をやられまして、地域医療との長年のつながり的にも問題ないと思いますので、今の流れでいいと思いますから、結論を出していただいていいという判断をしているわけでありますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"都知事あてに４万６,０００筆の署名が届いています。地域医療としての要求に沿った病院の存続をしてほしいという声が多数届いておりますので、要望を出していきたいと思っていますので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"本多委員","kind":"意見","question":"先ほども少し述べたのですが、特に陳情の１番目の項目、「都に慎重に再検討するよう都に要請してください」というところですが、これまでの説明と今後の公社移管にかかわる方向で、もう方針が出ておりますので、その内容でいいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"川西委員","kind":"質問・要望","question":"陳情の要望に沿って区として要請を出すというところに主眼があるようですので、結論を出しても賛成です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほどお話ししたように、内容的なものがいろいろ状況がわかっていないので、都もある程度形をつくってきたと思います。それを変えさせることの要望をということだけれども、私自身は先ほど言ったように継続でと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"}]},{"id":"topic-02","title":"の２、報告事項","agenda":"の２、報告事項","exchanges":[{"speaker":"飯沼委員","kind":"確認","question":"保育園在園ではなく、地域の子どももかかわるのですよね、その点を再確認したいと思います。それから、受付時間が書いてありますが、各保育園というのはすべての保育園なのか、実施園で受け付けるのか、その辺をもう１回説明を求めました。","respondent":"小林保育課長","answer":"内容につきましては、特に変更をしません。それから、受け付けにつきましては、すべての園と保育課で夕方７時まで、該当期間中受け付けをしてまいります。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"特に、体制的に私が率直に感じるところは保育園は余分な人員がいないので、このときだけ体制が特別に取られるのでしょうか。保育しながら電話が何回も鳴ると大変だなと思ったのですけれども、その辺の体制は特に問題ないのか尋ねました。","respondent":"小林保育課長","answer":"保育課につきましては、夜間窓口と申しますか、時間を延長して行いますので、その分は入園相談係の人員で対応しております。現在７時半まで各園ともに延長保育に取りくんでいる状況ですので、対応している人員で基本的には昨年は問題なく対応できたと承知しております。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"平成１７年度、平成１８年度を比較しますと、ここに関して質問をしたいと思います。８月のモデル事業でというご説明の算定だったのですけれども、どのようなサービスが具体的に受けられるのか、この点について説明を求めました。","respondent":"早津高齢福祉課長","answer":"要支援は今まで１本でしたのが、要支援１・２という新しい区分をそろえて、要介護の５段階とあわせて７段階の認定が行われるというものです。予防給付のケアプランは新しくできる地域包括支援センターが基本として行うということになっておりますが。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"自分は一体どういうサービスになるのかというところが、大変心配さているので、そこのところをもう１回お答えをいただきたい。それから、これは４月１日からの移行ということでしょうか、そこも説明を求めました。","respondent":"早津高齢福祉課長","answer":"今現在では、私どもは今申し上げたような認識でおります。それから、認知症と給付請求の状況にあるか云々ということが、主治医の意見書の中には項目として反映されているというような変更点があります。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"意見","question":"これをすべて地域包括支援センターのところでチェックしていく体制ができているのかどうか、その点を一つ。自立のための家事援助のところに、例えば期限が何箇月とか区切られるようなことがあるのかどうか、その点も心配なので聞かせてくださいとの意見を述べました。","respondent":"早津高齢福祉課長","answer":"ケアプランのチェックができるかですが、予防給付について平成１８年度は３,１８７件を予定しています。これは裏返して言えば、必ずそれが受けられるわけではなく、従来よりその辺の制約が出てくる可能性があるだろうと考えています。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２９ページのデイサービスですけれども、今までどおりにデイサービスを利用できるのかどうか、ここを教えていただきたい。３２ページの訪問リハビリテーションのところですが、なぜ訪問リハビリテーションのところが減っているのか、ここも説明を求めました。","respondent":"早津高齢福祉課長、上山介護保険担当課長","answer":"まだ示されておりませんので、要支援系の軽い方については、月額定額方式を導入されるのではないかということが議論をされております。病院でないとできないということになりますが、増えておりますのは周辺のところも含めて… ７月付の実績、１カ月分だけの実績によるものですので、今掲げている数字よりさらに低くなるという予測をしております。したがいまして、平成１７年度から１８年度の数字が減るということの理解は…","id":"exchange-024"},{"speaker":"川西委員","kind":"質問","question":"多様化する中で委員会の回数も、認定会議の回数も増えるのであろうかと予想されますが、その辺はどういうふうに見込んでいらっしゃるか伺います。それから、３５ページ、夜間対応型訪問介護の中身をお願いします。","respondent":"早津高齢福祉課長","answer":"介護保険制度推進委員会ですが、説明でも申し上げましたように、さらに二つの機能が付加されます。夜間対応型訪問介護というのは、２４時間型のホームヘルプサービスは定時巡回を基本としております。","id":"exchange-025"},{"speaker":"川西委員","kind":"質問","question":"一つだけ再質問は、今後またありますが、任期２年で同じメンバーでずっと通していらっしゃる方は何人ぐらいいらっしゃるのか伺っておきます。後で聞きますから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこに１カ所ずつぐらいとか、そういう計画があるのかどうか、そこを教えていただきたいのが一つ。もう一つ、基金の使い方について国の指針といったものがあるのかどうか、その辺を説明を求めました。","respondent":"早津高齢福祉課長、上山介護保険担当課長","answer":"小規模多機能についての見込みはですが、先ほどの説明のとおり、こういう見込みを立てたものです。基本的には４１ページの(5) の1)にありますように、総介護費用を見込んだ上で、掛ける１９％となっております。 先ほどの介護保険制度推進委員会の継続している委員の数ですけれども、第二期の委員として１７名おりまして、そのうち７名が継続しております。平成１８年６月３０日までですが、それぞれ推薦を依頼したり…","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"資料２の先ほどの基金のところですけれども、第二期の積み立てと取崩しの額を、平成１５年、１６年、１７年度のところを改めて教えていただきたい。先ほど、第三期の取崩しの額が出ていたのでしたか、ちょっと聞き漏らしたので、第三期の取崩しがどのぐらいの予定なのか、もう一度説明を求めました。","respondent":"早津高齢福祉課長","answer":"足りなかったのが８,０００万円ぐらいだったはずでありまして、平成１７年度は２億円ぐらい不足するだろうと、そういう予測です。第三期におきましては、５億３,０００万円ぐらいの取崩しを予定しているです。","id":"exchange-028"},{"speaker":"須藤委員","kind":"質問","question":"３７ページの施設サービスのところでお伺いします。現実に我々は聞いているので、そういうときにはどういうふうにされていくのかなという思いがあるので、そのあたりを聞かせてください。","respondent":"早津高齢福祉課長","answer":"改めて施設サービスはどういうものが必要であるのかということを考えるべきものではないかと、こんな認識の中で全体像を考えているものです。実は頓挫するという例もかなりありますけれども、それは具体的なお話を逐次お聞きする中で…","id":"exchange-029"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、いろいろな組み合わせというのを今後の見込みの中へ考えていただきたいのと、施設サービス自体も現状が今のままで本当にいいのかなと。ケアという考え方ができているので、それに対応するような今後の見込みという形で考えていただきたいと思うんですが、いかがか尋ねました。","respondent":"早津高齢福祉課長","answer":"私どもも注視しているつもりですけれども、それ以上に多様化のスピードが早まり、また進展のスピードも早まるだろうと考えております。そういう意味では、敏感なアンテナを張りながら、今後の施設サービスも含めたあり方というものは常に検討してまいりたいと考えております。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"例えば、配食サービスとか、今回改めて介護保険の中に新しく介護保険として入ってくるものはどんなものがあるのかということを一つ教えてください。品川区は庁舎に１カ所置くということですけれども、地域包括支援センターが現在どんな体制になっているのか、そのことについて説明を求めました。","respondent":"早津高齢福祉課長","answer":"要介護１・２の方でも、そちらの方を対象としたリハビリ事業として今後も進めていくために、身近でリハビリという事業は残します。地域包括支援センターの体制ですが、先ほど申し上げたように、両方の体制で地域包括支援センターの体制を組むということになります。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"国会の初めの頃の議論の中で、丸々３年間入らないことになったのか、今回の区民健診は第三期の事業費の中に関係ないのか確認をさせてください。社会福祉士が１名、主任ケアマネジャーの体制はどうなっているのかお聞きしたかったので、ブランチの体制もあわせて説明を求めました。","respondent":"早津高齢福祉課長","answer":"ただし、これは６５歳以上の区民健診を介護保険制度の中に取り組んだときのことを想定しておりまして、少なくとも来年１年間については。地区の在宅介護支援センターにおきましては、在所のケアマネジャーたちが連携して地域包括支援センター業務にあたるという体制です。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２年目からは介護保険財政の中に入ってくる可能性が決まっているのか、そこのところを教えていただきたい。地域包括支援センターの考え方でいいのかどうかというところがよくわからないので、そこのところをあわせてお聞かせほしいと求めました。","respondent":"早津高齢福祉課長","answer":"区民健診の１年目については申し上げましたが、２年目以降についてはこれから検討していく中で結論が出てくると考えております。そこの相談の内容の中で、個別の対応をしていくという選択がよろしかろうと、まず大きく考えたものです。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"予防給付のケアプランですが、在宅介護支援センターがそれをチェックするという仕組みになるのでしょうか、そこのところを一つ。それから、平成１７年度は１,４６１件で２２.８％まで増えてきている状況が示されていますが、そういうものはどうなっているのか説明を求めました。","respondent":"早津高齢福祉課長","answer":"ただし、地域包括支援センターがつくるという原則ですので、内容のチェックについては地域包括支援センターが行うという構成になっております。ただし、今申し上げたように地域包括支援センターでのチェックがかかってまいりますので…","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この差は４００円ありますけれども、品川区の場合は１０５円ですが、どうして国との差がこれだけあるのかということを一つお聞きしたいと思います。それから、その辺の考え方では、有料老人ホームについてはどう考えられているのかもあわせてお聞かせほしいと求めました。","respondent":"上山介護保険担当課長、早津高齢福祉課長","answer":"介護予防事業の効果につきましては５％程度と見込みまして、若干国と比較しますと、予防効果を低く抑えた見込みをしているものです。そのために今回の保険料月額の推移した場合の金額と見込んだ金額が… 今説明したとおり、予防の効果について国ほど見込んでいないというのが一つですが、区の４,２３０円というのが。２９人以下の有料老人ホームを設置したいといった場合、この地区は既にありますので…","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほども飯沼委員からもありましたけれども、要介護１の認定を受けている方がどういう形で、いつ移行していくのかということが一つ。デイサービスとか、半年とか何年とか期間の限定なしにケアプランでされれば受けられるのかどうか、そこのところも教えてほしいと求めました。","respondent":"上山介護保険担当課長、早津高齢福祉課長","answer":"私のほうから介護給付費準備基金についてお答えいたします。制度そのものも３年に一度ずつ見直しがされるものですので、推移な見ながら基金の活用については検討してまいりたいと考えております。 認定変えをしたときに、要支援１とか２になりますと、簡単に言うと４月１日を期して一斉に変わるということではありません。ただ、介護報酬の関係が出てくるのが、今後の話になってまいりますので…","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"保険料も今回一気に６００円値上がりというのは、介護保険が一気に６００円上がるというのは、本当に大変なことだと思うんです。そういう点では、ぜひ基金もさらに取り崩していただいて、もっと安いというところでご検討をいただきたいという要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]},{"id":"topic-03","title":"所管事務調査にまいりますが、関係理事者以外の方は自席待機で結構でございます。ご苦労さまでした。 それでは、予定表の３、所管事務調査","agenda":"所管事務調査にまいりますが、関係理事者以外の方は自席待機で結構でございます。ご苦労さまでした。 それでは、予定表の３、所管事務調査","exchanges":[{"speaker":"川西委員","kind":"質問・要望","question":"一つは、いろいろ改革の将来像をお考えいただいてありがたく思いますが、相談機能の強化・充実の点で内容をご説明してほしいと求めました。","respondent":"辻田児童課長","answer":"そういう中で、それから児童の問題、そういうものに対して直接対応できる資質を向上させて対応していかなければならないという現実があると思います。相談事業というのは非常に連携を持っているわけですけれども、具体的なサービスにつなげていくという形で…","id":"exchange-038"},{"speaker":"川西委員","kind":"質問","question":"どうやって気持ちを開いていくかというものもありますから、研修を受けた人の配置とか、そういうことが地域の中に必要だと思います。ですから、この辺についてはいかがか尋ねました。","respondent":"辻田児童課長","answer":"そういうものにつきましては、どちらかと言えば児童センターの職員等は専門部分ですので、十分その辺については対応していけるです。それから、守秘義務の問題ですけれども、後に出てくる要保護児童地域調整会議につきましても…","id":"exchange-039"},{"speaker":"川西委員","kind":"質問・要望","question":"要望だけ申し上げます。その運営も結構ですけれども、適切な場所に非常勤で相談できる体制を抱えていくということが必要だと考えていますので、要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"本多委員","kind":"意見","question":"学童保育クラブは７５％ぐらいだと思うんですけれども、平成１６年度は人件費２５％前後だと思うんですけれども、まず説明を求めました。","respondent":"辻田児童課長","answer":"もう既に取り組んでおりますが、多彩な人材を活用するということで、児童センターの中にもいろいろな形の人たちが働いております。違った形での人材活用を図ることによって、サービスを向上させながら、人件費部分を抑えていくという形での努力はしています。","id":"exchange-041"},{"speaker":"本多委員","kind":"質問","question":"０歳から１８歳までの、１８歳までのＰＲといいますか、その辺はどのように取り組んでいくのか説明を求めました。","respondent":"辻田児童課長","answer":"もう一つ、子育て応援携帯サイトを今回１１月１日から立ち上げました。こういう形での広報媒体を使うことによって、パソコンではなくて携帯電話でいろいろの情報が取れるという形での工夫もしています。","id":"exchange-042"},{"speaker":"山路委員","kind":"質問・要望","question":"孫が３歳になりまして、一時３歳になるちょっと前ぐらいから、悪いしということで悩んでいたわけです。子育て支援という一つの核ですけれども、統一したものになっていくのか、その辺の将来の見通しについて聞かせてほしいと求めました。","respondent":"辻田児童課長","answer":"その中で、特にいろいろな地域の方々と連携する中で、子育ての輪を広げていくということが一番大事ではないかと考えております。特に、今後も児童センターに招いてお話しを聞く会などもやっていくことも、地域特性を生かした館運営になるのではないかと考えております。","id":"exchange-043"},{"speaker":"山路委員","kind":"質問","question":"まさに、よく同じ世代の子ども同士で遊べるようになったというのが、今説明されたとおりだと思います。ライフステージに対応した事業の充実ということで、小学生事業の再構築と書いてありますけれども、ここをお聞かせいただけますか尋ねました。","respondent":"辻田児童課長","answer":"そういうことから、すまいるスクールではできない異年齢間との交流事業が、これからは児童センターの中の小学生の事業として出てくるのではないか。昔ありましたがき大将がいて、遊んでいろいろなことを学んでいくことが一つ児童センターの中でつくり出せればと考えております。","id":"exchange-044"},{"speaker":"山路委員","kind":"質問","question":"２回説明をしていただきました。異学年というのはいじめがなくなると、随分前から言われておりましたけれども、幼児と小中学生の交流も児童館によっては可能か尋ねました。","respondent":"辻田児童課長","answer":"これは保健所でも実施しておりますし、児童センターの中でも現在実施しています。今後、どういう形で拡大していくかということにつきましては、今後十分検討していきたいと考えております。","id":"exchange-045"},{"speaker":"須藤委員","kind":"質問","question":"それから、町会等ではどういう位置づけにされていくのか。そういうものとの関係はどういうふうになっていくのかと思うんですけれども、いかがか尋ねました。","respondent":"辻田児童課長","answer":"すまいるスクールや何かとはいろいろな形で連携を取りながら、お互いに特徴を生かした形で事業を実施していこうという話し合いは持っております。地域との連携の一番の基本となるような事業につきましては、ＰＲおよび周知を関係者の方々に広くしていきたいと考えております。","id":"exchange-046"},{"speaker":"須藤委員","kind":"質問","question":"そういうものがダブったり、子どもがどっちに行っていいかという話がいろいろ聞こえてきたりするので、そのあたりのところを上手に連携を取りながら。どうしても教育との関連、過保護のサービスが入ってきてしまうというような感じもするのだけれども、そのあたりはいかがか尋ねました。","respondent":"辻田児童課長","answer":"例えば児童センターは１３地区に分けまして、町会との連携というのはお祭を通してですけれども、児童センターの館長はやっております。地区委員とかいろいろな方たちが子どもに対して係わっているところで、調整部分も早急に検討していかなければならないと考えております。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"意見","question":"委員長にお願いですけれども、一応表からは読めますけれども、ここから一体どんな論議を導き出していったらいいのかというところで悩むんです。こういう事業にこのぐらい予算をかけてこういう効果がありましたという…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、そういう評価の仕方、とらえ方の違いかなとも思うんですが、ぜひそういうふうにしていただきたい。児童センターの改革はどこの部分でどういうメンバーが参加されて行われているのか、今どの辺にあるのか、お聞かせほしいと求めました。","respondent":"辻田児童課長","answer":"児童センターの将来構想、児童センターの改革という形のことを平成１５年、１６年にかけて実施しております。改革検討委員会につきましては私がトップということで、引き続きもう少し具体的な形で検討されているです。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"このところ子育て支援では保育園はもちろんですけれども、保健所も、児童センターもいろいろな部分で求められてきています。そういった面も含めて、あらわせないかと思っているんですが。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"須藤委員","kind":"質問・要望","question":"今後どうあるべきかという、いろいろな連携をどう構築していったらいいか考えていくのが所管事務調査だと思うので、理事者は考えていますよと。今日は時間もあれなので、そろそろというようなことを思いながら整理をしていただきたいと、お願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ、次には具体的な資料を求めていきたいと思いますので、よろしくお願いいたします。地域の方のところもどんどんご意見を入れていくようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"川西委員","kind":"質問・要望","question":"差し出がましいんですけれども考えていただきたいのは、自分で認識しながら、今日の委員長の答弁を支持したいと思います。新児童センターの構想に対して、どういうものを我々が提言していくかということを、これからの委員会運営の中で発言していく必要があると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/948006?Template=document&Id=3126#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":57381,"voices":125}},{"id":"h17-20051104-5","meetingId":"h17-cm11","date":"2005年11月4日","dateIso":"2005-11-04","committee":"総務委員会","time":"午後１時０４分～午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"を議題といたします。 特別区人事委員会勧告の概要","agenda":"を議題といたします。 特別区人事委員会勧告の概要","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと確認しておきたいのは、職員組合のほうとの話し合いがどうなっているかということが一つ。具体的にどういうものが検討されているのか、その中身がわかったら、教えてほしいと求めました。","respondent":"桑村人事課長","answer":"この内容を実施する、給与構造の変革等も、平成１８年４月１日から実施したいという提案をしています。やはりどうして、給与表を変えない限り、１２月にはなかなか実施が難しいということがありますので、そういった関係です。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問・要望","question":"４ページの勤務環境の整備のところなんですけれども、子育て支援のところでは、３００人以上の企業での義務づけがあります。人事院の検討している内容だとか、そういうのがあったら、ちょっと教えてほしいと求めました。","respondent":"桑村人事課長","answer":"先ほど言ったように、制度をつくっても、それをどうやって実施するかというようなことなんだろうと思います。一定のものよりも、ある意味で、次世代を育成していくんだという考え方が必要なのかなと思ってあります。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"意見","question":"そういう意味では、遅出早出ということだけではなくて、やっぱり残業をしっかり規制していくとか、そういうことなんかも必要かなと思います。そういうふうな実効ある内容を期待しておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"心の健康づくりという中で、２３区の数字が、先ほど示されたんですが、品川区の中でもやっぱりそういう傾向が出ているのか、どうか。その点を、まず教えてほしいと求めました。","respondent":"桑村人事課長","answer":"先ほどは、２３区全体の数字ですが、品川区については、平成１３年が、そういう方が７人、平成１６年が１０人です。平成１７年については１０人を超していますので、今は、心の健康で辞められる方が半数を超えているような状況です。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"同じところの２番、皆さんお名前を書かれて、土日に実際にお仕事に携わっているということを感じるんです。土日の勤務ではないのか、扱いとしてはどうなるのか、その辺はどういうふうに考えたらいいのか、ちょっと教えていただきたい。","respondent":"桑村人事課長","answer":"やはり健康の面でも問題があると考えていますので、土日に来るとしても、その分ほかの日に休んでくれるよう勧告しています。もちろん、超勤になったりする場合もあるでしょうけれども、基本は振り替えということになっております。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"意見","question":"結局同じことになってしまうんでしょうし、非常に難しいなと思うんですけれども、その辺はうまく考えていただければなという思いはありますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"藤田委員","kind":"質問","question":"ですから、一般区民から見ると、下がったときは、それからだし、本来なら４月までさかのぼって引下げをするのが筋じゃないかなと思うんです。その辺、どういうふうになっているのか、ちょっとお聞きしたいと思います。","respondent":"桑村人事課長","answer":"実施時期の次のところに出ていますように、実施時期までの月給の月数と、来年３月の期末手当から落してしまう。国が８月ぐらいに出すわけですけれども、検討してやると、どうしても１０月になってしまうのかなと。","id":"exchange-007"},{"speaker":"藤田委員","kind":"質問","question":"これは、仕事上のことが原因で心を傷めるというんでしょうか、私的な部分のものなんでしょうか。品川区としては、仕事上のことなのか、その辺ちょっとお伺いしたいと思います。","respondent":"桑村人事課長","answer":"そういう意味では、これが複雑になっているがゆえに、なかなか治らないというんですか、そういうことが多いのも事実です。なかなか難しいと思うんですけれども、そういった方法がないと、なかなかそのものを吹っ切って出勤するのは難しいと思っています。","id":"exchange-008"},{"speaker":"藤田委員","kind":"質問","question":"しつこいようなんですが、療養期間中の給与体系というのは、どういうふうになるんか尋ねました。","respondent":"桑村人事課長","answer":"の１年間は、いわゆる無給になります。共済組合からも８割出ると考えますので、３年間は、８割が保証されるということです。","id":"exchange-009"},{"speaker":"本田委員","kind":"提案","question":"いろいろな改革提案も出されておりますけれども、将来的には、いつまでこの方式でいくのだろうかということ。その辺のポイントがあれば、お聞かせいただきたいと思うんですとの意見を述べました。","respondent":"桑村人事課長","answer":"２３区それぞれ別々でありますし、またそれが当たり前だという考え方を持っていますので、そういった制度が必要なんだろうと思ってあります。もう２年先になります、人事制度をつくっていくかというようなことの自主性が、少し打ち出されているかなという気もしています。","id":"exchange-010"},{"speaker":"本田委員","kind":"提案","question":"２３区統一の労働条件に関する重要な問題ですから、一括でいくべきだということなのか、足並みはそろっているんでしょうか。今度の中では提案はされておりませんけれども、改革すべきところもあるのかなというふうには感じるんですけれども、そういう議論はあるんか尋ねました。","respondent":"桑村人事課長","answer":"このような形を検討しろと言っているわけでございまして、国が一定のところを、多分検討するようになるんだろうと思います。なかなかうまくできないと答えていたんですが、国や他の団体の動向を踏まえて、検討するという言い方に変わりました。","id":"exchange-011"},{"speaker":"本田委員","kind":"質問・要望","question":"サービスの向上に努力していくという事業展開を求められているときですから、そういう点で、なお一層のご努力をお願いしたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"高星委員","kind":"提案","question":"新たにこれから起こってくるであろうサラリーマン大増税も含めて考えたときに、人事委員会の考え方って、これでいいんですかとなる。私は非常にわからないんですけれども、その辺の注意するところってないんですか、どうなんか尋ねました。","respondent":"桑村人事課長","answer":"あるいは、区民サービスに努める人間というのは、きちっと評価しようじゃないかという考え方なんだろうと思います。先ほどから言っているように、これを各区がどういうふうに使っていくかということが問題なのかもしれないと思っているところです。","id":"exchange-013"},{"speaker":"高星委員","kind":"質問","question":"さて自分たちはどうするんだみたいなところで、そういったものを、わかりやすいようにしていくというのが筋なんじゃないかと思うんです。国の財政がこういう情勢ですから、それをいろいろな意味でしわ寄せが来ているわけですから、どうか尋ねました。","respondent":"本間総務部長","answer":"例えば、今の次世代育成支援のようなものにつきましては、そういうような連鎖が、今までもございました。区は、品川区としてきちんとした人事行政の対応を図っていきたいと考えているところですので、よろしくお願いいたします。","id":"exchange-014"}]},{"id":"topic-02","title":"所管事務調査に入ります。 本日は、契約事務","agenda":"所管事務調査に入ります。 本日は、契約事務","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"基本的なところで教えていただきたいんですが、どのぐらいの時間的な流れ、日にちの流れというのはどうなっているのかなという点。何回ぐらい開かれたのか、あるいは、テストだからやっていないというのかもしれないし、ちょっと、その辺のところだけ説明を求めました。","respondent":"鷹倉経理課長","answer":"申請に係わる業者への説明ですが、１社当たり２名か３名かに集まっていただいて、全体の場で説明した経緯がございました。システムが、できるだけ間違いのないような形で使っていただきたいと、利用度のいいような形にしていきたいと考えておるところです。","id":"exchange-015"},{"speaker":"原委員","kind":"意見","question":"今の電子入札のほうなんですけれども、各企業の反応なんですが、現状は、いろいろなところで希望が出てきているのかなと思うんですが、全体としては、抵抗があるとか、ないとか、そういう部分がおわかりになることがありましたらとの意見を述べました。","respondent":"鷹倉経理課長","answer":"ただいろいろ相談だとか、要望等は聞いていただくと、こういう話です。その辺も含めて、細かく吸い上げながら、体制をつくっていきたいと考えておるところです。","id":"exchange-016"},{"speaker":"三村委員","kind":"質問","question":"電子入札のほうの、電子証明書でということだったんですけれども、この辺にかかる業者の手間とかというのは、そんなに難しい手続ではなくできるのか、その辺をお聞きしたいんです。","respondent":"鷹倉経理課長","answer":"それから、民間業者で２社ほどありますが、そこで証明書を取るという形の流れになっております。慣れれば、そんなものかということだと思うんですが、そういう流れになってあります。","id":"exchange-017"},{"speaker":"三村委員","kind":"質問","question":"全く松阪市と同じようなシステムということですか。だから、インターネット上だけでも完結できるようなシステムにしていったほうがいいのではないかというのがあるんですけれども、いかがか尋ねました。","respondent":"鷹倉経理課長","answer":"先ほど申し上げましたとおり、早急にそういう流れに移ってきた中で、慣れていただくという意味もありますし、こういう形を利用しているわけですけれども、目指す方向は、ということです。","id":"exchange-018"},{"speaker":"三村委員","kind":"質問","question":"せっかくシステムを入れていく以上、ある程度、ボリュームをもって、電子入札のほうはきちんと稼働していくようにしていくべきだと思っているんですけれども、目標設定とか、どの程度の割合を、そっちのほうに移行していくとかというお考えはあるんか尋ねました。","respondent":"鷹倉経理課長","answer":"私ども、今回、共同で開発したとはいえ、当然、一定のコストがかかってあります。随時減らしていかなきゃいけないですので、このシステムをフルに活用して、早急に良い状態に持っていこうと考えているところです。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１１月から始まったということで、９月からテスト実施等をなさっていたというお話だったんですけれども、ホームページの中にうたわれていたんですか。その辺はどうなんか尋ねました。","respondent":"鷹倉経理課長","answer":"今回、１１月４日付で、ホームページで見られる段階に、きょうなっています。まだちょっと確認していませんが、そういう形でお知らせするような流れになってあります。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１１月ごろから始まるということ自体が出ていたかどうか、電子入札になりますということが掲示されていたわけですか、６階のほうには。","respondent":"鷹倉経理課長","answer":"こちらには、掲示されていたということは、確認してみます。テストの段階で、こういう形でやりますよということで、大きな話はもう既にしていますので、その部分では、周知は行き届いていると考えています。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"どうかと、公平性という点では、ちょっと対応しきれないんじゃないかなという思いが一つありました。２０番の入札期間のところで、今までと同じような形のものを、そのまま入力すればいいということなんか尋ねました。","respondent":"鷹倉経理課長","answer":"総務委員会でもお話が何回か出ているんですけれども、いわゆる、談合防止の一つという形で必ずつけていただくという形のものです。電子ベースになったときに、やはりこれは制度上不可欠ということで、従来のようにつけていただくという流れになっています。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"意見","question":"当然、つけてもらっていいんですけれども、今まで手書きか、パソコンなどでやっていたと思いますけれども、そのまま写せるような状態、要するに、あまり作業的に変わりがないのかどうかというのは、そこら辺だったんですけれどもとの意見を述べました。","respondent":"鷹倉経理課長","answer":"作業的には全然同じです。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"意見","question":"４番の履行場所の住所が違っているはずです。これは、消しておいていただいて結構ですとの意見を述べました。","respondent":"鷹倉経理課長","answer":"こういうことのないように、ご指摘の話だと思うんですが、その点、気をつけてまいりたいと思います。","id":"exchange-024"},{"speaker":"中島副委員長","kind":"質問","question":"あそこの市では、非常に前向きに、そして目的にきちんと５本柱というのを立ててやっていたわけでなんです。品川区としては、どうなんか尋ねました。","respondent":"鷹倉経理課長","answer":"品川区の場合、今まで、内部的にきちっと積み上げて、地道ながらきちっときている。大きく宣伝していくということではなくて、地道に、確実にやっているですので、その辺のところをよろしくお願いします。","id":"exchange-025"},{"speaker":"中島副委員長","kind":"質問","question":"区内の業者の方から、品川区も談合があるんだという声を何度か聞いたんですが、そういったものというのは全然ないんでしょうか。ここで聞くのは、ちょっと違うのかもしれないんですけれども、そういう声というのは、区のほうには届いてないんか尋ねました。","respondent":"鷹倉経理課長","answer":"明らかに談合があったというようなときには、去年ございましたが、公正取引委員会のほうに通報していることがあります。確実に調査をし、事情聴取をしていくということによって、そういう噂をなくしていくと考えているところです。","id":"exchange-026"},{"speaker":"中島副委員長","kind":"質問","question":"松阪市の場合は、一同に介することをしないことによって、談合が阻止できるということなんですが、果たしてそうなのかなという疑問もあるんですが、その辺はどうなんか尋ねました。","respondent":"鷹倉経理課長","answer":"確かに、現場説明だとかという形で、一同に介する。これはやっぱり、精査して見ていくということになります。","id":"exchange-027"},{"speaker":"中島副委員長","kind":"質問・要望","question":"ときおり、私もいろいろな契約の金額なんかを見ると、やはり落札されたところというのは、独特の数字が出ているような気がしちゃうときがあるものですから、やっぱりこの辺のところは、しっかり今後も検討課題の中に入れていっていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"藤田委員","kind":"質問","question":"そうなると、どういう対策というか、歯どめというんですか、経理課のところではとられるのか。もう一つは、電子入札ですから、その業者がいろいろなところに参加できるわけですよね。","respondent":"鷹倉経理課長","answer":"二つご質問いただいて、まとめた答えになるかどうかあれなんですが、まず１点目は、区内業者ということで、支店なり、本店なりがあって、それが実体がどうなっているかというお尋ねかなと思うんです。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の延長の質問なんですけれども、全体で２１億円のコストがかかっていると出たんですが、品川区の負担というのはどのぐらいになるんか尋ねました。","respondent":"小野情報システム課長","answer":"これを５年間でやりますが、品川区で各１年間、おおよそ１,０００万円です。開発経費と、５年間の運用経費をやるということですので、５年間ですから、５,０００万円という形になります。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"セキュリティ部門になると、全く別の会社が入ると、パターンが全然変わってしまう。その辺の問題というのは、先々の話ですけれども、気になるんですけれども、どうか尋ねました。","respondent":"小野情報システム課長","answer":"平成１６年度から一応契約が始まりまして、平成１７年４月から平成１７年度になっておりますが、ここの１社と契約しているという状況です。それなりのノウハウがこういう部分の中で広まっておりませんので、現実的には、同じものがいくのではないかと考えております。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594587?Template=document&Id=1700#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":41120,"voices":101}},{"id":"h17-20051107-11","meetingId":"h17-cm11","date":"2005年11月7日","dateIso":"2005-11-07","committee":"自治制度特別委員会","time":"午後１時０５分～午後３時３５分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査の(1)都区制度改革・主要５課題に関すること","agenda":"特定事件調査の(1)都区制度改革・主要５課題に関すること","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"最後のところからちょっとお伺いをしたいんですが、何となく見る感じではできそうもないわけで、どういうところをお考えになっているのか。もちろん４０人で計算しているんですが、そういうことも考えたり、ここら辺の学校数をどういうふうに算定してまず出されたのかを教えていただきたい。","respondent":"日下部企画財政課長","answer":"じゃあ、なかなか詰めを進めていくことも非常に難しいのではないかということもありまして、現時点ではこのままでは財調協議には入れないと。そのまま棚上げにしておくわけにはまいりませんので、できるだけ早い段階で、このようなことではないかというふうに認識をしています。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"品川区ではそれを特別区にどうやって答えたのかというのがわかれば教えていただきたいのと、じゃあ、都区協議会へ持っていってしまう。なかなか都の代表質問等も見させてもらったら、そこら辺のところもどうお考えなのか、わかれば説明を求めました。","respondent":"日下部企画財政課長","answer":"その辺も含めて何とか打開の道筋を見極めていくといいますか、最大限の努力をしていくということになるのではないかと、このように考えております。先ほどの先般の第３回の定例会で、非常にその辺の対応にいろいろ苦慮しているといいますか、そんな話も聞いているところです。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問","question":"そこがわからないんだけれども、それを教えてほしいのと、そういう議論がないなら。これはもう１回改めてちょっと言っているんだけれども、そこら辺はひどいことを言ってきても、そこら辺の考え方をもう１回教えてほしいです。","respondent":"日下部企画財政課長","answer":"あるいはまた、そういう大きな流れの中でこの問題をしっかりとらえていかない限りは、なかなか解決は難しいかなというふうに考えています。区側の主張のところを見ていただいても出てまいりますけれども…","id":"exchange-003"},{"speaker":"石田委員","kind":"意見","question":"何かやってほしいなというお願いと、どうも私なんかは、そこを打破するためにはどうしたらいいのかなと。行政同士でお互いの主張をしても、それであとはお願いというところにどうしても行き着きそうな気がするので、これはお願いというか意見になりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"塚本委員","kind":"質問・要望","question":"そこをどう見るかということをひとつ教えてほしいのと、もう１つの見方として、２３区の主張がここにどうやって反映されていくのか。ここで交渉したことが２３区にどうやって戻ってくるのか、今、その辺ももう少し詳しく教えていただきたい。","respondent":"日下部企画財政課長","answer":"もともとが財調協議会は集中審議に入る前には都区検討会ということで、各区の財政担当課長レベルでの検討組織、各３つの分科会に入りまして。トータルで考えますと、私自身としては、今のところ都側の強みというのを感じとることはできないというのが実感です。","id":"exchange-005"},{"speaker":"塚本委員","kind":"質問","question":"そういうことを実際にやっているのかどうか、それは公にしやすいわけですから、そういう手続をしているのかどうか。それが弱いのではないかということを指摘したいんですけれども、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"そういった意味におきましては、もう少し私どももパンチが足りないかなと、そのような感じを持っております。マスコミ等に対しましても、これは区長会事務局が１本でこの間のいろいろな区長会の動きも含めまして、現に行っているという状況です。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"戦ですから、照会ということはしっかりある、タイムスケジュールの中に入れておかなければいけない。あるいは、ほとんどの学者はこういうふうに解釈するよということだってあるわけですから、ここまで逃げ込み作戦だけを繰り返して。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"特定事件調査(2) 清掃制度に関すること","agenda":"特定事件調査(2) 清掃制度に関すること","exchanges":[{"speaker":"土井委員","kind":"質問","question":"資料等はもう整理しなくてもいろいろ出ているわけですから、進めていただくことでよろしかろうというふうに思っています。〔「答えてもらったらいいじゃないですか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"これは容器包装リサイクル法の再生に向けても事業者の拡大責任というものが盛り込まれるかどうかというところで微妙なところかと思うんですけれども、結果、どういうものになるんですかというところをまず質問します。","respondent":"中山清掃リサイクル課長","answer":"十分な広報をしていくべきだという方針が確認されましたので、例えば広報であったり、説明であったりというものが今後なされていくものです。逆にそれが平成２０年度を目途としても、それまでにさまざま、集中的に考えていくという形になります。","id":"exchange-009"},{"speaker":"井上委員","kind":"意見","question":"ということは、方針を出されたということで、これが決定事項で、このまま２３区が進むということではないということで理解をしていいんですね。〔「違うよ、２１年を２０年にしたんだからね」と呼ぶ者あり〕との意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"２３区としてこのように進めていくという方針を決定したです。ですから、これから具体的なその実現に向けての説明なり何なり、データ検証なり、実験なり、モデル実証なり、行うということです。","id":"exchange-010"},{"speaker":"井上委員","kind":"提案","question":"いろいろなものが提案されていくんだと思うんですけれども、この平成２２年からの更新は、そのサーマルにするための改築ということなのかどうなのか。その辺はどうか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"マテリアルを１本視野に入れながら、できないものについては、サーマルリサイクルを実施するに当たって検討しなさいというのが前提です。実は城南の品川も含めた５区ぐらいのごみを焼却する専用プラント、トータルで可燃ごみ量が増えることに対応するという整備になるものです。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"一番最初にその他プラスチックでリサイクル用のＰというマークで１とか２とかあって、そういうことをどう国も含めて考えられているのか。そこのところは品川区としてどういうふうに考えて、そこも含めてどんなふうにこれから進んでいこうということなのか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"２３区としては、ここでもご説明したように、各区事業の中で考えていくです。どうしてもごみよりもさらに処理にコストがかかってしまう構造を考えると、各区の中で判断をしていく、こういう整理をしたものであります。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"あれはもうどうなるんでしょうかというか、あれは今、どうなっているのでしょうか。もう何もしないよという流れなのか、どういうふうに今動いているのか説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"何もあれはすべて６通りに分別することを義務づけての表示ではありませんけれども、資源有効利用促進法に基づいて表示は義務づけられているわけです。そのための１つの目安になるということです。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"じゃあ、そのプラスチックを可燃ごみにしていくという状況の中で、処理能力というのは、プラントの更新などで、清掃工場は現状の処理のままでいいのか、そのことによって拡大されなければならないのかという見通しをされているのかというところでは、どういうふうに計算されているのか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"一般廃棄物処理計画の、施設整備計画、４番の方の図ですけれども。基本的には工場の規模は変えない中で、今回のサーマルによって最終処分量が大きく減るということで計画しているものです。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここら辺のデータというのはどういうふうに出されているのかということを１つお聞きしたいんですけれども、本当に安全なのかどうなのかというあたりのところがどうなっているのかということが１つ教えていただきたいのと、そこら辺のところもちょっと説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"それから、スラグの有効利用の見込みですけれども、確かにこれはこれから２３区の課題になってはまいります。逆に公共工事だけでいいのかということを考えますと、今、そこの辺は清掃一部事務組合にも区としても十分働きかけをしていかなければいけないです。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"一番大事なのは、そういう点では、そういう点で日本はすごく弱い状況になっていると思うんです。拡大生産者責任というふうなことをやっていって、今回そういったところがここの中に入っていなくて、そういう点では区としてはいかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"今回のこの廃プラスチックのむしろ実施に向けての課題を我々としてどうやるかという報告の中で、区としては、申し上げているとおり。公害防止の技術、こういうものを総合的に勘案した結果として十分可能であるという結論が出てきた、こういうことです。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"３.１倍に増えてしまったという、デポジットだとか、どんどん燃やしていくというふうなことになっていくんじゃないかなというふうに思います。それともう１つ最後にお聞きしたいのが、ここの中で、ここら辺のところは具体的にどういうふうにされていくのかということをお聞きしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"どういうふうに収集をモデルにしても行い、どういうデータをとるのかというのを決めていくのが、実はまず必要かなというふうに思っております。２３区の中でこういうことが必要であり、今、これから清掃一部事務組合あるいは２３区の中で進めていく状況です。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、自治体では、ゼロエミッションとか、ゼロウエイストというふうなことで取り組みを進めている自治体もありますので、ぜひそういうふうなところも参考にしていただきながら、区民の意見を十分にくみ取っていただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"本田委員","kind":"質問","question":"清掃一部事務組合が改革プランもこうやって出して、２３区との連携も強めていくということは大変いいことなわけですね。２３区で十分説明をやっていくということ、技術的な面と労使間の面とありますけれども、この点はどういう議論になっているんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"これはもう２３区の現下の状況の中で、逆に言えば、いきなり全部アウトソーシングということはできないと。安定的な運用を１つの柱というふうにあえて入れてきたという部分もありますから、より一層の強調をして、逆にきちんとその辺を説明する出し方を。","id":"exchange-019"},{"speaker":"本田委員","kind":"質問・要望","question":"アウトソーシングについてもどういうものかというものを、もっとそれぞれ２３区、決して東京の清掃事業にとってはプラスではないと思うんです。率直にそういうような感想を持ちますので、よりよい建設的なその辺の構築をやっていただきたいというふうに要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"ほかのことも一生懸命やっていいものがそれなりに一生懸命やれるなと思ったんですけれども、１つだけ確認をさせてください。本当の意味の抜本的な改革をもう１回どこでやるんだというのが、動きというか、何かそこら辺のものに対しての見解があれば教えていただきたい。","respondent":"中山清掃リサイクル課長","answer":"同時に抜本的改革をそのままで残すのではないよという委員会のご指摘なども視野に入れて検討を進められてきたという経過は確かにあります。そこの部分は少なくとも我々もそういう流れの中で経営計画に参画して原案が出されているということを認識の中で残していくという形と両面…","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918758?Template=document&Id=5584#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":53297,"voices":60}},{"id":"h17-20051107-16","meetingId":"h17-cm11","date":"2005年11月7日","dateIso":"2005-11-07","committee":"街づくり特別委員会","time":"午後１時０４分～午後３時２８分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件整理しています。","topics":[{"id":"topic-01","title":"公有地の活用に関すること","agenda":"公有地の活用に関すること","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今ついに学校関係者への説明ということでお話をいただきましたが、第一日野小学校ＰＴＡ、あと日野中学校ＰＴＡにお話をした。第一日野小学校についてもＰＴＡ全員の皆さんに声をかけたのか、あくまで執行部の役員だけなのか、その辺どうなんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"学校のほうの説明ですけれども、学校のほうにつきましては、ＰＴＡ役員会の場で会長のほうから説明したという形で聞いてあります。その後役員から、各役員の方からちょっとという形でというのは聞いていないところなんですけど、まず役員の方には全部周知がされているという形で…","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"それは区のほうから、ＰＴＡはいろいろな会議があると思うんですけど、そこに出向いていって、役員、執行部だったら十二、三人の方だと思うんですけど、そのほか一般の役員ですと４０名、５０名いることもあると思うんですけど、そこに出向いていって説明をなさったということか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"それぞれ校長先生からＰＴＡの方に説明した経緯と、あとはＰＴＡ会長がまた役員に対して説明した経緯、何回かに分かれて説明をしているというふうになっております。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"校長先生に話して、またＰＴＡ会長に話して、それがまた伝わる。事情を話して、そしてまた直接質問をもらうというのが私は筋だと思うんですけど、それでＰＴＡ会長がまた役員に話したということでよろしいんですね。","respondent":"榎本行財政改革担当課長","answer":"進め方につきましては、どの段階できちんと説明をしていくのかというのは協議しながら進めていきたいというふうに考えております。今のところ、まだちょっと学校側からは特に企画のほうで説明をしてほしいというところまでは進んでいないという状況です。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"学校からじゃなくて、今まですまいるスクールをやるにしても、学校改築をやるにしても、一応皆さんに呼びかけて、そして直接話をして、直接またご意見を聞いてきたかと思うんですけど、そこは何か手続上問題があったんじゃないか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"今までのは１回決定した方針をそういう形で進めるという形にはなるんですけど、そういう形の進め方も含めて教育委員会と詰めていく。原案が決定だという話にはなりませんので、その進め方としては…","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"そこにお子さんを通わせているんですから、やはりきちんと呼びかけて、区のほうで誠意を持ってお話ししたという形が大事だと思うんですけど。こういう形でやりますというふうな動きをしていただきたいなと思うんですけど、その辺どうか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"その辺も含めまして、ＰＴＡ会長がやはり一番ＰＴＡをまとめる立場ですので、ＰＴＡ会長と十分調整して、教育委員会とも調整しながら進めていきたいと考えております。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問","question":"この間、決算特別委員会でもうちの会派からこのことについて地域の方にしっかりと説明をしてくださいという発言をさせていただきました。反応といいますか、今まで相当誤解があったと思うんですが、その辺の状況とかをちょっと教えてほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"地域への説明の部分ですけれども、その部分についてはきちんとこれからやっていくということで、特に反対等はございません。それから、防災拠点としても新しい防災拠点としての位置づけがされますので、その辺についても安心できるです。","id":"exchange-006"},{"speaker":"本多委員","kind":"質問・要望","question":"この先の首都高の品川線ですとか、そういったいろんなところから地域としては非常にいい話じゃないかというお話も伺ったりしますので。具体的な説明でこういうふうな説明をしたとか、その後、首都高の品川線の環境的なこととかは特に出なかったんですかね。","respondent":"榎本行財政改革担当課長","answer":"それから、まだ施設の部分の設計図もできていない段階ですけれども、十分配慮した設計をしていくという形での説明をさせていただいたところです。それから、そういうところも防災拠点として使えないかという形での検討も進めているという形の説明をさせていただいたところです。","id":"exchange-007"},{"speaker":"山村委員","kind":"質問","question":"それは区との協定で、小学校や中学校と同レベルの防災拠点として活用するということができるというのは、協定さえ結べば可能ということなんですか。そこら辺をもう少し詳しく説明を求めました。","respondent":"久保田防災課長","answer":"さらにこの近辺では、もう一つ高校等がありますので、そちらとは今交渉中でございまして、間もなく協定が結べるような状況にあります。小中学校の避難所ほどまだまだ設備的には十分じゃないところはあるんですけども、一応避難所としては受け入れてくれるという形にはなります。","id":"exchange-008"},{"speaker":"山村委員","kind":"質問","question":"高校というのは攻玉社だと思うんですけど、先ほど言った設備という面があると思うんですけど、そこら辺は何らか協定した場合は補助していくのか。ちょっと私も一般質問したいので、一般質問で質問してもいいような気もするんですけど。","respondent":"久保田防災課長","answer":"あるいは便槽をつくったりとかいうようなことをやってきているんですけれども、私立大学と結んでいるところは、まだまだそこまでは至っていません。向こうのいろんな考え方、いろいろと今度その辺は話を煮詰めていきたいというか…","id":"exchange-009"},{"speaker":"山村委員","kind":"質問","question":"そうすると、品川区全域でやると思っていいんか尋ねました。","respondent":"久保田防災課長","answer":"一部で今私立の関係で結んでいる関係は、四つか五つほどありますけども、できれば私どももより広くやっていきたいという考えを持っています。ただ、できるだけ多くの大学、私立高校に声をかけて協力を求めていきたいというふうに考えております。","id":"exchange-010"},{"speaker":"山村委員","kind":"質問","question":"どうもありがとうございました。一般質問でも同じことを聞くかもしれませんけど、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"確認をさせていただきたいんですけど、日野中学校跡地ということで、せんだっていただきました地図がありまして、この計画というのは、グラウンドを含めますけれども、校舎という建物、上物自体は右側の日野中学校と体育館ということでいいのか確認だけさせていただきたい。","respondent":"榎本行財政改革担当課長","answer":"建物の配置等はまだこれから設計ですけれども、基本的には、やはり全体の配置を考えときには、今の建物の配置というのは十分参考になるです。来年度設計予定という形ですが、実際上は今現在第２グラウンドという形で使っておりますので、今後十分検討させていただきたいと思いま…","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問・要望","question":"９月２日にいただきました資料の右手のほうなんですが、図書館、設計の段階で複合化していくようなお考えはどういうふうに持たれているのか。そのあたりを含めた並べかえというんでしょうか、お考えの範囲以外のものなのか、ちょっと教えていただきたい。","respondent":"榎本行財政改革担当課長","answer":"切り離して検討していったほうがいいだろうということで、それも含めて切り離して考えて、学校は学校でという形での考え方を持ってあります。防災上の件につきましては、設計の中で十分配慮できるかなというふうに考えております。","id":"exchange-013"},{"speaker":"大沢委員","kind":"意見","question":"新館のほうが昭和５７年ということで、その点、どういうふうにお考えになりますかとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"やはり昭和５７年建築の教育総合会館というのは、やはり、昭和５７年建築というのはそのまま活用できるような形にしていきたいなと。利用勝手等、今現在ちょっと分かれることもないということですので、その辺は十分検討できるというふうに考えております。","id":"exchange-014"},{"speaker":"山村委員","kind":"意見","question":"日野中学校のプールというのは、今後どうするのかとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"プールをどういう形で使うのかというのは、今後検討させていただきたいと思いますけれども、現在実際上は新館の上にプールという形でできておりますので、それがどういうふうに活用できるか、実際上文化センター施設として活用できるのかも含めて検討してまいりたいと思います。","id":"exchange-015"},{"speaker":"山村委員","kind":"意見","question":"そうすると、何度も申しわけないんですけど、壊すわけじゃないわけですね。それだったら、民間に開放するとか、そういうようなことで腐らしたりはしないということですよねとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"規格が、ちょっと小学生用と中学生用のプールの規格が違いますので、そういった意味ではちょっと難しいかなと思います。その他の用途として使えるかどうかというのは、建物全体の利用勝手の中で検討してまいりたいというふうに思っております。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"それと、今後の進め方というか、区民に対しての説明とか意見を聞くということでの今後の考え方、それも伺っておきたいんです。そのあたりでのご意見はどういうふうに出ていたのか、出ていなかったのか、そういう事柄についてももう少し丁寧に教えてほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"今後、問い合わせ等があれば、それに対して個別に説明を行っていきたいなというふうに考えております。それから、特に町会・自治会長単位等でも、ＴＯＣというのは地域のシンボル的な建物という位置づけを十分ご認識いただいていると思いますので。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"それを計画に反映させてという、そういうお気持ちがどの程度この計画で持っておられるのかということをちょっと改めて伺っておきたいと思います。区のところでこの計画とは別にどういう形でされてきたのか、それはそれでいいんですけども、その辺のところをちょっと伺いたいんですけど。","respondent":"榎本行財政改革担当課長","answer":"ニーズ調査のほうですけれども、今回はこういう本格的な利用計画案という形ですけれども、その前までずっと暫定計画は並行して検討してまいりました。その後で、そういった意味で各地域での要望等を踏まえた上でのそういう検討をして…","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"例えば公園にしてほしいとか、何かちょっと違った形での要望というのが出ているというふうに私は当初の説明を聞いたときに伺ったんですよね。だから、ちょっとこういう質問にさせていただいたんですけども、その辺というのは、どういうふうに整理していったらいいんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"やはり第一日野小学校の教育環境の向上というのがありましたので、そういったものを多角的に検討して調整をしていきたいという形です。それも今すぐでなくても活用の検討が、また次にできるということでの価値があるのかなという形で、財産の有効活用ができるという判断です。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"日野中学校が移転して跡地利用を何らかの形で考えなきゃいけないというのは、小中一貫校の計画ができて、具体的に進んだ時点でわかっていましたよね。そういう当初のときに、そういうふうな検討がじゃあどこまで具体的に種類が上がって検討されたのか教えていただきたいなと思っているんですけど。","respondent":"榎本行財政改革担当課長","answer":"あくまでもそれは暫定利用という形で、本格的なものについては特にその中では検討は、特にこれだという本格的利用のものは進んでいなかったです。暫定利用とそういう外部からの利用の中で検討してきたところ、新たなそういう申し出があって、急遽私たちで検討したという形です。","id":"exchange-020"},{"speaker":"本間委員","kind":"質問","question":"理解度といいますか、その辺についての反応は、集まった人々の反応はどのようなものであったのでしょうかということが一つです。先ほどのお話だと、初めてそういう民間に貸し出しをする、それも１０年間という部分はどのようなやりとりがあったんか尋ねました。","respondent":"榎本行財政改革担当課長、久保田防災課長","answer":"やはりこちらで説明したときにも、１０年程度かかるという形がありますので、特に貸し付け等について反対の声はありません。この説明をした中で、一番逆に意外だったのは… 今回の移転計画についてのご説明と、第一日野小学校、新しい第一日野小学校のほうで十分人数的にはクリアできるというふうな説明をしましたところ。多いですねという話から、今後のいわゆる私どもの心構えというんですか…","id":"exchange-021"},{"speaker":"本間委員","kind":"提案","question":"これまで何らかのご意見を求めている人々がいるわけでございまして、ともすると、正式に区から提案されたかどうかあれですけども。資金的な援助も含めてですか、そういう部分に対して鋭い質問等があったのかどうかというようなこともお聞きしたわけですが、今後ともそのようなとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"そういう形での、やはり教育施設としての新たな展開という形でありますので、その辺をきちんとやってほしいというような話があったところです。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"幾つか質問です。日野中学校の説明会を今後どうしていくのかということと、そういうお子さんたちもいらっしゃるわけですから、その考えはいかがか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"日野中学校のほうの説明ですけれども、日野中学校のほうもそれぞれ校長からと、それからＰＴＡのほうにも説明があってやっております。それから、十分その辺も踏まえて今後教育委員会の中でそういう形で進めていくということは…","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"特に荏原第一中学校の関係するところがありますので、そのところへはご理解を求めていただいたほうがいいかなというふうに思っております。管理、責任の所在はどうするのかとか、その責任の範疇の管理をする上での区側とＴＯＣ側とでの協議はどういうふうな形でしていくのか。","respondent":"榎本行財政改革担当課長","answer":"前回説明させていただきましたように、その時期にはきちんと説明を、確定した説明という形になろうかと思います。それはそれできちんと地域の方に説明をさせていただかないといけないと考えていますので、こういう形で説明をさせていただいているところです。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、少し外から見えるように、説明が多分あるかと思うんですけど、だれが見てもわかるように、そういうことはできないものでしょうか。どうなっちゃったんだろうというふうに、何か工夫していただきたいなと思うんですが、これについていかがか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"第一日野小学校の地域全体がこういう計画で動いていますよというような形である程度説明できるようにして、区民の方々のご理解とご協力を得られるような形で進めていきたいと思いますので、そういうことも念頭に入れて対処していきたいと考えています。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"初めに、区のほうの考え方をちょっと教えていただきたいなと思うんですけれども、その考え方についてちょっと教えていただきたいんですが。普通財産となるわけですから、そこをまず教えていただきたいのと、その後の動きと現状を教えていただきたい。","respondent":"榎本行財政改革担当課長","answer":"説明会の区の考え方というか、まずはこの地域・学校関係者の説明ということを第一義的に考えて説明をさせていただきました。ＴＯＣとのルールにつきましては、これからＴＯＣ側が全体の改築計画の具体的な検討に入るということで、それがまず先行している段階です。","id":"exchange-026"},{"speaker":"中塚委員","kind":"提案","question":"最初に対象の範囲とさっき伺ったのでもう一度お考えを教えてほしいと求めました。ＴＯＣはどういう提案をしてきて、規模や形ですか、規模や形をちょっと教えていただきたいんですねとの意見を述べました。","respondent":"榎本行財政改革担当課長、上野都市開発課長","answer":"前段のほうですけれども、その説明については、企画と教育、両方でちゃんと分担をしてきちんと対処してまいります。区としてどういうふうに使うかですので、その使い方についてはきちんと責任を持って説明等… 形を検討しているのかですが、ＴＯＣに関しましては、せんだっての９月２８日の街づくり特別委員会での経緯などをやりとりの中で説明いたしまして。現状７００台規模の駐車場を使っているですけれども…","id":"exchange-027"},{"speaker":"中塚委員","kind":"提案","question":"一応ＴＯＣの提案というか要望というんですかね、これがＴＯＣ側の提案で、区としてはそれを原案と思っているかどうか。規模と形をちょっと教えていただきたいのと、改築費用の一部を負担していただくというお話がありましたけれども、年間の契約金になるんですかねとの意見を述べました。","respondent":"上野都市開発課長","answer":"現在使っている７００台分の駐車場スペースはおそらく続けたいと考えられますから、具体的な内容等はまだわかりません。今後当議会の状況を踏まえまして、今後具体的な協議を進めていくとしておりまして、現時点では具体的なものは私どもはまだ持ってございません。","id":"exchange-028"},{"speaker":"中塚委員","kind":"意見","question":"たしか１０年間貸し付ける、改築計画がよくわからない時点で何で１０年間というのが出てくるのかどうかもよくわからないんですね。もう一回説明を求めました。","respondent":"上野都市開発課長","answer":"その方法がいけるというふうに決めた段階でより具体的な詳細な施設の規模等の協議が深まるものと考えてございまして、材料等は持ってございません。今後その辺の協議状況を踏まえながらご説明できる段階で当議会にもご説明してまいりたいと考えています。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"通常のお金の負担の割合といいますか、その説明をいただきたいんですね。それと同時に、ＴＯＣ側が負担するというのは、どこの部分なのか、そこを教えていただけますか。","respondent":"榎本行財政改革担当課長","answer":"よほど耐震上５０年を超えているとか、５０年以内での改築というのは、どちらかというと優先順位が低くなってくるというような形が一般的な状況です。区としてはなるべく多く経費を負担してもらいたいという形で考えておりますので…","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"の９割は区が出すんですか。どうも流れが見えないので、もう一回だけよく説明していただきたい。","respondent":"榎本行財政改革担当課長","answer":"実際上、学校を移すということですから、第一日野小学校のほうの解体プラスこちらの新築部分全部を移転にかかる経費という形で考えております。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"そうすると、国の負担が軽くなるか、品川区の負担がＴＯＣのあれによって軽くなるということなんですか。その幼保の考え方、施設をつくるとまたいろんな補助金の関係、どうもいろいろあると思うんですが、その辺はどうなっていますか。","respondent":"榎本行財政改革担当課長","answer":"経費の部分はまだ精査を全部しておりませんけれども、国庫補助等はまた申請できるものがあれば申請をして、区の負担をなるべく軽くしていきたいという考え方です。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"いろいろ見えてこない部分があるので、ＴＯＣが駐車場として貸す、現状と同じような駐車場の利用の仕方として貸すんですかね、７００台。現状のＴＯＣが使っている駐車場の利用として貸すだけで、それ以上も、それ以下も、ほかに目的はないんですかね、その点、教えていただけますか。","respondent":"上野都市開発課長","answer":"特段のそれ以上、それ以下もないと考えています。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"じゃあお聞きしますけど、年間１００万円で貸すんですか。それはあえて言わないという解釈を私はするんですけど、どうなんでしょう、そこをちょっと聞かせてください。","respondent":"岩田まちづくり事業部次長","answer":"ただ、区としては、あくまでこれはＴＯＣ側が今のところご協力をしたいということですから、これは寄附行為だと私どもは認識しております。私どもはそれなりのきちっとした主張をさせていただきまして、具体的な金額のやりとりについては…","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問","question":"今の財産価値の損失分というのがあるわけですから、減価償却あり、財産価値がどれだけ残っているか。ですから、これは本筋だとは思うんですけど、それでもあえて今の段階では話せないということか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"私の今のところの考えですが、具体的なやりとりの契約をしていくことになりますので、それまではしばらく様子を見ていただきたいと思います。","id":"exchange-035"},{"speaker":"須貝委員","kind":"質問・要望","question":"それで、ちょっと確認なんですけど、民間企業では、大体民間の遊休地を暫定的に貸すということをほとんどしないんですね、大手でも。１０年間にわたって貸し出すということは、民間の企業に貸し出すということは、その点についてご見解を説明を求めました。","respondent":"榎本行財政改革担当課長","answer":"それぞれ個別の事情を判断して、１回ここで１０年貸したからといって、次も同じ１０年貸さなくちゃいけないというものではございません。そういう形でなく、個別に判断しております。","id":"exchange-036"},{"speaker":"須貝委員","kind":"質問","question":"地域の人がその１階部分に逃げて来れるとか、水等も置いておけるようなスペースは少なくても１０年間貸すわけですから、ちょっとご見解を説明を求めました。","respondent":"榎本行財政改革担当課長","answer":"そういう具体的なところも含めて協議を進めていきたいと考えています。","id":"exchange-037"},{"speaker":"伊藤副委員長","kind":"確認","question":"同じ費用、よりプラスアルファなことをできる環境がそろっているわけですから。プラスアルファがあるわけですから、考え方としてはその小学校の移転だけじゃなくて、どうか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"複合化の部分ですけれども、あそこの実際上、小中一貫のときにも多分検討された、要は高さの違いです。そこまでのメリットはないのではないかという判断で、少なくとも本館、現在はそれを切り離して考えたほうがいいという考え方に立っているところです。","id":"exchange-038"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"ですから、そういう技術的なところを乗り越えて、より有効的な使い方じゃないかなと私たちは思っているわけなんですよ。ですから、現状の考え方をお聞かせいただきたいんですが、いかがか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"実際上の検討では、やはりそういうことも必要だなという形で検討せざるを得ないとは思うんですけれども、要は教育総合会館という形ですけれども。学校は単体で…","id":"exchange-039"},{"speaker":"伊藤副委員長","kind":"質問","question":"やるのならば、ＴＯＣの利用者にとっては非常にありがたい話があるわけですから。ただ単に小学校の移転だけで済ませて果たしていいのかなというところがずっとありますので、もう一言答弁をお願いします。","respondent":"榎本行財政改革担当課長","answer":"今現在の教育総合会館の実施計画の中でも、構想検討ということで、検討はずっと続けております。実際はそこの新館、本館をうまくどういう形で学校と見比べられないような形での部分というのは十分検討していきたいというふうに考えております。","id":"exchange-040"},{"speaker":"三上副委員長","kind":"質問","question":"それはどういうことかというと、今学区域がなくなっているわけですから、こういうふうに一つ思われます。ですから、そっちに行こうという話になればそれはそれでいいですけども、いかがか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"その辺につきましても、実際上、町会の役員にも全部説明をしたところですけれども、やはり、南側の部分という形で若干地域性の部分がありますので、その部分を今後教育委員会と詰めて説明を進めていきたいというふうに考えている次第です。","id":"exchange-041"},{"speaker":"三上副委員長","kind":"質問・要望","question":"そういった点での、ちょっとご意見をお伺いしておきたい。いい理念であると考えていますけど、そういった点をしっかりと確認していただいて、これもはっきりと求めておく必要があるんじゃないかな。","respondent":"榎本行財政改革担当課長","answer":"これについては両者それぞれの思いで協議を進めているところですので、協議が整った段階できちんと説明できるような形にしたい。片方で金額が出ますと、その点は十分やりますけども、財政的裏づけの説明はきちんとできるように対処していきたいと考えています。","id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"さっき聞きそびれちゃったんですが、ほかの方々のご質問を伺っていて改めて思った点で質問させてほしいと求めました。新たな理解をいただくための説明が必要だというふうに思うんですけども、そういうことについてはどう考えておられるのか、その３点です。","respondent":"榎本行財政改革担当課長","answer":"第一日野小学校跡地の説明の関係ですけれども、今回は日野中学校の跡地活用と第一日野小学校跡地活用の説明は一体だというふうに考えております。駐車場の関係ですけれども、やはり、それがもう少しまとまった段階でまた地域には改めて説明に伺いたいという形で説明をしています。","id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"やり方をもっと企業ですから、ＴＯＣもいろんな事業展開をされているし、区内だけでなくてね。これは１回目の説明ということで受けとめて、そういう姿勢で開いていくべきだというふうに思っているんですけど、その点はどうか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"今、まだホームページを出して日も浅いですし、まだ意見等は特にお問い合わせいただいていない段階ですので、さらにその部分は深く関係者と広く開いた形での説明を努力していきたいというふうに考えております。","id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"そこには３００社の企業の持っている車だけじゃなくて、それにしても７００台というと大した台数だし、もっといろんな意見が出てくると思うんですよ。だから、そういう点で慎重に事を進めていただきたいということをちょっと改めて強く意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"それが明らかにされるのは、つまり、検討中の内容が案として議会だったり住民だったり、明らかにされるのはいつの時点なのかというのを伺いたい。これはいつなのかを教えていただきたかったのと、一体のものと考えているのか、そこだけちょっと教えていただけますか。","respondent":"榎本行財政改革担当課長","answer":"そこの部分は一体のものとして考えておりまして、実際上、今回は第一日野小学校のほうは、ある程度前倒しして改築の部分を考えてあります。計画案という形ですけども…","id":"exchange-046"},{"speaker":"中塚委員","kind":"意見","question":"１０年間とはいえ、どういう進め方で進めていくのか、そういうのはやっぱり一定議会のほうで示していきたいなと思っています。ちょっと大まかですけどとの意見を述べました。","respondent":"宮崎委員長","answer":"それは正副のほうでも検討させていただいて、一定の取りまとめを行っていきたいと思います。そういうふうに考えておりますけど、よろしいでしょうか。","id":"exchange-047"},{"speaker":"本多委員","kind":"質問","question":"特定事件調査で公有地の活用に関することということで常にやっているわけですから、そういったことも重要視してほしいと求めました。その意味で、報告事項をいただいているたびに意見をそれぞれ言わせていただいているわけですから、そんなふうに思っております。","respondent":"宮崎委員長","answer":"ちょっと私のほうからの説明が不足していたかと思うんですけれども、もう一つは、三つが特定事件調査として付託いただいております。前回まとまった説明をいただいたんですけど、これだけ早く、これだけちょっと早くやったらどうかというのが正副の気持ちなんですね。","id":"exchange-048"},{"speaker":"山村委員","kind":"質問","question":"ということは、日野中学校跡地だけ、また公有地の中で特別に意見の集約をして、ちゃんとしたものをつくるべきということか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"南委員","kind":"提案","question":"そうすると、今回委員長のほうで正副でまとめられて提案されるというのは、公有地に関することだけを文書で各会派ごとに出して、そのほかの防災だとか武蔵小山駅周辺のあの問題についてはまた一定の時期にまとめて出すと、そういう二段構えでやるということでいいんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"山村委員","kind":"質問","question":"公有地に関すること。それとも日野中学校跡地だけに関してか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"だから、公有地に関することが具体的には日野中学校の問題だというふうになっているわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"それよりも、もっといろんな公有地の活用について、どう考えていくべきかというところの議論をしてと思っているんです。できれば、どのくらいできるかわかりませんが、その話し合いは継続的にやっていただきたいなと思うんですね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"西本委員","kind":"確認","question":"もう一つ確認したいのは、各会派の意見を聞くということの意義というか、どこまでなのかと思うんですけど、反対、賛成という形でするんですか。どういう形で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"そうすると、議長のほうへは特別委員会の中で、今回はこう考えているという形でいいんですか。それをどういうふうにまとめるんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"じゃあ、それは後で一つにまとめるという形か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"須貝委員","kind":"質問","question":"やはり今までの議会のルールとしては、せっかく特定事件として出しているんだから、５月にちゃんと回答を出すというのが筋道じゃないんでしょうか。何か理由があるならば、お聞かせ願えればありがたいと思う。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"須貝委員","kind":"質問","question":"やっぱりいろいろ白熱して議論した上でなったと、別になければないでいいですけど、ただ、順序を今回に限り変えるというのは、どうなんでしょうかと思いますけど。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"ちょっといいですか、今の件で。ですが、そうすると、この委員会のそもそもの目的が、日野中学校のことが解決できることを今やっているわけじゃないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"須貝委員","kind":"質問","question":"建設というのは、１０年スパン、例えば大型の高層マンションでも２年かかりますよね。１年延びたで、それは事情があるならば仕方ないですけど、そうなんですかね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"南委員","kind":"質問","question":"要するにこの委員会として賛成なのか反対なのかの１本にするわけじゃないし、１本にまとめるわけじゃなくて、どちらにしてもね。別に１本に絞っていこうとか、そういうことじゃないというふうに私は理解しているので、いいんじゃないですかというふうに思っているんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"三上副委員長","kind":"質問・要望","question":"特定事件についてそれを議論し、そしてやるということになれば、スピードが求められているということがあるということです。わかっているけれども、委員会として当然我々の責任を今果たそうとしているだけだというふうに受けとめていただければいいんじゃないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"須貝委員","kind":"質問","question":"今三上副委員長と伊藤副委員長の話をお聞きしましたけど、ちょっと待っていただいても、来年でもいいんじゃないか。ちょっと事情はわからないですけど、ちょっと筋道としてよくわからなかったということで、そういう発言をさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"大沢委員","kind":"意見","question":"各論をどういうふうに論じていって、何ら特別委員会の性格上不自然でも何でもないことかと思いますので、もう一回特別委員会をお調べになって……との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"須貝委員","kind":"質問","question":"すみません。例えばだれかが亡くなったとか、震災が起きたとかの緊急性の予算ならわかりますけど、ちょっと意味合いが違うんじゃないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問","question":"売り言葉に買い言葉的な議論になってしまう。最終的に結論を出すのはやっぱり執行部ですから、私はそう思っておりますので、何ら不自然なところはないと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664767?Template=document&Id=6312#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":45677,"voices":145}},{"id":"h17-20051108-8","meetingId":"h17-cm11","date":"2005年11月8日","dateIso":"2005-11-08","committee":"建設委員会","time":"午前１１時０２分～午後３時２６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"の第１６回東京都道路整備事業推進大会","agenda":"の第１６回東京都道路整備事業推進大会","exchanges":[{"speaker":"大西副委員長","kind":"意見","question":"以上で、本日の予定はすべて終了いたしました。○午後３時２６分閉会との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/825107?Template=document&Id=3834#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":1417,"voices":7}},{"id":"h17-20051109-14","meetingId":"h17-cm11","date":"2005年11月9日","dateIso":"2005-11-09","committee":"行財政改革特別委員会","time":"午後１時０３分～午後３時１９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"最初に特定事件調査を行います。 行財政改革に関することのうち、民間委託等に関すること","agenda":"最初に特定事件調査を行います。 行財政改革に関することのうち、民間委託等に関すること","exchanges":[{"speaker":"林（宏）委員","kind":"質問・要望","question":"７年、８年ぐらいなんだろうけど、あにはからんやペーパーレスはかなわなかったよね。区としてどこに効果があったというものを認めてこのステップに入ってきているのか、その辺をわかっていたら教えていただきたいんだけどな。","respondent":"小野情報システム課長","answer":"当然業務を進めていく中で、あるいは区役所が要求する仕事のレベルについていけないというところが１つあったんだろうと考えております。１つは業務の対応といいますか、改善というところが出発点だと考えております。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"意見","question":"片方でこの１ページ目の、特にピンクの部分の最初の四角、次の四角ぐらいまで相当お金かけているよね。どのぐらいというのは、区として数字を持っていらっしゃるのかなとの意見を述べました。","respondent":"小野情報システム課長","answer":"電子調達、ここでの初期費用としては１億５,６００万円ほどということを、平成１１年から１５年までの決算の合計額という根拠で算出しております。その後のものについてはまだ算出しておりませんので、おおよそこういう第１ステップ…","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"意見","question":"３億円という話は僕はちょっと信じられない数字だろうと。いわゆる電子化に対しての区としての投資額ですよとの意見を述べました。","respondent":"小野情報システム課長","answer":"ランニングコストの部分に、これは平成１５年度１年間という形ですけれども、１億４,６００万円ほどが運用コストとしてかかっております。機器の関係についてはいわゆる使用賃というか、一括して購入してしまうということではなくて、リースで年度で払っているという形です。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"意見","question":"区債で５年間というのでやっていった方が、いわゆる効率ということから考えたら、リースするメリットがないと思うんだよね。なぜこういうことをやっていくのかという基本的なものをもっと持っているというか、その辺についてちょっと説明を求めました。","respondent":"小野情報システム課長","answer":"単年度としてはここで人件費の削減ということで効果が出てまいりますので、それと開発の経費、それから導入した後のいろいろな運用経費ですね。そういうものを含めまして、平成１９年度にはその初期の投資額が回収できると試算をして、実際こちらの開発に取り組んだところです。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"この右側のサービス水準の確保という、ＳＬＡというこれはだれがつくって、文言になっているんですか。さっき言ったこのぐらい向上させたいんだという、これのもとは何なのか、それだけ説明を求めました。","respondent":"小野情報システム課長","answer":"国としてはこれを全自治体に実施してもらいたいという考え方があります。当然私どもの方も、このガイドラインを１つベースにして、区の方の要求水準というものをこのＳＬＡで定めていきたいと考えているところです。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"いかなきゃいけないんだから、いきたいじゃなくて、いきますということを僕は要望しておきます。ただ品川独自というものをなくす必要はないので、独自性を発揮するという部分もきちっと確保しておいてほしい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"武内委員","kind":"質問・要望","question":"主には経費の削減とか業務の合理化ということでお聞きしたんですけれども、そういった面で何か目に見えた効果というか、何か期待できるものがありましたら教えてほしいと求めました。","respondent":"小野情報システム課長","answer":"ここにもちょっと書いてありますけれども、やはり２４時間３６５日運用が実際に可能になってくるというところは大きなものだろうと思います。かなりの運用時間を確保できるということがありますし、そういう点では大きくサービスの範囲が広がってくるのではないかと考えておりま…","id":"exchange-007"},{"speaker":"武内委員","kind":"質問","question":"具体的に何かわかりやすいところで、例えばこういう部分のサービスが２４時間３６５日になって、今まではこうだったんだけどこういうふうになるんだみたいなのがもしありましたら、ちょっと説明を求めました。","respondent":"小野情報システム課長","answer":"１つはここに書いてあります電子申請、まだ品川は１２月からという形ですけれども、これは実際に２４時間受付が可能になる。こういう部分の中でサービスが改善されていくです。","id":"exchange-008"},{"speaker":"武内委員","kind":"質問","question":"わかりました。そういう方に対しての、情報弱者に対しての配慮というか、そういうのはどう考えていらっしゃるか説明を求めました。","respondent":"小野情報システム課長","answer":"それからもう１つは、この中で新しい放送と通信を融合させるような新たな取り組みをしていて、現在具体的な検討が始まっているという状況にあります。そういうことでもなかなか対応ができない部分については、ＩＴになじまない方についてもサービスをきちっとやっていく…","id":"exchange-009"},{"speaker":"中島委員","kind":"質問","question":"１点目は先ほど武内さんの質問のＩＴに弱い方のために公開端末を何台か用意するとおっしゃったんですが、そのときに１回開くと履歴が残ります。そうした公開端末におけるセキュリティーはどのように考えていらっしゃるんか尋ねました。","respondent":"小野情報システム課長","answer":"公開端末についてのセキュリティー、インターネットで公開されているホームページ等からの情報を自由に引くことができるということです。申しわけございません、今ちょっと私の方で把握をしてございませんので、確認をさせていただきたいと思います。","id":"exchange-010"},{"speaker":"中島委員","kind":"質問・要望","question":"電子調達とか電子申請になってこれが今年度からできるということなんですが、登録を１つにするということは経費の面ではどうなんでしょうか。これを１本にするには費用が相当かかるんか尋ねました。","respondent":"小野情報システム課長","answer":"１つの登録によってすべての電子申請等のサービスが受けられること、これが本筋だろうと思います。現在幾つか先行して個別のシステムが動いておりますけれども、これについては今後１本化ができるような検討をしてまいりたいと考えております。","id":"exchange-011"},{"speaker":"中島委員","kind":"質問・要望","question":"やっぱりまたやり直しをするというとそれだけの費用がかかるわけですから、その辺のところも検討の中に入れてほしいと求めましたが、いかがか尋ねました。","respondent":"小野情報システム課長","answer":"長期的な見込みを立てながら、適切な時期にできるだけむだのないような形で処理をしてまいりたいと考えております。","id":"exchange-012"},{"speaker":"三村委員","kind":"質問","question":"今、この中のステップ３の官民を超えたサービスということで打ち出されているんですけれども、その辺のところを。転出届を出したら、共同開発をしている自治体間のそういったことまで視野に入れて作業が進んでいるのか、その辺のところだけ教えていただけますか。","respondent":"小野情報システム課長","answer":"住基ネットワークのサービスで２度区役所に出向いていかなくてもできるという対応がとれておりまして、その手続がその１つのフォーマットの中で。まだそこまで取り組みという形ではいっていないんですが、考え方としては、そういう方向でだんだん進んでいくのではないかと思いま…","id":"exchange-013"},{"speaker":"沢田委員","kind":"意見","question":"システム全体をアウトソーシングする方向だということと、８階の大型コンピューターをデータセンターに移行していく展望を持っていると。そこらが不安なんですが、もう少し説明をしてもらうとありがたいんですけどとの意見を述べました。","respondent":"小野情報システム課長","answer":"ウェブ化というのは１つのコンピューターのシステム設計で、その中でウェブという方式をとってシステムをつくっていくです。情報システム課を通して、区が保有しているいろいろな個人情報等が一般のインターネット等のネットワークを通じて外に出るということはございません。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"これ１行だと、どんなセキュリティーをやるための努力が日常的にされているのか、開発されているのかというのが全然見えてこない。実際にはどういう検討がされているんか尋ねました。","respondent":"小野情報システム課長","answer":"いろいろ実際に運用していく中でつけ加えたり変えたりする必要が出てまいりますけれども、こういうものについても事前に区の承認を得なさいと。こういうふうなことで実際の運用の部分についてセキュリティーを十分得られるように義務づけをしていくと。","id":"exchange-015"},{"speaker":"沢田委員","kind":"意見","question":"そこに矛盾というか、難しさがあるんじゃないかと思うんですね。最後にデータセンターの中身について、どういうところで運営してというのがわかっていたら、少し説明していただけるとありがたいんですがとの意見を述べました。","respondent":"小野情報システム課長","answer":"データセンターについては、実際にそこには非常に重要な機器類がありますので、場所等について詳しくお話しすることはできないんですが、近辺です。さまざまな部分で、いろいろな対策がとられている施設ということで…","id":"exchange-016"}]},{"id":"topic-02","title":"議員定数に関することでございますので、区議会事務局長以外の理事者の皆さんは自席の方へご退席していただいて結構でございます。ありがとうございました。 それでは…","agenda":"議員定数に関することでございますので、区議会事務局長以外の理事者の皆さんは自席の方へご退席していただいて結構でございます。ありがとうございました。 それでは…","exchanges":[{"speaker":"中島委員","kind":"質問・要望","question":"それとともに、私どもは区民の多くの方から定数削減の声を伺っております。もっと少ない中でやっている議会もあるわけですから、このように感じております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"大西委員","kind":"質問・要望","question":"今、ちまたに言われている区民の皆さんからの議員定数削減という要望ということを皆さんの中からお聞きすることがあるわけですけれども。４２名が多いのか少ないのかという根拠を見出しながら、そういった多岐にわたることを検討すべきである、そのように考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"沢田委員","kind":"提案","question":"非は非として、間違えたところはしっかり指摘をし、改善を求めるという本来の機能を果たすべきなんじゃないかと思います。議会の中で区民の了解を得られないこちらの方こそ急いでやるべきで、出会手当だけでもたしか年間１,５００万円ぐらいになると思いますのでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"沢田委員","kind":"提案","question":"議員定数を減らすかどうかという点は、どうやって効率的なむだを省いていくかということなので、対案として、大西委員と同じように提案しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"築舘委員","kind":"意見","question":"平成１５年の自治法改正後の各２３区の方向性を見てみますと、外国の例を見ましても、議員の数というのは必ずしも多くはない。大切なことではないかということを自民党としては意見を申し上げたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"自分の意思で逝ったわけじゃないんですから、やむを得ず今３９名で残った者で頑張っているという意識を持ってやるべきだろうと僕は思っています。これから委員長のお考えでやっていかれるかどうかあれなんですけれども、４５人は要るだろうというような、僕はいろいろな意味を込めてね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"藤原副委員長","kind":"意見","question":"区民の数は徐々に増えているということで、現状維持ということと、それともう１つは、議員定数、行政改革、職員の削減とかをしております。議員も議員改革という意味において、議員みずから議員の定数も削減したらどうかという、現状では２つの意見が出ている次第ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"三村委員","kind":"確認","question":"どういった項目で調査結果がワースト２というふうになっているのか確認したところ、議会を開催していないとか、あと全委員会が公開されていない。そういった仕組みづくりもきちんと議論をあわせてしていくべきだと私たちは考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"中島委員","kind":"提案","question":"このときも、我が党では４名削減という提案をさせていただいていたわけですが、そのときに３０万人という話をしたという話も伺っております。私たち自分自身のことですから、その中で一生懸命仕事をできる議員というものを目指していくことが大事ではないかなと…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"沢田委員","kind":"提案","question":"これを機会に議会はどうあるべきかという林委員の提案は、私は非常にいい提案だと思いますね。この場でやってもいいような気もするけど、本音でやるというのでも私らは構いませんし、改めてそういう場をやるという提案については賛同しますとの意見を述べました。","respondent":"須藤委員長","answer":"皆さん方が進め方で結論を出していきなさいということであれば、日程的なものを踏まえながら、運営の仕方についてもご発言いただければと思います。ほかにございませんか。","id":"exchange-026"},{"speaker":"大西委員","kind":"意見","question":"１つ皆さんで本当に議論を深めて、これはできるかどうかわかりませんけど、あり得ることであろう。私ども品川区にとって、人口がどうなっているのか、諸問題がどのような形に推移しているのかをよく議論するということが肝要だろうとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"藤田委員","kind":"質問","question":"身分にかかわる問題ですから、最終的には一人一人がこの時代を見据えて、どうあるべきかということを決断しなきゃいけないと私は思うんですね。党内からしても血のにじむような決断をしているわけですから、ですから、これは最終的にはお一人おひとりの身分にかかわる問題ですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"今の国の政治家を見ていても、言っても変わらないよ、投票しても変わらないよとあきらめちゃっていらっしゃる部分の意見なんかも伺うわけですね。そういった面で、こういった面を見ても、政治への意識を高めていく部分での議員の活躍がすごい重要視されているのではないかなと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"三村委員","kind":"質問・要望","question":"先ほど林委員がおっしゃっていたように、きちんと本音で議論をしていくべきではないかなと考えています。先も言ったように、そういったところもあわせて深い議論をしていっていただきたいなと、私の方はもう少し議論を深めていくべきと考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"武内委員","kind":"質問","question":"いろいろなご意見を伺って、確かに議会、また議員の役割の重要性とか、そういったものはそのとおりだなと私も認識しております。まだたしか議員になってから１回もないんですけれども、またこのときはどういった経緯でそういう形に、局長にお聞きしたらいいんですかね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"武内委員","kind":"意見","question":"よくわかりました。３年目になるということで、五回ほどやっていると思いますので、あまり時間をかけずに結論を出していくべきじゃないかなと考えておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"藤田委員","kind":"質問","question":"ですから、その辺を十分に承知していただいて、定数の問題をどうするのかという、そこに絞って議論すべきではないかと。そして、一定の時期に結論を出していくという、それが議会の責務であると私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問","question":"我々も人数が多いんじゃないのと言われますけれども、じゃあ何人がいいんですかという話になると、そう言われる方から答えは出ないです。４２人がいいんですか、４０人がいいんですか、３８人がいいんですかと言っても。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"大西委員","kind":"質問","question":"今年つくられているわけですから、ここに載っている「然るべき時期にさらに調査を行い、決定する」という形で運んでいただければと。この行財政特別委員会の中でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"中島委員","kind":"質問","question":"区民の方の声を皆さん聞いているわけですから、それを全く無視してきたのか、考えてきたのか、このことが大事ではないかと思うんですね。むしろはっきり結論を出すなり、全員協議会で結論を出すということが大事ではないかなと、このように感じております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"林（宏）委員","kind":"提案","question":"議長に提案をして議運に諮って、条例改正ですから、本会議に提案していくということになるわけで。何も全員協議会が２時間の中で２人の先生に話を聞くだけで終わり、それこそ５時まで時間はたっぷりあるわけですから、そういうやり方もあるとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/787035?Template=document&Id=5788#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":41515,"voices":81}},{"id":"h17-20051128-6","meetingId":"h17-cm11","date":"2005年11月28日","dateIso":"2005-11-28","committee":"区民委員会","time":"午前１０時０３分～午後２時２３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を89件整理しています。","topics":[{"id":"topic-01","title":"第７９号議案、災害に際し応急措置の業務に従事した者または水防に従事した者の損害補償に関する条例の一部を改正する条例","agenda":"第７９号議案、災害に際し応急措置の業務に従事した者または水防に従事した者の損害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"武内委員","kind":"質問","question":"水防法の改正によって条例の数字が変わった、内容は変わらないという説明をいただいて、国から都道府県に変わったと、ちょっと今伺ったんですけど、水防法自体の変わったところをもうちょっと詳しく説明いただけますか。","respondent":"久保田防災課長","answer":"浸水被害をあらかじめ予定されている区域を浸水想定区域として指定し、立会川等についても昨年度ですか、区のほうに来ております。区のほうでは、それに基づきまして、現在浸水予想図に基づくハザードマップを作成中です。","id":"exchange-001"},{"speaker":"武内委員","kind":"意見","question":"そうすると、あくまで都道府県知事が国と共同して通知とかその他のことを行っていくということで、区の役割としては変更があるのかどうか、その辺のところをとの意見を述べました。","respondent":"久保田防災課長","answer":"従来から区の体制としては、災害応急対策本部、いわゆる水防本部を設置して、適時円滑な対策等に従事しているということが基本ですので、これらについての変更というのは特にございません。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認なんですが、どういう状況だったときに、これが適用されるかということを改めて確認いただきたいんですが。","respondent":"久保田防災課長","answer":"水防法につきましては、水防管理者、水防団長あるいは消防機関の長が従事させることができるという規定になってあります。今お話のとおり、現在のところ、区のほうにおいてはそういうような適用例というのはございません。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"確認だけなんですが、そういう大規模災害が発生して、こういう方々から一般の方にお願いした場合、万が一の場合があったときに、この災害補償が、この法律、法令、条例が確立された、その確認でよろしいんですね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"住民が参加すると同時に、その場の判断が求められているというんですかね。これはひとまず避難したほうがいいのか、それともそのまま協力したほうがいいのか、そこをちょっと説明してもらえますか。","respondent":"久保田防災課長","answer":"従来確かに今お話に出たように、実際やっぱり一定程度訓練した方とか何とかという形が、望まないとなかなか難しい点はあるかとは思っております。例えばそこの現場にいて、やはり一定程度…","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"手伝って、けがをされたときの補償というのは必要かなと思うんですね。本来損害補償第３条のところに、説明のパンフレットとか、そういう周知みたいなものは現状どういうふうになっているのか説明を求めました。","respondent":"久保田防災課長","answer":"あるいはそのときにいかに安全対策を施すかということにやっぱり視点があると思いますので、仮に万が一そういう自体が起きたら、その時点でやはり周知をしていくという形になるかと思います。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"１点、損害のお金の出し方についてお伺いしますが、これは負傷とかがないようなことを願うんですけれども、もしなったときの方に損害を補償するための保険といいますか、保険をかけてお金を支払うのか、それとも支出というのはどこから出てくるのか尋ねました。","respondent":"久保田防災課長","answer":"それで一定填補されるという形にシステム的にはなっております。補償の内容については、これは政令で定まっておりますので、それに準じた区の条例を適用すると、こういうシステムになっております。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"従事した人というんですか、その人を確定というんですか、どの人なんだと。その辺をちょっと１点お聞きしたいのと、損害補償ですから、この辺についてちょっと２点お聞きしたいと思います。","respondent":"久保田防災課長","answer":"やはりそれを認定するかという作業なり、あるいはそういう機関が一定程度判断するという形にはなるかと思います。それから、「速やかに」というのは、いわゆる手続上速やかにというような意味合いだというふうに解釈しております。","id":"exchange-008"},{"speaker":"木下委員","kind":"質問","question":"先ほど課長のほうからハザードマップを作成するというお話をお伺いしまして、また周知のほうはどうなっているのか、ちょっと聞きたいなと思います。防災というと、一人ひとりの区民の方々の意識づけが大事だと思いますので、そこら辺のことをお教え願いたい。","respondent":"久保田防災課長","answer":"これは来年の１月の防災フェアにオープニングしたいと思っていますけれど、そこの中で知ることができるというようなシステムをまず一つつくります。区民への周知ですけども、当然ながら広報、あるいはそういう形でまた周知を図っていきたいというふうに考えております。","id":"exchange-009"},{"speaker":"武内委員","kind":"確認","question":"確認で、聞いたかもしれないんですけど、もちろんそういう方がその際にけがをしたというのもこの場合含まれると判断してよろしいんですか。公のところからその方なり、その地域の方に要請が出ないとその対象にならないのか、その辺のところだけ確認しておきたいと思います。","respondent":"久保田防災課長","answer":"その辺は申請があって、そういったところの経緯なども判断する場合というのがあるかとは思います。市町村長、警察官等々ができるということになりますので、そういう形での形式はとるかというふうに思います。","id":"exchange-010"},{"speaker":"武内委員","kind":"質問","question":"万が一、特に集中豪雨的な災害ですと、ある特定の地域だけで集中しますよね。それとも申請のとき、その辺の事情を勘案してできるのか、その辺のところはどうか尋ねました。","respondent":"久保田防災課長","answer":"経験事例があるとかなり詳しくお話はできると思うんですけれども、幸いなことに、区のほうではそういうような経験がございませんけども、おそらく今おっしゃったようなことも加味した形で、おそらく判断が一つは出てくるのかなというふうには想像されます。","id":"exchange-011"},{"speaker":"武内委員","kind":"質問・要望","question":"そういうことも今後出てくる可能性がありますので、そのような方向で、最初から何か要請がないけど手伝いもしました。それによってけがをしたからだめなんだよというんじゃなくて、その辺のところを認めるような、ぜひ条例にしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"林（宏）副委員長","kind":"意見","question":"そのときの防災組織の中に本部長だとか広報担当だとか、いろいろ役割分担を決められているんだけども、それはこういうことに当てはまるの。既に要請はされているの、いざというときにやってくださいというふうにとの意見を述べました。","respondent":"久保田防災課長","answer":"大きな災害対策基本法に基づいた災害対策、要するに災害というふうになれば適用されるかというふうに思いますけども、今お話が出ていた通常の訓練とか何とかというのは……。","id":"exchange-013"},{"speaker":"林（宏）副委員長","kind":"質問","question":"今いろいろ質問出ていたけど、あるいは区民防災組織みたいにいざというときは機能してくださいよとふだんから町会にお願いしているわけでしょう。そうすると、そういう人たちにも、こういうものがありますよと少なくとも本部長というのかな、町会長には言っておいてあげる必要があると思うんだな。","respondent":"久保田防災課長","answer":"過去にもこういう形でのお話はしたことがあるかとは思うんですけども、徹底ということになれば、まだまだ十分じゃないところがあるかと思いますので、機会を介してその辺についてもお話をしていきたいというふうに考えております。","id":"exchange-014"}]},{"id":"topic-02","title":"第８５号議案、指定管理者の指定","agenda":"第８５号議案、指定管理者の指定","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"比較検討されたんでしょうかということが一つ。ですから、なぜ３年間なのかということを単純にお伺いします。","respondent":"長田区民課長","answer":"そういった意味から、今までも安定をした運営を実施してきてもらったということで、まずそういった評価があるです。それから、期間の３年ですけれども、基本方針もついてありますけれども、原則は期間５年を基本とするということになってあります。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"質問","question":"それをさらに進めていく上に当たって、今まさに課長がおっしゃったような民間の方々が逆に進出できにくいような状況が正直あるわけじゃないですか。ですから、本来の趣旨とは相当外れるわけですから、その考え方についてもう一つお願いします。","respondent":"長田区民課長","answer":"それがいろんな状況からかないませんでしたけれども、３年後につきましては、公募選考を基準とするというようなことを当然考えてあります。その間の準備期間としての３年間ということで、先ほどの説明を申し上げたものです。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"でも、逆に言えば、そういうものを変えていかないと、民間の方が入りにくいわけじゃないですか。民間の方も入りにくいことがあるわけですから、そのことについての３年間かけて見直しの議論はどうするんですかということをもう一度お願いします。","respondent":"長田区民課長","answer":"その地権者の総意に基づいて管理組合が設置され、この運営についてはその管理組合が基本的にどういうふうにしていこうかという議決をしています。この会議の中での話ですから、今結論はということでは、ちょっと申し上げられないというのが現実です。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問・要望","question":"３のところに収入とか収支計画、新規参入業者からこういう情報を結果的に行政が集めることができるんでしょうかということを一つお伺いしたいのと。例えば株式会社になったとか、その場合にどれだけ私たちに情報を提供できるんですかということをお伺いしたいんですが、いかがか尋ねました。","respondent":"長田区民課長","answer":"民間としては、それじゃあこれからそういうような部分にも参入をしていくにはどうしたらいいかというようなことを検討しているようです。ただ、これこれこういう理由により…","id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それは非常に企業のノウハウであり、知恵の結晶でしょうから。理解してほしいのは、これは最終的に議会の議決になってくるわけですから、いかがか尋ねました。","respondent":"山田区民生活事業部長","answer":"この個々の部分はお答えをしていくということで、今日の議論の場がまさにその場であるというふうに認識していますので、どうぞよろしくお願いいたします。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"意見","question":"最後に一つ気になったのが、指定管理者の基本方針の２ページの選定委員会のところで、「事業部ごと」にという表現になっていますよね。事業部ごとに、最終的に品川区の案として決定するのはどなたかということを、どこでだれがするかということをお答えくださいとの意見を述べました。","respondent":"長田区民課長","answer":"選定委員会につきましては、委員ご指摘のとおり、事業部長が委員長になって実施をするものです。当然どこにするよという決定につきましては、区長決定で内部決定をとった上で提案を申し上げると、こういう手順になってあります。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、万が一事業部ごとの選考委員会の決定が区長部局で受け入れられない可能性もある、要するに何を言いたいかというと、そういう最終的なストップをかけるものはあるんですかということをお伺いしたいんですが、いかがか尋ねました。","respondent":"長田区民課長","answer":"当然のことながら覆る場合もあり得るというようなことですけれども、通常は区長の権限を任されて選考委員会をやるわけですから、通常の手続の中では考えにくいかなというように考えてあります。","id":"exchange-021"},{"speaker":"武内委員","kind":"意見","question":"選考基準で２０項目書いてありますけど、各５点で１００点満点ということだったんですが、トータルで何点だったのかということ。例えば４点、５点ならばいいのですが、その辺をお示しいただけますかとの意見を述べました。","respondent":"長田区民課長","answer":"すべて３以上というような形になってあります。関係法令の遵守および利用者の安全確保、こういった部分でも及第点だろうというようなことでの評価が下されたものというふうに思ってあります。","id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"概ね３以上だということでわかりました。この選考基準の２０項目ですけども、３年後に見直す中で、その辺の考え方とかがありましたら説明を求めました。","respondent":"長田区民課長","answer":"高度な区民の文化要求に対応していくというようなことのために設立をされたわけですから、当然そういった視点というのは必要になろうかと思います。あわせまして、きゅりあんの中でそういった事業の実施…","id":"exchange-023"},{"speaker":"武内委員","kind":"質問・要望","question":"それプラスやっぱり文化芸術という部分のものを民間の応募される企業はどう考えているかという部分のところに選考基準を加えていただければと思いま…要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"この文章だけだと、いわゆる現行の文化振興事業団にという、文化振興事業団ありきと思えたんですね。その中で今伊藤委員の質問の中で、なぜ初めから委員会に出す資料の中に公募はしたけれども、まず教えていただきたい。","respondent":"長田区民課長、山田区民生活事業部長","answer":"今回については、基本方針の中にも書かれていますけれども、公募は基本という部分については変わっていません。ただ、特別な理由がある場合というようなことで、基本方針の中にも書かれてあります。 その内部的な検討の段階で、手を挙げられるということはありますかという、可能性として伺ったのは２社ございました。先ほど課長から説明があったとおり、スケールメリットとして考えたときに、非常に難しいということが出てまいりまし…","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"そのときの採点が１００点満点でほとんどの方が７０点以上ということだったんですが、この委員の方は今部長がお話をした内々で２社をあれしたけれども、選定委員は知っていたんか尋ねました。","respondent":"長田区民課長","answer":"当然部長と私は直接の担当部分ですから、少なくてもそういった情報は知っておりました。ほかの委員につきましては、そのことは特に事務局としてほかの委員、３名の委員にお伝えをして選考したものではございません。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"点数のことですが、１００点満点で皆さん７０点以上ということでしたが、何点以上ならば文化振興事業団がいいという正確な点数があったんでしょうか。それとも、感覚的に７０点以上ならいいなと思ったんか尋ねました。","respondent":"長田区民課長","answer":"点数の評価の問題ですけれども、５点法でやっていますから、その真ん中になるのが３点です。そういった意味では、判断の基準というのは３点を２０項目足した部分の６０点が判断の基準になるのかなというふうに私自身は思って臨んでおりました。","id":"exchange-027"},{"speaker":"藤原委員","kind":"意見","question":"まさに厳格な審査をして、一つしかない文化振興事業団が合格点をとったことはものすごくよかったとは思いますが、それと議会に議決をされて、指定管理者に文化振興事業団がなったとして、個人情報の保護というのはどのようになっているのかご説明くださいとの意見を述べました。","respondent":"長田区民課長","answer":"早くから区の個人情報等の取り扱いに基づきまして規定をつくりまして、その規定に基づきましてずっと対応してきたところです。ですから、そういった部分の個人情報に扱う部分というのは、ほぼ区並みということでご理解をいただいてよろしいかと思います。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"具体的なことを伺いたいんですけど、選考基準の１番の(1) で、「利用者の平等な利用が確保できる内容」となっているんですけれども、この「利用者の平等な利用」というのは何なんか尋ねました。","respondent":"長田区民課長","answer":"当然対象施設が公の施設ですから、これの目的にも書いてあります「何人も」という話になります。そういった中で、ごく一般的な通常の感覚としての区民の平等ということが図られなければならないだろうということで、一番先に挙げたものです。","id":"exchange-029"},{"speaker":"木下委員","kind":"質問","question":"オープンで応札してと、その中で品川文化振興事業団に決まったということだったら、何も皆さんそういうふうにならないと思うけど。どういうところで、我々はわからないわけですから、この指定管理者制度というのに移行して何年かたったわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回区議会に議決を求めるんですけれども、その議決を求めることの制度上の目的や趣旨、ここをちょっとまずご説明していただけますか。その他もろもろありますけれども、これはあくまで選定委員会の判断であって、僕たちの判断が求められているわけですよね。","respondent":"長田区民課長、山田区民生活事業部長","answer":"６項には「指定管理者の指定については議会の承認を得ること」、これが根拠です。これについても有していると、これは資金だけじゃなくて、人的資源も含めて有しているというようなことから判断をしたものです。 今回は行政処分の一種、それからあと、利用料金制を持ってご自分の歳入という形をとれますよというふうに性格が変わってきております。議会としてもそういった推移を見ていただきながらご判断をいただいて…","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"であれば、具体的に協定書が履行されているかどうかの関与を具体的に教えていただきたいのと、判断するための基準を教えてくれと言っているんですね。つまり、区が「この団体は大丈夫ですから信じてくださいよ」と、これでは僕らは判断できないわけですよ。","respondent":"長田区民課長","answer":"そういった部分では、基本方針の中にも書かれているように、１年ごとに評価をしなさいよというようなことが基準です。ですから、そういった中で先ほど申し上げました点数になったというようなことですので、よろしくお願いいたします。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"年に１回報告書を指定管理者が出して公表されるということですけど、今回は議案としてかかっていることですから、もう一度お願いします。経営基盤が安定したかどうかなんて、逆に伺いますけど、この資料で何をもって僕らは判断すればいいんか尋ねました。","respondent":"山田区民生活事業部長","answer":"これを夜間の実施に持っていきまして、例えば午前中使っていると、１日貸していないんじゃないかというご指摘がございました。今話題になっておりますＡＥＤの導入をし、職員も訓練をし、対応ができるように努力をしていく。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"この文化振興事業団がアルゼンチン国債の１億６,０００万円の購入問題を過去に引き起こしているし、その損害が今確定している。選考委員会でも、全く触れられていないのか、それとも触れて議論したのか報告してください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"中塚委員","kind":"意見","question":"その財団が過去に起こして、今年の６月に損害が確定している、この問題を選考委員会で審議したのかしていないのかも答えられない。そう思いませんかとの意見を述べました。","respondent":"長田区民課長","answer":"ただ、財団法人が品川区立総合区民会館の運営に不適切だというようなことは申し上げられないというようなことです。先ほど部長のほうからも説明申し上げましたとおり、ノウハウ、よろしくお願いいたします。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"現在の一連の今までの経過について、選考委員会では一言も触れていない、そういうことなんですか。そこを聞いているんです。","respondent":"長田区民課長","answer":"今ご指摘いただいた内容につきましては、今回の指定管理者を指定するに当たって、必要以外の項目だというようなことで判断をしておりますので、そういった議論はしてございません。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"ちょっと私伺いたいんですけれども、今僕は理解を共通したいんですけど、今の僕の発言で、どこが今の審査と合わないのか、委員長のその趣旨を話してください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"ということは、委員長は文化振興事業団が購入したアルゼンチン国債の購入の問題も区民委員会として問題にするのはおかしいと、そういうことでいいんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"中塚委員","kind":"意見","question":"別にどういうことかを問うわけじゃないんですけど、どう努力したのか、そういう経過すら報告されない。それすら触れないというのは、全く私はおかしいと思いますとの意見を述べました。","respondent":"山田区民生活事業部長","answer":"会計処理が、今の法人会計にのっとってやられているというふうに解釈していますので、私どもについては現在出されている資料の中でいわゆる安定した基盤を持った法人だという認識のもとにいわゆる候補者としたものですのでご理解いただきたいと思います。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"ということは、文化振興事業団の理事会が決めた決定や審議や中身に議会や行政は全くチェック機能が働かないと、そういうことなんですか。説明を求めました。","respondent":"山田区民生活事業部長","answer":"丸投げかというふうにご指摘をされると、評議委員会の中には各議員も選出されて、ご意見を言える場があるというふうに認識しています。決算、予算についても議会にご報告をさせていただいているところですので…","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"そして、こういうふうにやむを得なかったと。そういう手続を今回こういうわけでとらせていただきましたということは公表するというふうな状況なんか尋ねました。","respondent":"長田区民課長","answer":"今回の検討の資料の中で、第３回定例会で条例改正が必要となる公の施設の一覧というようなことで、お手元にお届けをしています。その中でもそのように説明はされているかと思いますので、よろしくお願いいたします。","id":"exchange-041"},{"speaker":"須貝委員","kind":"質問","question":"それと、今後もやはりこういうことが起こり得るというふうに常に考えていなきゃいけないのか、そうじゃないんですか。あくまで、やはり今後公募という大原則にのっとって続けていくのか、そこら辺をお答えください。","respondent":"長田区民課長","answer":"今後の心配ですけれども、先ほど申し上げましたけれども、区の方針としても、基本は公募です。その結果、従来どおり財団が指定管理者になるというようなことも確率的にはあることです。","id":"exchange-042"},{"speaker":"須貝委員","kind":"質問・要望","question":"できるだけ多くの企業が参加しやすいように、先ほどほかの委員からもありましたけど、そのような条件整備を整えていただいて、今回のようなことが起きないように今後工夫していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"林（宏）副委員長","kind":"質問","question":"いろいろお話が出ましたけども、そもそも指定管理者に、それから市場化テストに移行している。財団に指定管理者がいて、そこの財団が利益が出るように計画を立てて、税金は納まってくるんか尋ねました。","respondent":"長田区民課長","answer":"ただ、これについては正直申し上げまして、いろいろな財団も、今の財団も黒字になっている施設があります。そういったことで、できるだけ上がってきた利益を区民に還元するというような方向での運営というふうに心がけていきたいというふうに思ってあります。","id":"exchange-044"},{"speaker":"林（宏）副委員長","kind":"確認","question":"それで、財団は３番の(1)、(2)はクリアできたんですか。その辺、どういう判断をされて、個人的に課長も選定委員の一人だから、何点をつけたか、この(1)、(2)。","respondent":"長田区民課長","answer":"そこの施設を全部任せるよ、利用料金制度を取り入れて、全部それでやりなさいよというようなことではありません。そういった中で、先ほどご指摘の財政的な問題というのは解決されるであろうというふうに思っているところです。","id":"exchange-045"},{"speaker":"林（宏）副委員長","kind":"質問・要望","question":"今回財団に行かざるを得なかったさまざまな問題は、きちんと解決をこの２年余りの間でしておいてあげないと民間が入ってこられない、次も、その次も。その辺、これからのことなんだけど、考えていたら聞かせていただきたい。","respondent":"長田区民課長","answer":"平成１９年度の後半ぐらいからそういった手続に向けてのさまざまな検討というのはなされなければいけないだろうというふうに思っています。ただ、そういった部分についても説明をした上で、きちっと一線のスタートラインに並ぶべきだろうというふうに思っているところです。","id":"exchange-046"},{"speaker":"林（宏）副委員長","kind":"意見","question":"一人談合という言葉があるのかどうかわからないけど。そういうプロポーザルのかけ方というのは、いいわけとの意見を述べました。","respondent":"長田区民課長","answer":"そちらの身分での仕事のやり方、こういう仕事のやり方というのは、当然あるんだろうと思います。","id":"exchange-047"},{"speaker":"林（宏）副委員長","kind":"質問・要望","question":"３年先、２年先だから、それはきちんと理事者で議論をして進めていってほしいな。そういうこの指定管理者の運営上の評価については、理事者側が下した評価は議会に報告すべきだと僕は思うんですけど、いかがか尋ねました。","respondent":"長田区民課長","answer":"評価の問題につきましては、毎年行いますので、これは協議をしますけれども、必要に応じてお出しをしたいというふうに考えてあります。","id":"exchange-048"},{"speaker":"須貝委員","kind":"質問","question":"１点ちょっと質問だけ。あるならば、その金額は大体毎年幾らぐらいなのか、ちょっと数字だけ説明を求めました。","respondent":"長田区民課長","answer":"そういった中で、最終的に通年で言うと４,４００万円ぐらいの指定管理料が区から出ていくと。平成１８年度につきましては、これは初年度分として乗っけてやらなければいけないというようなことで、１億円ちょっとの金額が出てまいります。","id":"exchange-049"},{"speaker":"中塚委員","kind":"意見","question":"採決ですけども、私は今日ここで是非を問うのではなくて、引き続き議案について継続して慎重な論議が必要じゃないかなと思うんですね。ぜひ委員長にお願いしたいのは、賛否を問う前に、今日議案の審査を終わるのか、それとも継続するのか…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"中塚委員","kind":"意見","question":"今日結論を出すということですけれども、私は慎重に議論をすべきじゃないのかなと思います。審議に当たっても、ここの範囲ともしないというのはおかしいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"}]},{"id":"topic-03","title":"の中学生の主張大会","agenda":"の中学生の主張大会","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"中学生が作文をつくって、自分たちの主張を発表し合いながら、ＰＴＡの方も参加者もほんとうにいい企画だなというふうに感じます。ちょっと伺いたいんですけれども、それをちょっと教えていただきたいのと、わかる範囲でいいんですけども。","respondent":"田村地域活動課長","answer":"それともう一点のほうは、こういう学校のほうで、最終的には校長会のほうで説明した後は、各校長先生の判断で推薦を上げてもらうという形です。青少年委員を大体１０名程度ということで、冊子を１,２００部ほど印刷しますので、そのようなことを考えております。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問","question":"一緒に参加する子どもの移動費というのはどういう、交通費なんかはどういう形なんですか、説明を求めました。","respondent":"田村地域活動課長","answer":"保護者も３名程度でそろって、付き添いで出席する方もいるので、各地区のほうで必要に応じて出している場合もある。ただ、すべてがそうだというわけじゃないです。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回ブラスバンドが参加したり、またたくさんの子どもがもっともっと参加できやすいようになればと思います。要望で結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"}]},{"id":"topic-04","title":"の平成１７年度「第２２回防災フェア」の実施","agenda":"の平成１７年度「第２２回防災フェア」の実施","exchanges":[{"speaker":"武内委員","kind":"質問","question":"防災情報ステーションなんですけど、これは２階で実施される予定か尋ねました。","respondent":"久保田防災課長","answer":"一応３階で防災フェアのオープニングをやりますので、そのときに３階のほうに展示して開通式をやりたいというふうに思っております。あそこのほうに設置しながら、統一する考え方からいけば、より人が集まるところをねらって今後ともやっていきたいというふうに考えております。","id":"exchange-055"},{"speaker":"武内委員","kind":"質問・要望","question":"移動式ということなんですか、その辺を考えていただきたい。防災センター、前に３階にあった展示関係は、今２階にあるんですか、それとも外、どこか別のところに保管してあるんか尋ねました。","respondent":"久保田防災課長","answer":"以前あった３階のいろんな展示物につきましては、なるべく２階で使えるものは移動しようということで、いろいろやりとりしていたんですが、やっぱり故障のものがほとんどでして、残念ながら全部使えないということがわかりましたので撤去しました。","id":"exchange-056"},{"speaker":"武内委員","kind":"質問・要望","question":"どうしても２階に防災関係が集約してくるんだろうなというふうに思っていたんですけど、私も中を見て、いいなと思うようなものもありました。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問","question":"一つ伺いたいのは、こうした機会を通じてたくさんの方が制度を知って、安心感を持って利用できるようにぜひ進めていただけたらなと思うんですね。ぜひたくさんの方の相談が実を結ぶような、そういう防災計画の運営や企画が進めばと思うんですけども、いかがか尋ねました。","respondent":"久保田防災課長","answer":"それから、私どもも消火器のあっせんチラシの中、あるいはホームページ等についてでも機会あるごとにその辺のＰＲ等はしております。防災フェア等についても、それぞれの機関でその辺の問題について、よりＰＲを強化するような形で今後も呼びかけていきたいと考えています。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"決算特別委員会の中でも積極的にＰＲしながら増やしていきたいというお話も伺いましたけども、そういうのも強く押し出した中で。最後に、広報ではＰＲのことについてはどのような形で進めていくのか説明を求めました。","respondent":"久保田防災課長","answer":"さっきお話ししたとおり、１月１１日号の広報にまずお知らせして、そのほか、町会の回覧とか、あるいは小学校に関しましてチラシの配布を毎年行っておりますので、そういう形でやっていきたいと思っています。","id":"exchange-059"},{"speaker":"伊藤委員","kind":"確認","question":"二つほど確認といいましょうか、先ほど午前中の質疑の中にも出ましたけど、洪水ハザードマップを品川区でつくっているという答弁がありました。実際やられていらっしゃる、そういうことについての現在説明はどうされているんでしょうかということを二つお答えください。","respondent":"久保田防災課長","answer":"例年ですとワークショップを実施してきた町会の様子とか、３階のフロアを活用しまして、一斉展示会というのをある一定期間設けてあります。ですから、この防災フェアの１３日以降、そういう形でも引き続き展示して、区民へのＰＲを図るような形で、そういうふうに考えております。","id":"exchange-060"},{"speaker":"伊藤委員","kind":"質問","question":"予想されるから、それに対する対応を行政としてどうしていくか。それをどう解消していくかということのほうがはるかに大きな目的でありますので、どういうふうに区民に易しく説明していくのかをお知らせください。","respondent":"久保田防災課長","answer":"今出てまいりました対応について、そういうことのＰＲ等もこの浸水ハザードマップで取り上げられるものは取り上げながら、そういうような啓発的なものも含めてやっていきたいというふうに今検討しています。","id":"exchange-061"},{"speaker":"伊藤委員","kind":"質問","question":"でも、できないところは当然あるわけですから、そういうところをどうぞ皆さん気をつけてくださいよということの意識啓発にもなるわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"須貝委員","kind":"質問","question":"そういうときに、地域で逆に展示されたほうが、これはこれでいいかと思うんですけど、また効果が上がるんじゃないかなと。これは地域ごとに消防団やミニポンプ隊があるわけですから、そういう方向性ですか、お考えを説明を求めました。","respondent":"久保田防災課長","answer":"基本的にはそういう役割分担を踏まえながら今回やってきたものですので、そうした面については継続していきたいというふうに思っております。やはり、そういう区民消火隊なり…","id":"exchange-063"},{"speaker":"須貝委員","kind":"意見","question":"どうしてもこっちまで来るとなると、ほんとうに１カ所で区で集める、体験させるということを主眼で考えていただければありがたいなと思います。それを希望して終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"林（宏）副委員長","kind":"質問","question":"だけど、この字を書くこともあるんだろうけども、意図が何か隠されているんなら教えてほしい。ライフラインと言われたからね。","respondent":"久保田防災課長","answer":"申しわけありません。特に特別な意味合いはありません。","id":"exchange-065"},{"speaker":"林（宏）副委員長","kind":"意見","question":"頭に東京都、そして品川区環境開発部防災課と、結構大きい字で書いてあった。組立式のトイレが学校にあるのはご存じだという前提で話をしているんですけどねとの意見を述べました。","respondent":"久保田防災課長","answer":"仮設トイレなんですけども、導入したのが相当古い……。","id":"exchange-066"},{"speaker":"林（宏）副委員長","kind":"質問","question":"まさに地域に中学生が入ってきてほしいということから始まってきているわけで、そういうお考え、募集をかけたりとかいろんなことをするのはね。だけど、そういう区民が中へ入ってきている、参加してきてもらうという考え方はどうか尋ねました。","respondent":"久保田防災課長","answer":"毎回防災フェアについていろんな工夫をしてやっていきたいというふうに考えておりますので、今の委員のご意見も踏まえまして、今後十分に検討していきたいと思います。","id":"exchange-067"},{"speaker":"林（宏）副委員長","kind":"意見","question":"ほんとうに防災というのは１軒１軒違うんですよ。ああなるほどなというのをやっていければ、こういうことをやることの意義も一つ広がるんじゃないのかなと思うのでお願いしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"}]},{"id":"topic-05","title":"のサービスコーナー開設","agenda":"のサービスコーナー開設","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"目的なんですが、「日中仕事などで忙しい方のために」とあるんですが、仕事をしていない方でも使ってよろしいんでしょうか。わざわざ目的に書いてあるので質問するのが１点と、なぜ荏原地区というと大きい範囲なんですけれども、まず２点お伺いいたします。","respondent":"上川内戸籍住民課長","answer":"双方の事情がございまして、それがなかなか実現できないというところもございまして、ちょうど武蔵小山のところに場所もございました。そういう中で、荏原地域のサービスコーナーというもともとの願望というか、探していたところがありましたので、武蔵小山に決定したところです。","id":"exchange-069"},{"speaker":"藤原委員","kind":"質問","question":"今武蔵小山に土地がいいところがあったということなんですが、この土地はどこが所有しているんでしょうか。どこが所有しているのかというのと、貸借関係というのかな、区の土地ではないと思うんですけれども、どんな関係になっているんか尋ねました。","respondent":"上川内戸籍住民課長","answer":"そこの土地というのがサービスコーナーにというお話があったものですが、その窓口はまちづくり事業部のほうが窓口で、その事業をやっております。３年間ぐらい、事業を予定しておりますので、３年間程度の仮施設ということでサービスコーナーをそこの１階に置くです。","id":"exchange-070"},{"speaker":"藤原委員","kind":"意見","question":"このサービスコーナーというのは、３年間の仮施設なんですね。じゃあ、その後の３年後のサービスコーナーというのはどうなるのかということと、その後のことは東急とどのような話になっているのかとの意見を述べました。","respondent":"上川内戸籍住民課長、山田区民生活事業部長","answer":"３年間の仮施設としてそこに仮設のユニットみたいなもので対応するわけですが、仮設ユニットも３階程度を予定しておりますので、まだ今後検討ということです。 今回実施計画にも盛り込みましたので、仮施設３年、施設としては担保していくと。ただ、その下の１階のところには、サービスコーナーということは担保されているというふうに進めているところです。","id":"exchange-071"},{"speaker":"伊藤委員","kind":"質問","question":"今の件で、３階建ての建物をつくるというお話だったんですけど、２階、３階は何に使うんか尋ねました。","respondent":"上川内戸籍住民課長","answer":"この建物はもともと事業関連で東急側が施設をそこに使いたいというお話がございましたので、２階、３階は東急側がその事業の関連の施設としてお使いになるです。","id":"exchange-072"},{"speaker":"伊藤委員","kind":"確認","question":"そうすると、確認するんですけど、２階、３階は東急が使いますよと。ユニットを建てる費用と３年間分の東急が使う使用料を相殺するという考え方なんですかということの確認をお願いします。","respondent":"上川内戸籍住民課長","answer":"その区有地の賃借料のかわりに東急が建物を建てて、１階部分を区が使用するです。","id":"exchange-073"},{"speaker":"伊藤委員","kind":"確認","question":"これで確認だけで終わりますけど、土地は品川区のものですよと。３年目以降は、そのときの品川区の行政の判断で何をつくるかこれから検討していくということでよろしいですね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"実際、今大井町でやっていて、利用客の数から出したのかどうか、そこを教えていただきたいのが一つ。職員の体制はどういう形で、交代も含めて常駐なのか、人数を教えてほしいと求めました。","respondent":"上川内戸籍住民課長、山田区民生活事業部長","answer":"職員体制は大井町と同じようにローテーション、大体常時２名から３名程度のローテーションで行います。やはり、土曜日が圧倒的にサービスコーナーにつきましては多いということで… 目黒区との関係なんですけれども、実を言いますと、目黒区の同じような担当のところと相互乗り入れできないかという申し入れはしたところなんです。新たに広げる考えはないということで、これは単独で…","id":"exchange-075"},{"speaker":"林（宏）副委員長","kind":"意見","question":"要するに、駅に近いというか、大井町は駅の中、地域センターのやっている作業、ここの９まで全部やっているんだよね。やっているんだよねとの意見を述べました。","respondent":"上川内戸籍住民課長","answer":"やっています。","id":"exchange-076"},{"speaker":"林（宏）副委員長","kind":"質問","question":"だから、土日お勤めしている人、それから駅に近いということで、勤めの行き帰りにという利便を提供するということの考えだよね。主要じゃない駅といわれると困るけど、幾つかのそういう駅に設置できればしていこうと、そういうお考えを持っていらっしゃるんか尋ねました。","respondent":"上川内戸籍住民課長","answer":"実施計画の中で大井町サービスコーナーに続いて、部内の中で地域センターとサービスコーナーの部分のところの役割分担等の中で今検討しております。今後来年の秋ぐらいには方向性を出せるように検討をしていきたいと考えています。","id":"exchange-077"},{"speaker":"林（宏）副委員長","kind":"意見","question":"区民へのサービス向上、特に土日は完全にシャットアウトになっているところがこういうふうに使えるようになる、あるいは５時以降というのかな。ここは火曜日の夜にあいているみたいだけれどとの意見を述べました。","respondent":"田村地域活動課長","answer":"地域センターとサービスコーナーのあり方、今年の５月から議会のほうの指摘もありまして、自主的に検討を進めよう。ですから、来年の秋ごろをめどにどういう整理をしていくのかということを今検討している段階なので、そういうのも当然視野に入れて。","id":"exchange-078"},{"speaker":"林（宏）副委員長","kind":"質問・要望","question":"やっぱりあるものを生かすという考え方が一つ基本になきゃおかしいし、また区民の利便性に新しいものが必要だという考え方もいい。ぜひきちんと区民の立場に立って計画を立てていただきたいとお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"}]},{"id":"topic-06","title":"の平成１８年版、ごみ・リサイクルカレンダー","agenda":"の平成１８年版、ごみ・リサイクルカレンダー","exchanges":[{"speaker":"武内委員","kind":"質問","question":"２０万部を作成されたということなんですけども、１部当たりどれぐらいの経費がかかったのか、あと、１２月中旬までに区内の全世帯に配布する予定ということですけど、配布の方法について説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"これが２４万円の広告が入っておりますので、１部当たり１６円弱、１５円８０銭の経費になるというものです。配布ですけれども、清掃事務所の職員が区分けをしまして、作業の終了後等に順次全世帯に配布に回るです。","id":"exchange-080"},{"speaker":"武内委員","kind":"意見","question":"１６円弱ということで、非常に安いのかな、ちょっとわからない。例えばシルバー人材センターの方にお願いするとか、そういう経費の問題もあると思うんですけど、その辺の検討もされたと思うんですけどとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"考えたんですけれども、これは５年目に入っておりますけど、こういう形でやらせていただきたいと思います。","id":"exchange-081"},{"speaker":"武内委員","kind":"質問","question":"ちょっと別の質問で申しわけないんですけど、この地域は何時ぐらいに来るかとかというのは、しょっちゅう変わるんでしょうか。それとも、ある程度何年間か、何年間ということはないんでしょうけど、決められた時間帯で動いていらっしゃるんですかね。","respondent":"中山清掃リサイクル課長","answer":"作業の計画と申しますけど、毎年実は変更しておりまして、時間の変化がございました。今の予定ですと、１９年度ぐらいまでの２年間については、対応できるようになるかなというふうに思っておりますので。","id":"exchange-082"},{"speaker":"武内委員","kind":"意見","question":"ぜひ、すごく難しいと思うんですけど、時間がやっぱり一番いろんな方からそういう希望があるので、ただなかなか難しいというのはわかっていますので、難しいんですけど、なるべく大体の時間帯がわかるような方向性に進まれるようにぜひお願いしたいというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"木下委員","kind":"質問","question":"今の質問に関連することだと思うんですが、ごみカレンダーの中に、朝８時まで出してくださいと記入されていますよね。昔はあったと思うんですけど、これはちょっと希望での話なんで、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"中塚委員","kind":"質問","question":"もし、ご存じだったら、２３区でこういったごみカレンダーをつくっているところはほかにあるんですかね。ちょっと教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"２３区で、私の知る限りないと思います。多摩地区においては、こういう形でごみの収集の曜日が変わったりするような地区もありますので、導入されているところもありますが。","id":"exchange-085"},{"speaker":"林（宏）副委員長","kind":"確認","question":"いわゆるこの区民委員会に係る関連の質問があって、１回目に入れてもらって、公開はされているんだよね。それをちょっと部長なり課長に確認をしたいのと、僕も所属の議員として確認をしておきたいことが１点と、それを教えてほしい。","respondent":"岩崎環境清掃事業部長","answer":"「廃棄物減量等審議会は非公開です」というようなことを主張なさいました。あれっ、翌日訂正するつもりはないんだというようなお話を言ってこられたものですから、これは弱ったなというようなことで思っておりました。","id":"exchange-086"},{"speaker":"林（宏）副委員長","kind":"質問","question":"一般質問に関連してというほどの、公開していないという断定的にすることは僕らはちょっと異議することだと、委員長から一言。意思だから、自分の発言が残るという意味だから、伝えてあげてくれればありがたいなというふうに思いますので、お願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"木下委員","kind":"確認","question":"そういうふうに言った発言に対して訂正するつもりはないと、ほんとうに井上議員のほうがそのようにおっしゃったんでしょうか。確認で。","respondent":"岩崎環境清掃事業部長","answer":"そのとおりなんですが、もし、何でしたら、委員長がご確認いただくか、そういう手順はどういうふうになるのかは議会のほうにお任せいたしたいと思います。","id":"exchange-088"},{"speaker":"須貝委員","kind":"確認","question":"我々も一般質問の趣旨を聞いていますので、それは教育委員会のお話だったと思うので、ちょっともう一回事実関係を井上幹事長に確認をとってみます。それで、あとどういう認識でそういうお話をしたのか、その辺もちょっと一度持ち帰らせていただきまして、また委員長のほうに報告します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/678828?Template=document&Id=2442#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":59902,"voices":222}},{"id":"h17-20051128-7","meetingId":"h17-cm11","date":"2005年11月28日","dateIso":"2005-11-28","committee":"厚生委員会","time":"午前１０時０２分～午後３時３１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を82件整理しています。","topics":[{"id":"topic-01","title":"の１、議案審査","agenda":"の１、議案審査","exchanges":[{"speaker":"川西委員","kind":"質問・要望","question":"２つ目は開設の日時なんですけれども、６月１日。４月１日になぜならないのか、教えてほしいと求めました。","respondent":"高橋幼保一元担当課長","answer":"お尋ねの開設がどうして４月１日にならないかというお話ですけれども、幼稚園の部分については４月１日から開設する予定です。３月中旬にできる予定になってありますけれども、現在、２カ月の期間を置くのがスムーズな受け入れ体制ができるのではないかと考えているところです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"０歳と１歳、２歳と３歳というふうになっていて、どう表現したらいいのかわからないけど、クラス別になっていないんです。この辺で集団の考え方がどうなのかなという疑問を持っていますので、まずそこのところをお答えください。","respondent":"高橋幼保一元担当課長","answer":"設置基準については通常どおりの部分であると思いますけれども、４、そういったクラス別保育ができるように考えてまいりたいと思います。それと、今、話しました設置基準について、狭いですけれども、設置基準以上の面積で設定しています。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１歳の小さいときに、そこをお聞かせいただきたいのと、乳児のところからずっと成長していくわけですね。教育のところがどうなのかなと思うんですが、単純に比較して、職員配置がどうなるのかというところをお聞かせほしいと求めました。","respondent":"高橋幼保一元担当課長","answer":"幼稚園部門につきましては、従来どおりの４歳、５歳、園長も含めれば１人ですけれども、２人から４人体制ということで考えているところです。子育ての専門非常勤として１人、８時間の人が２人というような考え方と、あと延長保育については１０人という感じで考えているところで…","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"睡眠と小集団のところ、これは意見なので、今後考えてほしいなと思うのが、０歳、１歳のところが合計で１６人ですよね。専門非常勤１人と、あと延長用の職員で１０名と、もう１回説明を求めました。","respondent":"高橋幼保一元担当課長","answer":"預かり保育につきましては、８時間の資格のある派遣の方２人でみていくということを考えているところです。それと、幼稚園部門ということでは、幼稚園教諭の活用ということも含めて考えているところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"派遣の有資格者の方がみていて、あと延長のところは非常勤が加わっていくということなんですか。二葉保育園は激変緩和で２年間は従来どおりと書いてあるんですが、なぜ月額利用がなくなったのか、ちょっとその辺をお説明を求めました。","respondent":"高橋幼保一元担当課長","answer":"預かり保育利用料につきましては、今度新しくつくった４時半までの支援型の預かり保育等のこともございまして、今までと違った形で。不必要な月額利用を抑制し、広くこのことが区民の皆様にご理解いただけるように考えていますので、よろしくお願いします。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"月額利用がなくなったというところで、どのくらい影響が起きるのかなというところも１点お伺いしたいと思います。１万円を超える負担増になるというところでは、その点が１点と、その辺を説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"意見","question":"ここで配膳ということですけれども、小学校の給食と、特に保育園の０、１、２の給食というのは、かなり刻みからして、味つけからしても内容が異なると思うので、そこら辺がどのように手が加えられて提供されるのかという、その辺を説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"意見","question":"０、１、２だけじゃなくて、幼稚園のところも、学校とは違うと思うんですね。その違いをどういうふうにして提供するのかというところを説明を求めました。","respondent":"高橋幼保一元担当課長","answer":"最初ご説明したように、１、２については公立保育園の給食献立で提供していきたいと思っています。そちらの方に移行したいという考えの中で、４月に入園されるお子さんたちを抜かして、平成２０年４月１日から新たな料金体系を考えているところです。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間を見てきても、サラリーマン層の所得が、このところ７年間続けて低下しているという状況があるんです。子育てのところ、経済的支援を求めていることに対して、この預かり保育料のところで反対ということで態度を表明します。","respondent":"石田委員長","answer":"設置はいいということね。もう１回ちょっと。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"意見","question":"第８０号議案は保育園をここで設置するという内容なので賛成をいたします。第８３号議案については、預かり保育のこの利用料のところで負担増に対して反対ということで、第８３号議案には反対の態度をとらせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問・要望","question":"保育に欠ける世帯も幼稚園を選択でき、預かり保育ができる、充実するということで本当に期待をしております。例年ですと定数が大体３０名台だと思うんですが、今の１２月前で、何かこの辺のところは原因みたいなものがわかれば教えていただきたいんですけど。","respondent":"高橋幼保一元担当課長","answer":"１１月の部分で終わったところなんですけれども、最初の出足としては少ないという感じですけれども、ちょっと心配しているところもあります。そういう状況です。","id":"exchange-011"},{"speaker":"山路委員","kind":"質問","question":"私の態度は第８０号、第８３号、賛成です。この関係から、私は個人的にはそういう心配をしていたんですけれども、そこらのかねあいは心配ないんか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"４月、そして転園するという形での６月台場保育園という形になるのではないかと思いますけれども、まだその辺見通し等はまだ立てられない状況です。あけてみるのが楽しみなところです。","id":"exchange-012"},{"speaker":"山路委員","kind":"質問・要望","question":"そのまま保育園の方がいいか、今の流れでこちらの方にもやらせたいという、その辺をよく現場で質問を受けるわけなんですね。その辺を悩んでいるお母さん方の相談を聞いていただいて、今後も徹底してほしいと求めましたが、その辺は区の方には相談はありますか尋ねました。","respondent":"高橋幼保一元担当課長、小林保育課長","answer":"予定しているのが、１月１９日に２時からと５時から、台場の幼稚園・保育園についての説明会を開催する予定です。これにつきましても１２月１１日号の方に載せてまいりたいと思っています。 これから１月に入りますと、４月１日通常の保育園の入園予定者の募集等が行われます。保護者の方が適切に選択していただけるように、十分な情報提供、ご説明を行ってまいりたいと思います。","id":"exchange-013"},{"speaker":"山路委員","kind":"質問・要望","question":"それぞれありがとうございました。こちらの施設でよかったと思われるような精神で接していただきたいことを希望いたしまして、第８０号議案、第８３号議案は賛成です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"須藤委員","kind":"質問","question":"この保育園・幼稚園の保育士、教諭、こういうメンバーがどういう形になるのかなと。もし新規採用であるならば、そういう新しい試みをちゃんと理解できるような教育講座というか、その辺がどうなっているか説明を求めました。","respondent":"小林保育課長","answer":"台場施設の要員については今後検討しますが、新規採用者が配置されることもあります。本年は大崎保育園におきまして幼稚園教諭を２名配置して、相互理解、保育を託すのに最適なメンバーを今後選定してまいりたいと考えております。","id":"exchange-015"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、新しい試みになってきますので、そのあたりをしっかり考えて配置してほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"本多委員","kind":"質問・要望","question":"全体的なところで確認をさせてください。例えば指定管理を受けた５年なら５年の間に行政委員がかかわるとか、その辺の手続的にどうなのか、ちょっと教えてほしいと求めました。","respondent":"谷田部健康課長、早津高齢福祉課長","answer":"ご質問の趣旨は、行政委員といいますと、教育委員だとか、そういう兼職の関係でしょうか。この指定管理者の中には、そういう意味での行政委員というんでしょうか、それは児童保健事業部関係ではないです。 議員の方が評議員として入られたりということがありますが、この指定管理者として委託関係に立つかどうかということとは別物ということになります。指定管理者になるかどうかということと…","id":"exchange-017"},{"speaker":"本多委員","kind":"確認","question":"我々も議決が必要ですから、手続的に確認をしたいということでこういう質問をさせていただいているんですが、そういった部分で運営主体とか。それだけちょっと確認ということなんですよ。","respondent":"早津高齢福祉課長","answer":"ちなみに、当委員会に付託されているものについては、いずれも評議員、理事に行政の人間が入ってはおりません。評議員として、その問題と委託するということについては別の問題ということですので、指定管理をすることについて支障はございません。","id":"exchange-018"},{"speaker":"須藤委員","kind":"質問・要望","question":"これでいいですかというだけの話ではないと思うので、私は委員長にお願いしたいのは、しなきゃいけない。そこまで議会の中で指定管理者制度をチェックしていくためには、委員長にその辺の考え方を伺い、理事者の方で整理していただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"石田委員長","kind":"提案","question":"しっかりその提案ができているかということで、そこの提案書の内容が一番私は問題かなと思っておりまして、私もある程度移行期の部分もあり。今、必ず委員会の中でもう一度それはいろいろな場面の中で…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"須藤委員","kind":"質問・要望","question":"我々は委員会としての責務が果たせるんじゃないかという感じがあるので、そこが今日のままでいいのかどうかというのをお考えを聞かせていただきたい。委員の皆さん方ともね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"そこのところで問題がなくてこうですと出されたものを見て、あ、そうですかと言って受けるのでは、議会の役割が果たせないと思っているんです。基本的なところではきちんと判断できる資料をいただかないと、判断はできないということははっきり申し上げておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"山路委員","kind":"提案","question":"現場現状といいますか、見ていますと、いろいろな問題もなきにしもないと思うんですね。そういう面では、チェックするということで、須藤委員から先ほど提案がありましたけれども、法人の事業に対する資料が必要かなという考えですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"川西委員","kind":"質問","question":"特に区が法人をあらかじめ計画して設置され、運営をずっと見てきた法人への委託なので、私は全面的に別にあまり異議は感じておりません。ですから、今おっしゃっているようなご意見は必要なことになるんじゃないかとは思いますけれども、そのような考え方です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"本多委員","kind":"確認","question":"先ほど質問をさせていただきましたように、全体的な意味で手続的な確認をしなければいけないと思いまして、先ほど質問させていただきました。個々の審議については現行の資料で審議できるものと考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"石田委員長","kind":"提案","question":"１５議案ということもあって、私はこの資料の中で移行期間、この議事を進めていこうと思ってこういう諮り方をさせていただきました。提案したところと、あと実績報告書をどう見るのかというところがこれからあると思いますので、どうぞよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"須藤委員","kind":"意見","question":"わかりました。概要とか、僕らが議決する事項は３つしかないけれども、この資料で審査をするという形にしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"山路委員","kind":"質問・要望","question":"今後といいますか、先のことをちょっと考えますと、ここの３ページの５番に載っていますよね。サービスの向上の評価、この辺は選考委員会と区としてはどういうシステムでやっていかれるか、考えられることを説明していただきたいと思うんですが。","respondent":"辻田児童課長","answer":"今、須藤委員及び山路委員の言うこと、それぞれ傾聴すべき部分が大変多うあります。そういう意味で、今後につきましては、そういう事業報告というようなものについてどういう形で報告していくか、検討してまいりたいと考えております。","id":"exchange-028"},{"speaker":"山路委員","kind":"質問・要望","question":"ああしてもらいたいという意見もあるわけでありますけど、品川区の現状では私はベストと思っていますので、１５議案には賛成です。ここにうたってあるだけということでありますけど、やっぱり的確に実行していただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どこがどう変わっていくのかというところを１点お答えいただきたいのと、民間参入のところも考えて、あと情報公開のところなんです。区はどういうふうに把握をして、どういう考えを持っていらっしゃるのか、まずその点をお伺いします。","respondent":"谷田部健康課長、早津高齢福祉課長","answer":"これなどはまさしく基本的な考え方の１点目の利用者に合わせた対応で、平成１９年度、指定管理者導入に向けて検討していくです。私の方で基本方針をご説明させていただきましたのは、２… そうした中で、こういったことについても門戸を開いた形で対応していくのが、総合的な福祉増進のためにはいいのではないかと考えています。４法人におきまして…","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この基本的なところに沿ってもうちょっとお伺いしたいんですが、１つは、あと区民などを参加させていく必要があると思います。その点をお伺いしたいのと、行政としてはどういった資料を求めて判断をするのかなというところの中身をお聞かせほしいと求めました。","respondent":"辻田児童課長","answer":"みんないろいろな意見を出されて、その適否について検討したわけですけど、特にいわゆる会議録みたいなものはその中では作成はしていないです。これについて山路委員にお答え申し上げましたけど、今後ちょっと検討するということで考えております。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"出てくる結果だけで判断をというところでは、私は不十分であると思うので、ぜひここの部分は改善をお願いしたいと思います。そこのところをお伺いしないと、これに対してどうだったのかという評価はどうなっているのか、お聞かせをいただきたいんですが。","respondent":"辻田児童課長","answer":"この中で普通と判断されたのが２の中の(1) の公の施設の管理者として適切な施設維持管理の考えを持っているかということと、それともう１つは。しかし、そのほかの項目についてはかなり高い評価をしているということで結果を出しております。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、そういった面ではとても重要な役割を果たしているわけなんですけれども、この辺の職員体制を判断するような基準というのはあるんでしょうか。この辺がどういうふうになって適正と言えるのかどうかというのが非常に判断がわからないんですけれども。","respondent":"辻田児童課長","answer":"それから、またほかの子育て支援センターであるとかいうものにつきましても、区基準を上回る全体で常勤職員が１３名という形で配置されております。そういうことについて協力して事業を実施しているという実態があるということで。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"態度表明のところで、先ほど申し上げましたように、資料のところでは不足であって、議会がしっかりと判断をできる資料を出していただきたいという意見をつけて、今回は今までの品川区内での実績のある社会福祉法人に指定ということで、賛成をいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほどは要望でとどめたんですが、開示の方向を示していただきたいのですが、この点が１点です。別紙３のところには総合の評価を載せていただいて、できたらわかりやすい方法で提出をしていただきたいなと思うんですが、その辺はいかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここの施設は具体的にどうで、どう判断したのかというあたりは、具体的なものがあるのかどうか。具体的には５段階とかというのもありましたけれども、基準と評価の仕方がどうなっているのか、お聞かせをほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ページ４のところで、情報公開のところで、そのできる以前に既に指定管理者に旗の台の心身障害者福祉会館などなっていますよね。は協定書の中で盛り込む、どちらかしないとそこがチェックできない部分になると思うんですが、その辺についてご説明をほしいと求めました。","respondent":"早津高齢福祉課長","answer":"１月の理事会において情報公開の規定を制定するというふうに聞いておりますので、いずれの法人もそれで出そろうというような形になります。そうそう出せるものも出せないというようなことはなかろうかというふうには理解しておりますが…","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、規定のされる前段階でも出るというところで、その辺では、直接法人に適用するという形で得ることになるのでしょうか。役所の方を通して、どちらか尋ねました。","respondent":"早津高齢福祉課長","answer":"法人の固有のものであれば法人へということになりますし、例えば今回の審査にかかわるようなものであれば、法人から提出されたものについては区で管理している限りは区の情報公開条例の適用対象になりますので、こちらの方にご請求いただいても結構です。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"かなり今、正規職員と非常勤職員のバランスというんですか、すごく介助する側として悩んでいるんだというご意見を複数伺ったことがあるんです。ここのところでどのようにチェック、評価ができるのかなという思いを持っているんですが、いかがか尋ねました。","respondent":"早津高齢福祉課長","answer":"入浴介助ということを１つとっても、あるいは浴槽の構造がどういうものであるかというようなことによって、かなり作業というのは変わってまいります。なおかつ、サービス評価についても積極的に取り組んでいるというような、そういう事柄の中で全体的な評価をしたです。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"最後になりますけれども、サービス評価、あと、苦情の処理、この辺をどのくらい行政の方としては把握できているのか尋ねました。","respondent":"早津高齢福祉課長","answer":"サービス向上に取り組む自発的な職員の組織をサービス向上委員会としてそれを支援するような形で点検活動も一昨年から進めているところです。苦情対応者というようなものを定めて、苦情が利用者の胸の内におさまらずに、それぞれの対応ができているというふうに考えてあります。","id":"exchange-040"},{"speaker":"須藤委員","kind":"質問・要望","question":"その場合に、どういった協定内容ができるのかなというのが、あらあらでいいですから教えてください。認定した議会はどこまでそういった場合にかかわってくるのかというようなあたりがどういうふうになってくるのか教えてほしいと求めました。","respondent":"早津高齢福祉課長","answer":"あらあらで考えている段階ですが、それから個人情報の保護に関すること、そういった内容を盛り込む予定です。それはもう案件によって違ってくるのではないかというふうに考えてあります。","id":"exchange-041"},{"speaker":"須藤委員","kind":"質問","question":"そういった内容的なものもある程度教えていただければいいんじゃないかなと思うので、どうですか、出せるようなんですか。この辺のところについては協定を結んでいきたいという方向性は委員会の中で資料として出されてもいいんじゃないかと思うんですが、いかがか尋ねました。","respondent":"早津高齢福祉課長","answer":"その書類等につきましても、議会にご了承を求めなくてはいけない部分というのは、やはり一定あるのではないかというふうに考えているものです。この管理者問題については、全体的な統一を図る必要があると思いますので…","id":"exchange-042"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、どういう事態が起こるかわかりませんけれども、ちょっと「はい」と言うのはなかなか難しいのではないかなというのが現状のところなので。二押し、理事者の方々に骨を折ってもらって、我々が本当に大丈夫だなという形までの資料提供をしていただきたいというふうにお願いをしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"本多委員","kind":"質問・要望","question":"それと、選定委員会の議事録を公開するべきだという意見があったんですが、私はこの意見には全く反対でして、例えば、プロポーザルなんですよね。一般で行くと資料を戻すというんですか、議事録の公開というのは、これはやるべきでないと思います。","respondent":"木下福祉高齢事業部長","answer":"指定管理に関する基本方針の３番のところ、(2) 番の選定委員会の最後のところにもありますように、選考結果および選考理由は公表する。そういうような考え方で、やはり１つの重要な視点として踏まえていくべきものかというふうに思っておりますので…","id":"exchange-044"},{"speaker":"川西委員","kind":"提案","question":"というのは、特別養護老人ホームの中で、現在提案されている３施設のみが、今まで区立施設、管理委託をしていたと。この３施設とほかの、この施設だけが区立として存続運営されなければならなかった設立のときの理由というのは何かあるのか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"大分昔の経過になるんですけれども、品川の場合、区の土地に社会福祉法人を設置してやってきたという経過があります。やはり品川区として特養を幾つあるんだというときに、やはり区立の特養を持っていた方がその部分での説明もしやすいというようなこともありまして。","id":"exchange-045"},{"speaker":"川西委員","kind":"質問","question":"３,０００万円組んだとかというようなことがありますけれども、そういうときには区の資金援助というのは、これからもあるのでしょうか。あってもらわないと私は困ると思うんですけれども、よろしく。","respondent":"早津高齢福祉課長","answer":"修繕については、基本的に今までと変わることはございません。介護保険制度の報酬の中には一定部分の改修経費ですとかというようなものを考えておりますので、これは区と法人と、そういう考え方です。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"１０月１日から介護報酬の改定とか、給食のところが変わったりとか、そういう部分というのは把握されているのかどうかと。その辺、委託先が変わったとか、そういうところの評価とかをここでできるのか尋ねました。","respondent":"早津高齢福祉課長","answer":"委託先が変わったということは今の段階では聞いてございません。１０月からの改定に伴って食事がまずくなったという声も、注意してまいりたいというふうに考えてあります。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"この辺の評価とか、やっぱりその利用者の側のところがどれだけ本当に盛り込まれて評価ができるのかというところがすごく大事であると思うんです。その辺のところは、行政としてはどこでどう評価しているのか説明を求めました。","respondent":"早津高齢福祉課長","answer":"当該の各法人は、そういった点でも私どもは自信を持って、この団体がよかろうというふうに考えているところです。８０人規模であれば１,０００万円を超えるような減収にはなりますが、私どもも今後十分注意してまいりたいというふうに考えてあります。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それともう１つ、その上の２番目のところなんですけれども、これはどういうふうに判断されるのかお聞かせいただきたいんです。そしてこれはどういうふうに実際のところは判断されるのかというふうなあたりを教えていただけないか尋ねました。","respondent":"早津高齢福祉課長","answer":"施設においての工夫というようなこととも関連しますけれども、食事においてはさまざまな工夫をしておりますし、個別の方の対応をしております。これは個別的な対応を旨とするようなグループホームですとか…","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私はこれをぜひ充実させていただきたいと思うんですが、そういうことはぜひ改めていただきたいなということを１つ要望させてほしいと求めました。その評価したものの１つ１つに対しての評価をしたそれに対してのまとめた資料というものはあるのかどうか、そのことについてだけ確認させてください。","respondent":"早津高齢福祉課長","answer":"これは福祉高齢事業部の方も個別の細項目に沿って５段階の評定をいたしました。８０点以上というような形にはなっておりましたけれども、これをそのまま外にお出しするというようなことは現在のところ考えていないところです。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これはぜひ私は評価結果に対しての公表というふうなものは明らかにしていただきたいというふうに要望させてほしいと求めました。なかなか判断もできないというふうなこともありますし、ぜひ区民に対しても公表していただきたいという要望をして終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"川西委員","kind":"質問","question":"この高齢者住宅については、下の３階の窓口で１２月ごろに募集をして、待機者を募り、順次入れていくという制度をやっていますよね。このシステムは全然変わらないのかどうか説明を求めました。","respondent":"蓼沼高齢事業課長","answer":"ただいまのご質問、入居者の募集、受付、それから選考方法、入居の審査会で審査をするわけですけれども、そういった従来のシステムについては変更はございません。","id":"exchange-052"}]},{"id":"topic-02","title":"の２、請願・陳情審査","agenda":"の２、請願・陳情審査","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"説明いただきまして、２３区中３番目という数字をいろいろ説明いただきました。そういった部分というのはどこまで、考え方です、数字どうのこうのというより考え方についてちょっとお聞かせいただきたいと思うんです。","respondent":"高橋幼保一元担当課長","answer":"経済的支援というところでは、補助金の部分を見てまいりますと、２１園で１１万５,０００円程度になってあります。我々の考え方といいますと、やはりそれぞれの保護者の方の選択というところでとらえていただきたいと思っているところです。","id":"exchange-053"},{"speaker":"本多委員","kind":"質問","question":"所得の４割がという話だったんですけれども、そういった意味で、現状の制度はわかります。ただ、そこの格差是正について、もうちょっと進められないかなというふうな思いがあるんですけれども、いかがか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"所得制限を設けているところが３区で、３２万円制限という制限があるのが１区で、３３万円の制限ということで１区が対象になっています。補助金額の平均というのは７,２００円ということで…","id":"exchange-054"},{"speaker":"本多委員","kind":"質問・要望","question":"この就学前というところで、幼稚園についても、なお一層そういった働きかけをしてほしいと求めました。要望として終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"須藤委員","kind":"質問","question":"ちょっと理事者にお聞きしたいのですが、子育て支援で親御さんが一番大変だと思われているのは何の原因が出ていますでしょうか。一般の調査なんかでは。","respondent":"辻田児童課長","answer":"統計的には経済的負担がというような部分が一番多うあります。","id":"exchange-056"},{"speaker":"須藤委員","kind":"質問","question":"品川区の私学の幼稚園へ行っている方と、公立の幼稚園へ行っている方の数を教えていただけますか。","respondent":"高橋幼保一元担当課長","answer":"公立に行っている園児につきましては５２２名で、私立の方が３,１１９名です。","id":"exchange-057"},{"speaker":"須藤委員","kind":"質問","question":"３,０００幾らの方が５００何人のところへと。そうすると、品川区全体の中で見ていってやるということが必要ではないだろうかなというふうな思いがあるんですが、そのあたりはいかがか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"親の負担、支援として品川区が進めてきている中では、やはり私立幼稚園に昭和４０年代には幼児教育を担ってもらった部分があると思うんです。幼稚園におきましては、そういったものもあわせて持ち…","id":"exchange-058"},{"speaker":"須藤委員","kind":"質問","question":"ただ、こういった私立の幼稚園を上手にお互いに連携をとって子育て支援策というものをつくっていくということが必要だろうと。品川区は一生懸命やっていただいていますけれども、今後ともそのあたりが必要ではないかなというような気がいたしますけれども、いかがか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"品川区が子育て支援を進める中で、品川区の子どもたちをいかにうまく０歳から就学前の子どもたちを教育、それから公私立保育園も連携する中で子育てについて考えていきたいと思います。","id":"exchange-059"},{"speaker":"川西委員","kind":"質問","question":"１つ最初に質問ですが、入園料補助金というのは、所得制限はなかったんでしょうか。済みません、伺います。","respondent":"高橋幼保一元担当課長","answer":"入園料補助金につきましては、所得制限はなく全員の方に支給するようになってあります。","id":"exchange-060"},{"speaker":"川西委員","kind":"質問","question":"一般質問とか、幼稚園における預かり保育というのをさらに充実してほしいという、そういう考えを強く持っています。2)、3)と複雑な面も、趣旨採択というのはできないでしょうかという意見を持っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私もあちこちで若干伺ってきたんですけれども、その辺をお答えいただきたいのと、ほかの事業で埋めているというところもおっしゃられていたんです。そういった面では、もう少し支援が必要ではないかなと思っているんですが、いかがか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"品川区、平成１４年度から預かり保育の補助金というものがありますが、平成１２年から５年間で預かり保育のモデル事業として進めてきたところです。現在、品川区も預かり保育の補助金については考えてまいりたいと思って検討していますが…","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"特に幼稚園に預けていてもお仕事をされている方が増えていらっしゃるというところも伺っていますので、ぜひお願いをしたいなと思います。もう１点なんですが、私立幼稚園振興のための母の会連絡会への助成というのは、どういう中身なのかちょっと教えていただけますか。","respondent":"高橋幼保一元担当課長","answer":"こちらの中身については、目的といたしましては、区内の私立幼稚園相互の連携を図るということで、私立幼稚園同士の親交のための事業として拡大してまいりましたもので、それをもって教育の向上に寄与するというところで、こちらは区独自のものです。","id":"exchange-063"},{"speaker":"山路委員","kind":"質問","question":"１つ１つ説明をいただきまして大体わかったんですけれども、今現在、８万５,０００円まで平成１５年以来上げていただいた。経緯としまして、大体何年に１回ぐらい上げていただいているのか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"品川区におきましては８万５,０００円の補助金を出している、何年に１回改正するということなく、平成１５年度に改正したばかりです。","id":"exchange-064"},{"speaker":"山路委員","kind":"質問・要望","question":"総務委員会のときも、１回、幼稚園の補助金の件がありましたので、ちょっと勘違いしておりまして、入園料補助金ということで理解をいたしました。総合的なことを考えますと、我が党の議員も紹介議員になっておりますので、できる限りの努力をしていただきたいことを要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"経済的負担の軽減をしていく方向をやっぱりずっと求めていきたいと思いますし。やはり補助のところを厚くしていく必要があると思っていますので、採択と言いたいんですが、とりあえず採択という。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"須藤委員","kind":"質問","question":"先ほどから質問の中でお話ししましたように、そういった意味での考え方も踏まえながら、この幼稚園の母の会の考え方を持っていってあげたいなというふうに思っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"4)のところの都加算補助を求めているわけですけれども、人員の配置が実際にここにかかわる部分が何人いるのかとか、金額的にどのくらいの補助になっているのかというところを具体的に説明を求めました。","respondent":"小林保育課長","answer":"０歳児保育の特別対策、それから１１時間開所の保育対策、あるいは一般保育対策事業等があります。現在、私どもちょうだいしている対象となっているのが、延長保育と産休代替と職員の補助の部分の金額を補助としていただいております。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問","question":"財調に入っている部分においては、このまま引き継いで実施をされるというふうに受けとめてよろしいのでしょうか。１１時間開所とか、今までどおりお金を使えてやっていけるのかどうか、その点をお願いします。","respondent":"小林保育課長","answer":"来年度、財調の算定の基礎が大きく変わるという話は聞いておりませんので、平成１８年度も平成１７年度同様の金額が期待できるものと考えています。２％前後増額されるやに聞いておりますので、金額的に補助が大きく切り込まれて…","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"都から６１名以上のところなんかは２人配置されているとか、そういった面のところの影響が日々の運営の中で特に心配されていると思うんです。その辺の影響というのをどう考えていらっしゃるのかお聞かせをいただきたいんですが。","respondent":"小林保育課長","answer":"基本的には、その９０名を超える場合には云々と、そういった配置の考え方ですよね。まだ東京都も交付金化の検討途上というふうに聞いておりますので、その動向を見守りつつ、将来的に検討をしてまいりたいというふうに思っております。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"提案","question":"都の方から市長会に提案をされている中には、１１時間開所保育対策事業、その辺のところを見ていらっしゃるのか。これはちょっと古いんですが、だからその辺、具体的に多分数字は出るんじゃないかと思うんですけれども、その辺はどうなんか尋ねました。","respondent":"小林保育課長","answer":"都が市に対して、先ほどご説明しました認可保育所運営費全体を見渡して、交付金化の検討を協議するというふうに新聞報道で承っております。規模に応じて９０人が１つのめどかと思いますが…","id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問","question":"まだ内容がどうなるかわからないということなんですけれども、減らされる可能性も十分含まれているという受けとめでよろしいのでしょうか。５番目ですか、実際にこうやって請願署名で５,０００人くらいの方ですか、この辺をどう受けとめられるのかということを説明を求めました。","respondent":"小林保育課長","answer":"特に、今年、来年と、在宅で子育てをなさっている方へのサービスの拡充ということも努めてまいります。そういった状況を考えた中で、引き続き検討をしてまいりたいというふうに考えております。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"意見","question":"大枠のところが新事業拡大の中でどのくらい増えているのか、ちょっとその辺も説明を求めました。","respondent":"小林保育課長","answer":"平成１６年度決算でオアシス総体といたしましてかかった費用は、およそ２,１００万円ほどと考えております。必ずしも在宅子育て支援だけということではございませんけれども、平成１６年度の運営費は、事業も増えている関係で。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、平成１６年度、平成１５年度と比較して１億５,２００万円増えていると、ちょっとこの中身、ごめんなさい、何の事業で増えているのか。その部分でほかの部分を圧迫していないだろうかという、こういった心配を持っているので、その辺もお答えをほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３歳児が２０対１、４歳以上が３０対１といった、国基準自体に対する評価がどうなっているのかというのが１点。どこをどう見て１.５倍と言っているのか、その計算の仕方の根拠をちょっと教えていただきたいなと思うんですが、いかがでしょう。","respondent":"小林保育課長","answer":"その１人であったとしても、非常勤等も含めて十分な対応ができているという、国基準で対応ができるというふうに考えております。それ以外に先ほどご説明いたしましたように、有資格の派遣職員、人員的には十分な人を配置できているというご説明をさせていただいているわけです。","id":"exchange-075"},{"speaker":"飯沼委員","kind":"意見","question":"２０対１、３０人を１人の保育士で見られる、十分成長発達を保証できるのかどうか。これを十分と思っているのかどうかという点は私はとても大きいと思うので、済みません、ここの点をお答えくださいとの意見を述べました。","respondent":"小林保育課長","answer":"逆に言えば、その人数であっても十分な保育の内容を提供できるだけのノウハウと気概を持って職員はやっているというふうに考えております。重ねてご説明しますけれども、これは必ず３０人見ろ、にわかに今の配置基準が不適切という認識には至っておりません。","id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問","question":"当然、学校で増えているんですから、保育園、幼稚園のところでもそういうお子さんは増えていると思うんです。やはり４歳とか５歳とか、こういったところから出ているんだと思うんですけれども、その辺はいかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この辺で何人の方が通っていらっしゃるのか、ちょっと数を教えていただきたいのと、保育料のところは、把握は難しかったんでしたか。プラスマイナスのところで、どのくらいの負担になっているか教えていただけたらうれしいんですが。","respondent":"小林保育課長","answer":"入所率にしますと８７.１％。標準的かと思いますが、これを単純に人数、それから年額の運営費で割りますと６万円前後なのかなというふうに把握しています。","id":"exchange-078"},{"speaker":"川西委員","kind":"質問","question":"ただ単なる港区が保護者に４万円出しているということだけでは比較にならないとは思いますが、どのぐらい承知していらっしゃるか伺いたいと思います。私も、うんうんと言いながら答えを出さなかったんですけれども、それでちょっと状況を。","respondent":"小林保育課長","answer":"その区の保育のサービス水準全体を考えませんと、なかなか一概に言えないのかなというふうに思います。はなくて、それプラスアルファやっている区が２３区の中に三、四区あるという状況は把握しています。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"意見","question":"ぜひ意見書は上げていくべきであると思いますし、６番目の複数担任制もこれは重要な課題だと思っています。以上なので採択の方向でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"須藤委員","kind":"意見","question":"子育て支援、先ほどもありましたように、全体で考えていくべきだろうというふうに考えておりますので、会派としては採決のときに態度を示しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"石田委員長","kind":"質問","question":"所管質問をなさりたい方がいらっしゃいましたら、その基礎となる一般質問の項目と、それに関する質問内容をこの場でお願いをしたいと思います。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/948006?Template=document&Id=3128#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":73448,"voices":259}},{"id":"h17-20051128-8","meetingId":"h17-cm11","date":"2005年11月28日","dateIso":"2005-11-28","committee":"建設委員会","time":"午前１０時０２分～午後２時５７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"第８１号議案、品川区交通安全対策会議条例の一部を改正する条例","agenda":"第８１号議案、品川区交通安全対策会議条例の一部を改正する条例","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"一つだけ教えていただきたいんですけれども、条例そのものを読んでいてよくわからないのは、ＪＲと首都高速道路公団で、事業主が、特別の事項を審議するとありますけれども、高速道路の場合、特別の事項というというのは、具体的にどういう内容なのか、ちょっと教えていただけますか。","respondent":"山口交通安全担当課長","answer":"現在のところは、まず最初に、ＪＲの関係につきましては、踏切等の関係もあります。自動二輪車の２人乗りが許可になりましたので、そういうことがありますので、そういう説明をいただいたりしている状況です。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"こういう工事をやりますとか、委員から出た質問に対して答えるとかという、そういう立場のほうが強いのかなという気がするんです。当然、ほかの委員と同じ立場でこれに参加をするということになりますけれども、ちょっとその辺の違いというのがあれば。","respondent":"山口交通安全担当課長","answer":"道路の交通事情もだんだん複雑化してまいりまして、意見交換、状況等をこちらに報告していただいている状況です。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"質問ということで、第３条のところで、委員は、「区長が任命または委嘱する」とありますが、任期のようなものはあるんか尋ねました。","respondent":"山口交通安全担当課長","answer":"任期につきましては、個人につきましては、在職中お願いするということで、転勤とかいう関係がありますれば、また新たに任命するという形になっております。","id":"exchange-003"},{"speaker":"井上委員","kind":"意見","question":"区に勤務する職員のうちからということで、先ほど、区長、助役、事業部長ということで、部長がずっと継続して変わらない限り、第７次計画が本年終了ということですが、そういう計画に合わせて、再度委嘱し直すとか、そういうことではないんですねとの意見を述べました。","respondent":"山口交通安全担当課長","answer":"在任中という形をとっていますので、その職にとどまっている限り、いわゆる職を転勤していなくなる場合は、また新たにその後任の方にお願いするという形をとっております。","id":"exchange-004"}]},{"id":"topic-02","title":"第８２号議案、品川区地区計画の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第８２号議案、品川区地区計画の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"住居地区(3) と近隣商業地区、条例変更区域が０.９haですか、住居地区(3) とはまた、条例上は違うのか。それから、実際にここにお住まいの世帯数はどれぐらいおられるのか、ちょっとあわせて説明を求めました。","respondent":"片田建築課長、伊勢住環境整備担当課長","answer":"住居地区(3) 、増加された住居地区(1) につきましては、最高限の高さとして１０ｍということで指定しています。通常は第２種高度地区、あるいは第３種高度地区といった都市計画の網がかかってくるんですけれども… 地区整備計画地域、合計で０.８haですが、この中には、１５０世帯、人口で言いますと、２６０名ということになります。","id":"exchange-005"},{"speaker":"菊地委員","kind":"意見","question":"協議会という形なのかどうか、ちょっとよくわかりませんけれども、そういった説明が何回ぐらい行われてきたのかということ。参加者は、実際にはどのぐらいおられたのかということも、ちょっと数字でお聞かせ願いたいと思いますとの意見を述べました。","respondent":"伊勢住環境整備担当課長","answer":"それから、「地区計画ニュース」を配りまして、今回の計画についてご案内してございまして、今年２月に意見交換会のご案内をいたしております。４月に原案説明会のご案内ということで、原案の説明会につきましては、参加者７名ということで開催しています。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"地権者を集められたのは３回ですか、累計で３０名弱ぐらいですが、世帯数との関係で言うと、非常に少ないのかなと思うんです。説明として行き渡ったのかどうかという部分が、その辺で、ちょっとお聞かせ願いたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"地権者合わせて１,０００部ぐらいですけれども、配布して、そういう面でも周知を図ってあります。それから、意見交換会、あるいは説明会等で、特に反対するというような意見もございませんでした。","id":"exchange-007"},{"speaker":"林（和）委員","kind":"質問","question":"第１０３号議案、第１０４号議案、第１０１号議案については１年の契約になっております。第１０４号議案はそれぞれ２年、３年に分かれているわけですけれども、どういうことなんか尋ねました。","respondent":"浜脇住宅課長、福田まちづくり事業部長","answer":"平成１４年に公募型のプロポーザルを実施いたしまして、平成１５年から管理委託を開始したということで、平成１５年から勘定して５年間を考えた。平成１２年に公募型プロポーザルを実施いたしましたけれども… これまでの経過を振り返ってみますと、この３社は、数年前にプロポーザルを実施いたしました。このプロポーザル制度というものを私どもが考えた前提には、大体５年間程度…","id":"exchange-008"},{"speaker":"土井委員","kind":"提案","question":"そして、期間中は、とりあえずそれを尊重して、急変を避けてやりましょうと。いろいろな提案をしてくる方を、これからも公募をする形でやるという意味も込めた年数なのかどうか、伺いたいとの意見を述べました。","respondent":"浜脇住宅課長","answer":"なかなか対応がおそかったり、ちょっと対応に不満があったものですから、従来から地元企業に任せようということを考えて想定しています。それにつきましては、また今後、やってまいりたいと考えております。","id":"exchange-009"},{"speaker":"土井委員","kind":"質問","question":"育てることも必要ですから、その点は、基準等しっかり守りながらやってほしいと求めました。ちょっと意見を述べさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"菊地委員","kind":"提案","question":"プロポーザル方式ですから、実際に、どんな提案内容があったのか。例えば、どういうサービスを進めていくとか、その一つひとつの提案内容について委員会に示されないと、判断のしようがないというのが一つありますとの意見を述べました。","respondent":"浜脇住宅課長","answer":"あるいはコストといったものを中心とした提案について、検討して採用した結果が、ベニーエステートサービスと三井不動産になったと伺ってあります。２点目の、これにつきましては、区が間に入って補修をしていくというのが基本となっております。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"その内容がどうなんだということが示されないと、この業者がいいんじゃないですかという形は、なかなか出てこないんです。この委員会に対して示していくということも必要ではないかなと思いますけれども、その辺の考え方も含めて、お聞かせ願えますか尋ねました。","respondent":"浜脇住宅課長","answer":"考え方の１として、第１０３号議案ですけれども、本社とのコミュニケーションをスピーディに行って対応したい」というようなことを述べております。品川区で取得しておりますＩＳＯ１４００１については、ごみの分別や資源再利用等、実施可能なものから始めているです。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"ですから、ちょっとこれは委員長にお願いですけれども、後にでも、こうした資料が委員のもとに渡るようなことも必要ではないかと思います。どういうふうに入ってくるか、改めて考えるべき中身ではないかと思うんですけれども、ちょっとお聞かせ願います。","respondent":"浜脇住宅課長","answer":"行政の委員以外は学識経験者等をと考えていますが、これまで公募でプロポーザルを実施しておりますといった中で、確認したです。検討してまいろうと考えていますが、今回につきましては、先ほど申し上げたとおりです。","id":"exchange-013"},{"speaker":"菊地委員","kind":"質問","question":"今回の第１０１号から第１０４号までの議案についても、今、実際に委員会に必要な書類はほとんど示されていないと思います。ですから、この議案については反対をする立場だけは明確にしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"土井委員","kind":"質問・要望","question":"全体の流れなんですけれども、指定管理者制度で、今、私どもがここで議決を求められているわけですよね。だから、ここのところをもうちょっと説明をしていただかないと、いけないんじゃないかなという気がするんです。","respondent":"浜脇住宅課長、福田まちづくり事業部長","answer":"来年１年間やっていただく入居者管理と、建物管理について協議を図り、議会の議決後に、その協定を締結するという予定です。１年間という期間がありますけれども、責任を持って実施するといいますか… ただ、今回につきましては、第１回目ということもありますし、今回のプロポーザルについては、競争性を前提としていないというものもあります。さまざまなご意見があろうかと思いますが…","id":"exchange-015"},{"speaker":"土井委員","kind":"質問・要望","question":"次の段階がもう１年後、２年後に来るわけですから、またある意味で議論しなきゃいけない部分があるのではないかなという気がいたしております。その節は、新たな状況ですから、また、いろいろな意味での話し合いを議会でもしていただきたいという思いであります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"堺委員","kind":"確認","question":"そういう場に、こういう人たちは出ているんですか。ちょっと、その辺は確認しておきたいと思うんです。","respondent":"浜脇住宅課長","answer":"ベニーエステートサービスについては３名、三井不動産については、部長以下６名、それから、品川宅建管理センターについては３名。これは、社長と副社長になりました。","id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"それから、三井不動産は、部長と担当の職員を含めて６名ですか。それから、品川宅建管理センターは、ここは社長と、職員を含めて３名か尋ねました。","respondent":"浜脇住宅課長","answer":"三井不動産につきましては、部長以下５名、だから担当者は５名。それから、品川宅建管理センターは、社長をはじめ３名で参りました。","id":"exchange-018"},{"speaker":"堺委員","kind":"質問","question":"その部長が、何かあった場合に、全責任を負うという資格を与えられた方ですか。その辺はどうなんか尋ねました。","respondent":"浜脇住宅課長","answer":"それから、品川宅建管理センターは、代表取締役と取締役ということで、代表が１名、取締役が２名参りました。それぞれの部長です。","id":"exchange-019"},{"speaker":"堺委員","kind":"質問・要望","question":"区からしかるべき人がきちっと出ているんですから、相手側もしかるべき人が出て来て当然ではないんですかと、なぜ出て来ないんですか。きちんとやっていただいたわけですから、きちっと確認をしておきたいと、それを申し上げているんです。","respondent":"福田まちづくり事業部長","answer":"それに最も的確に答えられるような、営業部隊と、技術部門の実践部隊を選抜したのではないかと考えられます。しかし、冒頭に申しましたように、委員のご意見はなるほどと思うところもありますので、次回以降に生かしてまいりたいと思います。","id":"exchange-020"},{"speaker":"井上委員","kind":"提案","question":"３番のところでも、「大規模改修修繕費他、管理業務費のコスト削減の提案がある」ということなんです。これについて言えば、今までの契約費用というのが下がっていくのか、どうなのかという部分なんですけれども、改めてお聞きしたいと思いますとの意見を述べました。","respondent":"浜脇住宅課長","answer":"苦情対応ですけれども、即対応ということで、今後も引き続きやるということを言っていただきました。私どもが許可して貸している住宅ですので、責任については、当然区が負うということになってあります。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"仕組みで、指定管理者制度を導入すると、行政処分みたいなところが、所管が違うというような話を聞いたんですけれども、勉強不足ですみませんが、そういうことはあるんか尋ねました。","respondent":"浜脇住宅課長、岩田まちづくり事業部次長","answer":"先ほどの処罰というような処分的ものにつきましては、すべて区長名で、区の責任でやっております。というのは、今後とも、その仕組みについては変わりません。 住宅で言えば、入居者の決定および督促、退去といった行政行為については委託できないというふうになっておりました。指定管理者の権限の中で、入居者と話し合って、さまざまなコミュニティ活動を行えるようにしていく予定です。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"今のお話で、部屋とか使用料については料金制をとらないんですけれども、多分駐車場が何カ所かあったかと思うんですが、それについては、指定管理者の収入としてカウントされていくということか尋ねました。","respondent":"浜脇住宅課長","answer":"駐車場につきましても、これまで同様、区の収入として入ります。ですから、今回、指定管理者のほうに収入が入って、運営するということはございません。","id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"そういったところのケアがとても大切だと思うんですが、そういったところは、どういうふうに業務として委託をされるのか。線引きとか、そういうふうな話し合いは、どのようにされているんか尋ねました。","respondent":"浜脇住宅課長","answer":"２カ月、あるいは３カ月といった滞納については、これまでどおり連携のもとにやってまいります。今回、それも変わりません。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"今まで、連携を取るということだったみたいなんですけれども、業務の範囲のところに、使用料の徴収みたいなことも含まれているんでしょうか。４ページに業務の範囲というのがあるんですけれども、この中に、区営住宅なんかの使用料徴収というような業務も含まれるのか。","respondent":"浜脇住宅課長","answer":"使用料を滞納した人については、今回、委託の中に含めてございません。事務的なこと、そういうことをやっていただこうということです。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"どうかというところの議論にもあったかと思うんですけれども、きちんとそこは今までどおり保証されるのか、どうかという不安があるんだと思うんです。契約の中でも、そういったところではどういうふうに指示されていくんか尋ねました。","respondent":"浜脇住宅課長","answer":"しかし、むやみやたらにそういう考え方はあれですから、できるだけこれまでどおり、連携の中で収納率が落ちないようにということでやっていきます。当然、今後の中に入れなければいけない内容と考えています。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問・要望","question":"次のことがもう平成１８年度には出てくるわけですから、ここのところを確認して、私たちは承認したんですということが必要だと思います。出向くということで、一応要望としてお伝えしておきますけれども、そういった形でつくっていってほしいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"菊地委員","kind":"質問","question":"もう１点だけ聞きたいんですけれども、どういう形で議会に示されるのか、情報開示されるのか。ちょっとそこだけ教えていただけますか。","respondent":"浜脇住宅課長、岩田まちづくり事業部次長","answer":"それについては、先ほど、私がベニーエステートサービスを例に出してやりましたけれども、ほぼそれと同じことがあったというのは事実です。これにつきましては、情報公開の際に出すことは可能だと思います。 したがって、その議事録をどこまで公にできるかについては、もう少し検討させていただきたいと思います。先ほど質問で説明が漏れたかもしれませんが、各社ごとに各委員が、各項目ごとに１点から５点の評価をしております。","id":"exchange-028"},{"speaker":"菊地委員","kind":"質問・要望","question":"事業者の内容を知ろうということではなくて、あくまでも管理にかかわるところでの内容については、明確に開示をしてほしいと求めました。先ほど述べたとおりです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"菊地委員","kind":"質問・要望","question":"７割ぐらいが民間での確認になるということですけれども、民間から上がってきた報告書について、ちょっと教えていただきたいというのが１点。区がやる確認の流れと、民間がやる確認の流れの違いといいますか、その辺をちょっと教えていただけますか。","respondent":"片田建築課長","answer":"どういう確認がおりているという内容で、法律に基づいた閲覧制度がありますので、そのような対応を行っているです。確認をやっていくというようなことになり、そういうことで進めているということで、行政のほうとしても認識しています。","id":"exchange-030"},{"speaker":"菊地委員","kind":"確認","question":"年間３００件から４００件ぐらいはまだ確認するのがあるんですけれども、一体、区の場合何人ぐらいいらっしゃるのか。建築確認をおろす段階で、一体どれぐらいの職員が携わっているのか。","respondent":"片田建築課長","answer":"法律の権限として持ってありますので、それにつきましては、必要に応じて対応を行っているという状況です。６人のところは、ちょっと確認させていただきたいと思います。","id":"exchange-031"},{"speaker":"菊地委員","kind":"質問・要望","question":"一級建築士が６名ぐらいで、年間３００件から４００件近い確認ということであれば、１日１件の建築確認をおろしていく形になりますよね。今の閲覧という中身で、これが確認できるものなのか、どうか。","respondent":"片田建築課長","answer":"恐縮ですけれども、現時点で、私からご説明できることは以上です。相談対応とか、それも適正な形でやるような体制づくりがあわせて必要ではないかということで、私のほうとしては認識しています。","id":"exchange-032"},{"speaker":"菊地委員","kind":"質問・要望","question":"他の民間機関で確認を受けたマンションもたくさんあって、住民が求めるのは、しばらくの間は。これはやっぱり、すべてがそうだとは言いませんけれども、行政の責任が一部はあるのかなと思うんですけれども、その辺はどうなんか尋ねました。","respondent":"片田建築課長","answer":"一応５年間保存となっていますので、建主のほうにも、書類の一部がお渡しされるような形になります。管理も含めた対応をされるかと思いますので、流れとしてどうなのかといったようなお答え、あるいはアドバイス等についてはできると考えています。","id":"exchange-033"},{"speaker":"菊地委員","kind":"質問・要望","question":"法律改正が１９９８年にあって、その時点から民間での審査が可能になって、今回の事件が起きたわけですよね。行政にまたすべての確認審査を戻すべきだとは言いませんけれども、横浜市の、そういうものを求めるべき内容なのではないかなと思うんですけれども。","respondent":"岩田まちづくり事業部次長","answer":"今後の民間確認機関のあり方と、自治体のかかわりについて、法律をどう変えればいいか検討をされるものと考えています。行政として、不安を解消するためにどういったサービスができるかということを、これから体制づくりも行ってまいりたいと考えています。","id":"exchange-034"},{"speaker":"菊地委員","kind":"質問・要望","question":"企業ですから、鉄筋１本を何mmか細くする、それに対する利益というのは生まれてくる。どうかというのは、企業の場合ははっきりしているわけですから、行政としてできる得る監視体制の強化だけは強めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"土井委員","kind":"提案","question":"あの程度なんだろうなという認識なんですけれども、それで済むんでしょうかということ。さあどうするかというのは、我々だけではどうにもならないことだなと思うんですけれども、その辺についての見解をお願いしますとの意見を述べました。","respondent":"片田建築課長","answer":"ただ、その権限の枠組みとして、現時点で１万m2といったような床面積の枠組みが指定されているといった状況です。それに対する是正指導といったものが、区として、自治体としての責任として付与されてきているです。","id":"exchange-036"},{"speaker":"土井委員","kind":"質問・要望","question":"そういう皆さんがちょっと見れば、ちょっとあれすればわかるようなことが、どうもやっていないように思えてしようがない部分があるんです。審査をしろという話になっても、できなくなっちゃいますので、その点よろしくご配慮いただきたい。","respondent":"片田建築課長","answer":"特に構造計算というものは、目に見えない部分ですので、力の流れはコンピュータ任せではなかなか難しいところがあります。その検査なりを、今後出てくるかと思いますので、それを含めた体制を検討していかなきゃいけないと思っています。","id":"exchange-037"},{"speaker":"大西副委員長","kind":"質問・要望","question":"今回、耐震強度の偽装の発覚が、どういうことで明るみに出てきたのかということが１点。一般の方からご相談されたときに、そういう方法があるのかということを、ちょっと教えてほしいと求めました。","respondent":"片田建築課長","answer":"逆に建築確認の流れを知らない方に、実際の事例を使って説明をしていった経過の中で、偽装が発覚したという話を聞いております。そういうような考え方がありますけれども、これが適正かどうかというところは、なかなか難しい問題だと認識をしております。","id":"exchange-038"},{"speaker":"大西副委員長","kind":"意見","question":"そういう場合に、区のほうに、うちのマンションは大丈夫だろうかというご相談があった場合には、具体的にはどういう対応をされるのか。その辺をちょっとお願いしますとの意見を述べました。","respondent":"片田建築課長","answer":"区のほうに書類を保管してあるものについては、それを含めて再確認をすることができますので、そういうことには対応していきたいと考えています。そちらのほうに書類をお持ちいただいて、専門家がアドバイスを受けるとか、そういう体制ができるかと考えています。","id":"exchange-039"},{"speaker":"堺委員","kind":"確認","question":"それからまた、相談の中身が、主としてどんなものがあったのか。今、お答えいただいた中で、ほぼ出尽くしているのかもしれませんが、確認します。","respondent":"片田建築課長","answer":"港区に住んでいて購入を考えているんですけれども、新聞報道で、逆に１００％安全なんですかというようなご質問。区としての対応を聞きたいとか、信用しているんですけれども、ほんとうに大丈夫ですかといったようなご質問等々が寄せられているです。","id":"exchange-040"},{"speaker":"堺委員","kind":"意見","question":"こういう件について、いろいろありましたら、ここに問い合わせくださいというような発信をしてありますか。見ておけばよかったんですけれどもとの意見を述べました。","respondent":"片田建築課長","answer":"まだ載せてございませんので、それについては早々に、建築課のほうで対応してまいります。","id":"exchange-041"},{"speaker":"堺委員","kind":"確認","question":"偽装がないことを書面上確認をしたということなのか、書面上確認をして、そういった両方で確認をして。その辺はいかがなんか尋ねました。","respondent":"片田建築課長","answer":"特に2)と3)につきましては、なかったのかといったようなことについて、書面上の確認をさせていただいています。したがいまして、現地のほうにその建物を調べに行くという状況には、まだ至ってございません。","id":"exchange-042"},{"speaker":"堺委員","kind":"確認","question":"もう一つは、時間的な問題もあるかとは思いますけれども、そんなに数があるわけではないですから、可能ならば現場というか、建物の確認。可能ならばの話ですよ、確認しておけばなお問題がないかなと、素人判断でお尋ねして申しわけないんですけれども。","respondent":"片田建築課長","answer":"例えば１０あるものを５に偽って入力したというか、確かになかなか見づらいといいましょうか、難しいことだと思います。区のほうとしても、その流れが適切かどうかといったところを、書面上、再チェックをし直すというようなことです。","id":"exchange-043"},{"speaker":"堺委員","kind":"確認","question":"念のため申し上げますが、この書面の確認は、課長がなされたのですか。それはどうか尋ねました。","respondent":"片田建築課長","answer":"職員ともども、私も同席した中で確認をしてきてあります。","id":"exchange-044"},{"speaker":"堺委員","kind":"確認","question":"イーホームズが確認して、２１日から営業中止という報告の中身になっているんですが、ここと近隣ですよね。したがって、その辺の、いわゆる近隣への対応、対策は、区としてどうお考えになっているんか尋ねました。","respondent":"片田建築課長","answer":"２４日に、ホテルに対する改善なり、解体等を含めた対応措置を考えていきたいというふうなお話を聞いてあります。一連の経過をご説明して、必要に応じた対応を、ホテル側のほうに指示していくということになっいる状況です。","id":"exchange-045"},{"speaker":"堺委員","kind":"質問","question":"今のご報告を伺うと、できることについては管理して、対応できることはしていきたいと思います。ひとつあろうかと思いますが、ぜひ、その段階でまたスピーディな対応をお願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"井上委員","kind":"質問・要望","question":"今年５月ごろに、早い時期に報告をほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"井上委員","kind":"意見","question":"時期が来たらというか、もう動いていることだと思いますので、何かが出たときではなくて、どういう状況になっているか。５月には出されているようなんですけれども、もう半年以上経っていますので、その辺で、次回というか、早めによろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"菊地委員","kind":"質問・要望","question":"３環状道路とか、オリンピックでどうなる、質問をしたりという中身ではなくなるんです。私としては、そこの議会運営委員会の縛りを解いてもらうような申し入れをしていただきたいということが要望なんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/825107?Template=document&Id=3836#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":47871,"voices":135}},{"id":"h17-20051128-9","meetingId":"h17-cm11","date":"2005年11月28日","dateIso":"2005-11-28","committee":"文教委員会","time":"午前１０時０３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を95件整理しています。","topics":[{"id":"topic-01","title":"第１０５号議案 指定管理者の指定","agenda":"第１０５号議案 指定管理者の指定","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"ただ、それにしても指定しちゃうわけで、競争入札をやるわけでないですよね。今度、こういうところにも声をかけて調べてみたというものがあれば、そこらの状況についてもう少し説明をもらえるとありがたいと思いますとの意見を述べました。","respondent":"富田生涯学習課長","answer":"今後の指定管理者制度の活用の方針といたしまして、基本方針の１ページ目、２活用の方針の(1)。したがいまして、指定管理者制度には移行いたしますけれども、現在の事業者でというふうになったところも１つとしてはあります。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"わかりました。二点聞きたいんですが、スポーツ協会に委託する委託料あるいは補助金がもしわかりましたら、どれぐらいなのか教えていただけますか。","respondent":"富田生涯学習課長","answer":"管理運営等々に係る経費としては約２億５,０００万円程度、それに対し、５,０００万円程度の収入があります。これまでですと、大ざっぱな話ですが２億円といったような金額が、委託料としてスポーツ協会のほうに支出をしているというのが現状です。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"そうなったときに、５年後の時点を今からちょっと言うのは何なんですけれども、今のような考え方を継承していくということなんでしょうか。その時点でまた新たな状況で、考え方等をもう一回組み立て直していくという、そういう考え方なのか、ちょっとその辺を。","respondent":"富田生涯学習課長","answer":"体育館でいえば、１つには貸切利用があり、その辺については変わらないというふうに思っております。はさらにスポーツ協会なりあるいはその他の民間事業者も含めてプロポーザルを行うということも考え方としてはあろうかと考えています。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"自分の健康を守っていくということが高まっていくはずですから、そしていろいろな多種多様な、そして安価な料金で参加できるような。そのときに全くほかの団体、そういうものは机上にもプランにものぼらなかったのかどうか、ちょっとその辺を伺っておきたいと思います。","respondent":"富田生涯学習課長","answer":"今回の選定に当たりましては他の団体と比較等々ということではなく、この財団法人品川区スポーツ協会を特定して選考対象者とするという進め方ですので、他の団体については検討しておりません。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"指定管理者で選定したという以上はそれなりの責任もあるわけですから、それから経費的なところを追求していくというところが求められていくと思うんですが、区民の皆さんに対してどこまで開示できるものなのかをちょっと教えていただきたいんですが。","respondent":"富田生涯学習課長","answer":"初めに選考の基準等についてのお尋ねですけれども、こちらにあります選考基準の一つ一つにつきまして、５段階での評価をそれぞれ行いました。やってきた内容についての評価を私どもとしても行い、さらに向上した内容としていくように指導してまいりたいというふうに思っておりま…","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"それで、その中で５段階というのを、基準というのは何なのだろうというところ、これはある程度明確になっているんでしょうか。そこを踏まえて選定に当たったのか、その辺、いかがか尋ねました。","respondent":"富田生涯学習課長","answer":"今後につきましては、その必要性等々を含めまして、今後の検討課題であるというふうに考えているところであります。体育館で努めているところですが、新たなサービスの向上、利用者のそういったところを生かした内容の展開というところが望まれるところです。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"具体的に５段階があるんだったら、５段階をどういうふうに設定していって、どういう評価に至ったのかとか、それから目標数値も必要だと思います。ある程度決定したという経緯については公開はすべきではないかなと思うんですが、どの辺、どんなふうまで今後公開していただけるのか尋ねました。","respondent":"富田生涯学習課長","answer":"どの辺まで公開できるのかといったようなことにつきましては、ちょっと今の段階でどこまでというのは差し控えさせていただきたいと考えています。実は総合体育館は面積は１.２５倍に広くなっていくのですけれども、候補者スポーツ協会からの予定によれば、付け加えします。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"それを十分考えていただきたいということですね。必要なときには必要なところにはお金をかけるべきというところは当然考えられていると思うんですが、その辺は十分に検討を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"沢田委員","kind":"提案","question":"議会運営委員会でちょっとこれは松澤委員から提案されて、西本委員が言われたように、議会の責任が問われるわけですよね。やはりどう審議して議会が選定をするに当たって責任をとれるような、そういう審議の仕方、資料あるいは情報公開なんかをやるべきなんじゃないかとの意見を述べました。","respondent":"古川教育次長","answer":"先ほどお示ししました区の基本方針ということをご説明した経緯もありますし、今回におきましても、さまざまなご議論をいただいてまいりました。今後５年間、総合体育館と戸越体育館を指定管理者として十分に賄えるものがあるのかという点につきまして私どもなりにご説明申し上げ。","id":"exchange-009"},{"speaker":"沢田委員","kind":"確認","question":"私は官から民への流れの中で、建築設計事務所の姉歯問題に伴うイーホームズの、確認申請の事業まで民間に任せちゃった。こういう確認審査みたいなものは、そういうことに匹敵するのにやってしまった、それが取り返しのつかない事態になっている。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"若林委員","kind":"確認","question":"確認ということで、ここに事業計画書等を審査したとありますが、計画書のほかにどんなものがあったのか、計画書が表には出せるものなのか、確認をします。","respondent":"富田生涯学習課長","answer":"平成１７年度、平成１６年度の同様のもの等々についての提出を見て、選定に当たったものです。ちょっとどの点までというところが、情報公開の条例等にのっとり、その辺の出せる部分については検討させていただきたいというふうに思っております。","id":"exchange-011"},{"speaker":"若林委員","kind":"意見","question":"今後、議会の議決を経て移行していくわけですが、ここには今後のスケジュールとして、通知とともに協定の締結ということがあります。そういういわゆるこれから取り決めるべきもの、取り決めようとしているものはどのようなものがあるのか、お知らせほしいと求めました。","respondent":"富田生涯学習課長","answer":"管理業務の停止について、管理運営するに当たっての守秘義務、個人情報の保護等々といったものにもあります。管理運営経費の取り扱いについてといったところも、この辺では協定書の中に入ってくる事項です。","id":"exchange-012"},{"speaker":"若林委員","kind":"確認","question":"それからもう一つは、例えばこの選定委員会等々でいろいろなご審議をされて、すべて５段階中の３段階以上ということで、一定の評価があります。委員からありましたような今度の建築確認の話から、受けとめていただいたのか、その点を聞いて終わりにしたいと思います。","respondent":"富田生涯学習課長","answer":"そういう意味では、特定のところに利用が偏る、そういった問題はないものというふうに考えているところがまず１つはあります。施設の５年間にわたる、しっかりしたその辺の体制、これからも一つ一つ指導していきたいというふうに考えております。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"そのうちの５,０００万円が利用料の収入だという説明をいただいたんですけれども、５年ぐらいさかのぼって、もしわかれば教えていただきたいんですけれども。","respondent":"富田生涯学習課長","answer":"約２億円程度というふうにお話し申し上げましたが、この辺の数字については、これまでのところ大きな変化はないということです。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"そうすると、２億５,０００万円の現行のこの数字は、ここ数年間変わっていないという、そういうことで考えていいか尋ねました。","respondent":"富田生涯学習課長","answer":"差し引きの２億円程度が委託料として支出している金額です。これには維持管理経費ですとか、光熱水費ですとか、さまざまな教室、事業の経費を含めたものです。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"そうすると、この利用料収入というのは、今年度というかしら、現行の５,０００万円程度だというんですけれども、この金額もそんなに大きな変化というのはないんか尋ねました。","respondent":"富田生涯学習課長","answer":"来年４月からは日野中学校のプールということになってまいりますので、この指定管理者の収支からは外れていくということになってまいります。支出ともに２,０００万円程度プラスで入ってきているといったような…","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"今までじゃあ２億円前後の委託でやれたのが、最初で公のところの責任というのはやはりどうなのかなと、言わせてほしいと求めました。意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"大沢副委員長","kind":"質問","question":"品川区指定管理者制度活用上に係る基本方針の２ページの「指定管理者の選定」というところで選定方法が書いてありますが、これは(1) の選定方法のただし書きの「ただし、よろしいんか尋ねました。","respondent":"富田生涯学習課長","answer":"おっしゃるとおりです。","id":"exchange-018"},{"speaker":"大沢副委員長","kind":"質問","question":"仮に面積の１.２５倍になっても、２億５,０００万円の経費は変わりませんよという話なんですが、そこらのところはどういうふうにお考えになっているんか尋ねました。","respondent":"富田生涯学習課長","answer":"今後、そういったところに努めながら、次の選定の機会にはそういったことも含めて検討していきたい。プロポーザル等々といったことも含めて検討して選定していくことになっております。","id":"exchange-019"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"お願いで終わりますが、特別の利用がある場合という、この場合の運用だけはきちんとやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"三上委員長","kind":"質問・要望","question":"私のほうから１点ちょっと確認だけします。それからどうあるべきかという、仮に５年間の間に不測の事態が生じた、それについて明確にちょっとお示しいただきたいなと思います。","respondent":"富田生涯学習課長、古川教育次長","answer":"選定基準を満たさなくなったと認めたとき、その他、指定管理者による管理を継続することが適当でないと認めたときには指定を取り消す。見込みがないと認めるとき等々の場合には、きっちりとそういった条件をつけ… 今回は、指定の議決を区民の代表者である議会でご議決いただく、こういう内容になっております。私どものほうは５年間、事業者においても当然それに答えていく責務がある、このように考えております。","id":"exchange-021"}]},{"id":"topic-02","title":"平成１７年請願第１４の２号、一人一人の子どもたちが大切にされる品川区を求める請願（請願項目1)2)3)）","agenda":"平成１７年請願第１４の２号、一人一人の子どもたちが大切にされる品川区を求める請願（請願項目1)2)3)）","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"意見表明の前にやったのでは、審議をする段階でどういう思いを持って出したのかというのは、おそらく陳述をしないと、これは審議に反映させることができないから、最初にそれは諮ったほうがいいんじゃないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"沢田委員","kind":"意見","question":"それをより補足する上でぜひ発言させてほしい、その上で審議をしてほしいという意味合いでやられているので、私は違うというふうに思います。だから最初にやるべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"南委員","kind":"質問","question":"区の説明はもちろんあるんですけれども、請願の方々のご意見を直接伺ってから審査したいと考えていますので、その意味で聞きたいと思っています。そういうふうに諮ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"西本委員","kind":"意見","question":"どうしてもこういうところをもう少し聞いてみたいなというような状況であるならば、それなりに委員それぞれの調査もあって臨んでいると思います。今までもこういう形で審議を進めていたと思いますので、私は今回もこういう形でよろしいんじゃないかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"せっかくおいでいただいて申し出があるんですから、やはりそれは議会としてしっかり正面から受けとめていくべきだというふうに思うんです。ですから、陳述のそういう状況がどういう経過の中で後になったのか、その辺の状況を委員長のほうでもしわかったら教えていただきたいし。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"沢田委員","kind":"確認","question":"そういう制度として申し合わせ確認事項でも明記されているんだと思うんですけれども、だから、我々が紹介議員になったからだとか。出席確認、また指導員の配置をしてほしいと読み取れるとそのときには主張したんですけれども、請願提出者の意向を冒頭で正確に聞いておくことは。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"三上委員長","kind":"質問・要望","question":"議会運営委員会の申し合わせ確認事項で、1)意見陳述は、休憩中に取り行う。ですから、当委員会としては意見陳述をどうするかは後で決めていきたい、こういうことであります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"沢田委員","kind":"確認","question":"確認したいんですけれども、今委員長がおっしゃられた説明を受ける前に意見陳述を言うのはいかがなものかと、それはそれでよくわかります。意見陳述を受けるかどうかというのは委員会の判断ですから、採決の直前になって、そのことを諮るのではなくて。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"南委員","kind":"確認","question":"ですから、すべての質疑が終わった後に意見陳述を受けるのではなくて、必要な場面で受けていきたいというふうに思っているんです。理事者に新たな質問もする場合だってあるわけですから、途中のところで、その保証をしていただければというふうに思っているんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"南委員","kind":"意見","question":"じゃあ質疑を終了しましたというふうに委員長のほうが抑えて、抑えてというかしら、抑えてというと表現が悪いですけれども、一応そういうふうに仕切って、その後に意見陳述というふうにしないで、受けていきたいと私は思っているんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"そういうふうに振っていただいて、諮っていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"松澤委員","kind":"質問","question":"そんなことをして、もし「これは文教委員会ではない、厚生委員会ではないですか」という話になったらどうするんですか。これが文教委員会の請願項目になったんですから、その意味で、意見陳述を決めようみたいな話が出るのは私はおかしいと思うんですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"だから、今回みたいな、請願をどこの委員会で取り扱うのか、請願の趣旨はどういうものなのかというのは、公開して当然のところだと思うんです。全部が議会運営委員会が非公開ではないんですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"若林委員","kind":"質問","question":"今、議会運営委員会の中身の判断になっております、当委員会は文教委員会と承知しておりますので、1)2)3)の請願項目について速やかにご審議に入れるようにしていただけないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"松澤委員","kind":"質問","question":"やはりこれは議会運営委員会の中で正副委員長一任で請願項目、これが文教委員会で取り上げるという話になったと私は記憶しているんですよ。ですから、もうそれでいいんですよ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"沢田委員","kind":"質問","question":"答弁者がいないわけですから。最終的にここに来たんだけれども、本当にそれでいいかどうかというのは、議会運営委員会がどうこうとかというのは本筋の私の思いではないです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"ですから、ですから、そういう趣旨になりますので。それに異論があるわけじゃないから」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"改めてとりわけ各校の実態調査のところの現状の状況把握のご説明を伺って、全く同じなのかなというのを説明を伺いながら思ったので。出席状況がどういうふうな現状になっているのか、その現状をどういう受けとめになっているのか、そこのところをまずちょっと伺いたいと思います。","respondent":"市川庶務課長","answer":"現在３８校の事業実施校のうち、現状１２校、現在のところは３８校のうちの１２校で業務の一部を委託しています。そういったものもありますけれども、勉強を除いた部分、こういう部分が現在委託の対象としているということでご理解をいただければと思います。","id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"この数字、どういうふうに区としては認識を持っておられるのか、ちょっと現状の数字をご覧になっての認識を伺いたいというふうに思うんです。委託事業にかかわる方々はどういう方たちが携わってくださっているのか、職員というか、携わる方の体制も含めて説明を求めました。","respondent":"市川庶務課長","answer":"それはこれからの問題だと思いますけれども、冒頭申し上げたように、比較的低学年児童の指示を得ているというふうな認識をしています。３番目の委託の関係ですけれども、これは人材派遣でございませんで、人材派遣会社による業務の受託ということで運営をしています。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、区としてはどういうふうに聞いておられるのか、その辺の状況を教えていただきたい。これは、そこに携わる人の配置というのはどういうふうになっているのか、そこを申しわけないんですけれども教えてほしいと求めました。","respondent":"市川庶務課長","answer":"各家庭では子育ての考え方、教育に対する考え方、ちょっとその辺は私どもと認識が異なる部分かと思います。それとともに、それを実践できるスタッフ、これを配置してほしいというところが委託内容です。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"新しい事業を展開して、区民にそういうふうに理解していただきたいと説明してきただけに、その点についての見解をちょっと伺いたいと思うんです。すべての全児童対策と言ったって３分の１ですから、みんなが本当に喜んでいけるような、その辺の見解はどうか尋ねました。","respondent":"市川庶務課長","answer":"冒頭説明申し上げましたけれども、あるいは情報提供、そうしたもので対応しているというふうに考えているところです。このように考えてありますので、少なくとも委託が利用率の低下につながっているという認識は、その点だけは明確に説明させていただきたいと思います。","id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"区の今の説明を伺って、しかし、利用されている子ども。これは利用実態調査という、そういうことで、私はむしろ積極的にやるべきだし、ほかの分野ではどんどん積極的にやっているじゃないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"沢田委員","kind":"意見","question":"３０人学級のことについても、出さなくちゃいけなかったのか、そこらをちょっと説明願えたらと思うんですがとの意見を述べました。","respondent":"市川庶務課長","answer":"他方、学童保育クラブ事業のそれに対応した廃止ということがあります。求めているというもの、十分対応できるものがあるだろうということの判断の上で、届け出をしたものです。","id":"exchange-044"},{"speaker":"沢田委員","kind":"意見","question":"それをあえて届け出をしたのは何か例えば都からの指導があったのか、何かちょっと。ここに書かれてるのは意味がわからないので、それの説明を願いたいと思いますとの意見を述べました。","respondent":"市川庶務課長","answer":"すまいるスクールがいわゆる計画事業として順調に推移してきていると、その一方で、学童保育クラブ事業が廃止をしてきているわけですね。そのタイミングを見計らって平成１６年４月１日に届け出をしたです。","id":"exchange-045"},{"speaker":"沢田委員","kind":"質問","question":"なぜこの時期にあえて出したのか、単純なところで聞いていたんだけれども、どっちなんか尋ねました。","respondent":"古川教育次長","answer":"その届けをやっているということで、平成１６年度も必要な届けをしておりますし、平成１７年も必要な届けを当然しているわけです。こういうことでありますから、今回、急にやったわけではございません。","id":"exchange-046"},{"speaker":"沢田委員","kind":"質問","question":"決してサービスの低下だとか、そういうのはございませんということを導入時にずっと言ってきたんですけれども、どうなんでしょうか。あるいはそれを利用していた子どもたちに問題は起きていない、むしろサービスは向上になったという具体的な事例があれば示してほしいんです。","respondent":"市川庶務課長","answer":"先ほども説明の中で申し上げましたけれども、要望、そういったものの聞き取りということについては対応してきたつもりです。ただ事業を進めていく上で、学童保育クラブと比べてこういう点がということが、特に顕著な形で出てきているということは認識をしてございません。","id":"exchange-047"},{"speaker":"沢田委員","kind":"質問","question":"３年ほどたった現在で、法で認められた第二種事業ですから、そこはしっかり抑えて調査する必要があるんだと思うんですよ。ちょっとここで言う、親御さんの意見なんかを調査するというのはぜひやってほしいと思うんですが、改めて見解を伺いたいと思います。","respondent":"市川庶務課長","answer":"現在、自分のところの個性に合った事業をしようということで、現実にはさまざまなニーズの把握に努めてあります。どういう支援をしていくかということを考えているわけでございまして、今現在、その辺の事情をご理解いただければと思います。","id":"exchange-048"},{"speaker":"沢田委員","kind":"質問","question":"ちょっと聞きたいんですが、先ほど登録者数なんかは出たんですが、今のすまいるスクールの中の、この７,６７６人ですか、この登録者数のうち、日中、親が働きに出て、学童保育クラブ事業で吸収をすべきお子さんというのは何人ぐらいいるんか尋ねました。","respondent":"市川庶務課長","answer":"私どもはいわゆる参加者の申請書から、日中の緊急連絡をする趣旨から調査した結果の数字ということでは、先ほどの７,６７６人に対して現在、３,６６４人の数字を把握しています。","id":"exchange-049"},{"speaker":"沢田委員","kind":"質問","question":"すると、この３,６６４人の出席状況は何かチェックしている。これは別にアンケートなんかやらなくても把握ができることだと思うんですが、出席状況はどうか尋ねました。","respondent":"市川庶務課長","answer":"特にこの子どもたちについての出席率、出席状況の把握ということは数字はとってございません。","id":"exchange-050"},{"speaker":"沢田委員","kind":"質問","question":"全部だとはもちろん思っているわけじゃないので、最低限、出席状況については区の責任で調査してもらえないでしょうか。本来の事業なんですから。","respondent":"市川庶務課長","answer":"今のすまいるスクールのさまざまな事業運用を実施していく中で、参考になるようなそういう事業の進め方の必要性というのはまだ現実の現場で聞いておりませんので、私どもは考えてございません。","id":"exchange-051"},{"speaker":"沢田委員","kind":"質問","question":"保育園や学童保育クラブのそれが本当に履行されているのかどうなのかということなしに事業の評価なんてできないんじゃないですか。だって移行したと言っているんですから、その移行がどうだったかというのは、成果を評価しなければならないじゃないか尋ねました。","respondent":"市川庶務課長","answer":"事業の実施の上に当たって、そういうことの問題はないという認識を持って、数字を把握する必要はないと先ほども申し上げた次第です。","id":"exchange-052"},{"speaker":"沢田委員","kind":"質問","question":"一番大事な点はサービスの受け手がどうなのかというのが行政評価の基本じゃないですか。それがどうだったかという評価に対して、このすまいるスクールになって、なぜできないのか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"学童保育が都の事業であるとか、こういうものが学童保育だという指針みたいなものはあるんでしょうか。こうあるべきだという設置基準というのはいかがか尋ねました。","respondent":"市川庶務課長","answer":"本日、私どもの手元に、それに類したものは用意してございませんので、答弁できません。","id":"exchange-054"},{"speaker":"西本委員","kind":"確認","question":"おやつに関しては、別の問題ですけれども、そのほかのものに関しては、きちんとやりますというお話だったんですが、実態的にはどうなんでしょうか。各すまいるスクールの中では徹底してされているという認識でよろしいか尋ねました。","respondent":"市川庶務課長","answer":"平成１３年度にすまいるスクール事業を始めた当初から、衛生と安全の確保については、万全の体制をとってきているところです。その意味で施設の確保、また出席確認についても低学年児童の安全確保ということで、既にかよう措置を講じてきているところです。","id":"exchange-055"},{"speaker":"西本委員","kind":"確認","question":"この実態調査はその当時の学童保育クラブと、それから全児童対策であった経緯とが、再編制されたという経緯をもう一度確認させてください。どういう経緯で品川区がすまいるスクールをやろうとしたのかを説明を求めました。","respondent":"市川庶務課長","answer":"学校の週休２日制を見据えていまして、文字通り全児童ということで、すまいるスクールを子どもの居場所づくりということで始めた経緯があります。特に学校施設の中に事業の実施場所を求めてつくったということは…","id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"幾つかご質問がありましたけれども、お子さんにとっても、いろいろな放課後の過ごし方というのがあると思うんです。今の時点では要求される現状が変わってきているのではないかなと思うんですが、この辺はどういうふうに教育委員会の方では考えているんか尋ねました。","respondent":"市川庶務課長","answer":"親なり家庭のそういう考え方に対応した子どもの居場所がどこまで整備されているのか、そこのところが実はすまいるスクール事業の出発点なわけです。そういった幅のある考え方にできる限り対応できるような、遊びなりスポーツなり、あるいは体を休める。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"この上にあるさっきも質問しましたけれども、出席確認、その出欠確認等々のものを言っているのかなと思うんですね。実際それがうまくいかないところがあるという傾向で、こういうものが出ているのかなと、そこら辺はどういうふうに考えているんか尋ねました。","respondent":"市川庶務課長","answer":"家庭が持っているさまざまな子育てに関する役割のすべてをある時間帯、すまいるスクールが受け持つという考えは少なくとも持ってございません。やはりすまいるスクールの果たすべき役割はそういうところで考えていく必要があると思って、仕事をしています。","id":"exchange-058"},{"speaker":"西本委員","kind":"確認","question":"最後に指導員の役割について確認をするんですが、今後、なされていくんだと思うんです。今後の指導員のあり方とか、学校からの温度差みたいなものについての統一性というものは今後どうされていくのかというのをお聞きしたいと思います。","respondent":"市川庶務課長","answer":"まずこの指導員の養成と申しましょうか、一定の能力開発なり人材育成といったことが喫緊の課題であると認識しております。こういったことが今後の指導員に求められてくるところだと、私どもも考えてあります。","id":"exchange-059"},{"speaker":"西本委員","kind":"確認","question":"一部は確認なんですけれども、指導の内容についてはもう２つに分かれたとか、その点はどういうふうにお考えか尋ねました。","respondent":"中島指導課長","answer":"例えば生活指導上、暫定的に２つに分けて複数担任でそこに当たりながら指導するというケースはあります。ただ、いわゆる学級数がそこで変更したとか、そういうわけではなくて、形式としてそういう形での指導を行っているという状況です。","id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"私は３０人というのを限定するのではなくて、それはある程度融通を効かせた、今後もそういう形で進めていかれようとしているのか。学級の編制みたいな形での考え方を最後にお聞かせいただきたい。","respondent":"中島指導課長","answer":"そういった形での変更はございませんけれども、３つに分けて指導するですとか、多様な方法が考えられていくものと思います。","id":"exchange-061"},{"speaker":"沢田委員","kind":"質問","question":"３０人学級のことが出てきましたので、中央教育審議会答申では４０人学級の問題には何も触れていないという話ですが、本当ですか。１０月２６日の中央教育審議会答申の少人数学級の編制に係る部分で、ちょっと違う決定が出ているんじゃないかと思うんですが、いかがか尋ねました。","respondent":"古里学務課長","answer":"すみません、ただいま資料を持ち合わせてございませんので、明確にお答えすることはできませんけれども、少なくとも現在の学級編制の基準に大きく影響を与えるような言質はなかったように、私は記憶しています。","id":"exchange-062"},{"speaker":"沢田委員","kind":"質問","question":"もしわかっていたら正確なところを教えてほしいんですが、少人数学級についても視野に入れて考えていく必要があるようなニュアンスの答弁が再質問の中でされたかのように思うので、その辺はいかがか尋ねました。","respondent":"古里学務課長","answer":"教育長がお答えをした内容のとおりと私どもは承知をしてございまして、東京都の方でいろいろな意味での検討がなされているです。その内容については私どもはまだ知らされていません。","id":"exchange-063"},{"speaker":"沢田委員","kind":"確認","question":"これは議事録も含めて確認したいと思います。本当のところはどうなのかと。","respondent":"中島指導課長","answer":"東京都が教員定数の方針の中で、私たちは少人数指導の有効性、それで成果が出てきている状況も報告してまいりました。当然これからいろいろな変化をしてまいりましょうから、それに合わせて、私たちもさまざまな対応をしていく形になろうかとは考えています。","id":"exchange-064"},{"speaker":"沢田委員","kind":"意見","question":"第８次の教職員の定数問題を考えるそこで、そのときまでにはやろうと、どんどん減っていくから教職員が余ってくるからということを私は聞いたんです。全国４７都道府県のうち、世界標準である３０人学級とか少人数の学級に移行してほしいというのが多いから…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"南委員","kind":"質問・要望","question":"今、３０人学級とか少人数学級についての流れというかは沢田委員からの話だったので、私はちょっとそことは離れるんですけど、今、世界の中で、改めてどのくらいの１クラスの人数なのか、ちょっとその辺の先進的なところをちょっと教えていただきたい。","respondent":"中島指導課長","answer":"ただ、実際に平均の児童数としては１７人から２０人、２１人から２４人、小学校、中学校はそれぞれそういう状況にあるとなっています。５年生から１０年生は同じく２４人、５年生から１０年生、別の州では２８人という設定もあります。","id":"exchange-066"},{"speaker":"南委員","kind":"質問","question":"Ｇ７のそういう国々は大体上限が３２人、アメリカの１年生から３年生のところが３２人ということで、大体それを下回った実態ですね。集団教育とか集団保育の中で、そういう言われ方をしているようなんですけれども、その辺の状況というのはどういうふうにとらえていかれるか尋ねました。","respondent":"中島指導課長","answer":"幼児教育、それから学校教育という範囲でのお答えになってしまうかもしれません。特に学校教育におきましては特別支援教育が今後先行していく流れの中で、学力的にも、また生活的にも非常に重要になってくる部分だと考えますし。","id":"exchange-067"},{"speaker":"南委員","kind":"質問","question":"授業を運営していくのは大変になっているという声を聞くんですけど、品川区の場合はそういう声というのはどの程度の範囲あるんですか。あるいは以前と比べて多くなったとか、少なくなったとか、傾向だけでも知りたいんです。","respondent":"中島指導課長","answer":"例えば学期初めと、それから秋のクラスとか、１０月の段階での学級の様子は大きく変わってまいります。今現在、そういう１年生の学級が継続しているというのはございません。","id":"exchange-068"},{"speaker":"南委員","kind":"質問","question":"そういう子どもたちが当然小学校に入ってくるわけですから、学校の中での教育活動そのものにも、私は見ているわけです。教育委員会の方の体制、３０人学級からちょっとそれますけれども、その辺については実態的にはどうなんか尋ねました。","respondent":"中島指導課長","answer":"学級数が１０月３１日に学校選択制のデータが上がった段階で微調整が入りまして、それに合わせて教員の定数がはまっていくという形になります。学校も一定の期間の中で、この作業を進めていくという状況があります。","id":"exchange-069"},{"speaker":"南委員","kind":"質問","question":"支障が出てはならないわけですから、それに非常にスピードアップして、体制をとってきているという状況があるんじゃないかと思います。区民だけじゃなくて、親としての国民的なそういう声というものについてどういうふうに思っておられるのか、あえて改めて伺いたいと思います。","respondent":"中島指導課長","answer":"この学級の規模と、そういった一人一人の発表する力、表現力といったものとの明確な相関はなかなか難しいと思います。今回の小中一貫教育の２本の柱をここに押さえている部分がありますし、今の品川区でできることということで、進めている状況です。","id":"exchange-070"},{"speaker":"南委員","kind":"意見","question":"むしろ、すべての子どもを引き上げていくというところでのやり方に早く切り替えていくべきではないかと思っています。以上、意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"南委員","kind":"質問","question":"私は１番の実態調査を行ってほしいという趣旨、実態調査をしてほしいという要請について、状況把握という程度にとどまっているという状況なんですね。したがって、この要請項目と大きな乖離があるということをどうしても感じざるを得ませんので、ぜひとも意見陳述を受けていくべきだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"沢田委員","kind":"質問・要望","question":"どういう中身であれ、陳述をさせてほしいと言ったときには、原則として受けるべきだと思います。両側が教室で、すまいるスクールそのものもよい制度に発展できる契機になるんじゃないかと思いますので、ぜひ陳述はやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"西本委員","kind":"確認","question":"ただ、ここのあえて意見陳述を聞くほどの内容、聞いて確認しなければいけないものかどうかというのはちょっと疑問があると思います。家庭のあり方とかも含めて考えていかなければいけないというご答弁もお伺いしましたし、ある程度ご理解されたんじゃないかと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"沢田委員","kind":"質問","question":"継続して、陳述は受けないということを決めましたけれども、そこらについて次回でも私ども自身も調べて質問をしたいと思います。今日のところはとりあえず継続をお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"南委員","kind":"意見","question":"やっぱり現場のすまいるスクールのところなども、直接この委員会としても調査に行ったりとか、そういうことが必要なんじゃないかと思うんです。平成１６年度から新たな届も出して、それから結論を出してみてもいいのかなと思いましたので、それからちょっと結論を出しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"沢田委員","kind":"質問・要望","question":"主権者の人格と学力をつくるという大変な問題ですから、一刻も早く３０人学級を実現すべきだと思います。そういう点からしても、３０人学級の問題の早期実現を求めたこの請願は採択すべきだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"}]},{"id":"topic-03","title":"の平成１７年特別区人事委員会勧告の概要","agenda":"の平成１７年特別区人事委員会勧告の概要","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"公務員はこの何年間かとまっていたんじゃないかと思うんだけど、やっぱり上がっていたんでしょうか。ちょっとそこらの全体の流れがわかったら教えてほしいんです。","respondent":"市川庶務課長","answer":"１点目の調査対象事業所ですけれども、この対象となる事業所の規模については、ほぼ例年同じ規模で推移をしてきてあります。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問","question":"民間事業所の職種はどういう職種なんでしょうか。その辺はどういう考え方で査定をしているんか尋ねました。","respondent":"市川庶務課長","answer":"職種の選定については、全産業分野にわたって、平均にわたるように職種のピックアップを行ってあります。その時々好況の職種、不況の職種織りまざってありますので、その辺は平均化できるような調査方法を従来からとっているということです。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"品川区における幼稚園教諭というのは、幼保一元化も含めて考えると、いろいろ内容が複雑化してくると思うんですね。その辺は給料にははね返ってくれるのか、あくまでも時間数でそういうふうになってしまうのか、そこら辺はいかがか尋ねました。","respondent":"市川庶務課長","answer":"特にこれから幼児教育に従事する職員も国家公務員、地方公務員の給与のあり方については、関心を持たれて検討がされているです。従来から平成１２年に特別区の新しい制度になったとき以来、いわば暫定的な対応を現在、とっているところです。","id":"exchange-080"},{"speaker":"南委員","kind":"意見","question":"２４人とさっきおっしゃったんですけれども、これは品川区のいわゆる公立幼稚園の先生の数ですよね。全体で２４人しかいないということじゃないのではないかと思っていたんですけど、公立幼稚園の先生の数が２４人、よくわからないんですとの意見を述べました。","respondent":"中島指導課長","answer":"今、大崎保育園に２人派遣で行っている教員も含めまして、いわゆる幼稚園教諭として採用されている人間の数が２４人です。研修派遣されておりますので、そういった人材を含めると、公立幼稚園に勤務している人材の数はもっと多くなります。","id":"exchange-081"},{"speaker":"南委員","kind":"確認","question":"確認なんですけれども、いわゆる園長職の方も含めて２４人ということでいいということか尋ねました。","respondent":"中島指導課長","answer":"小学校長が兼務している兼任園長は含みません。専任園長が３人おりますので、それも含んだ数です。","id":"exchange-082"}]},{"id":"topic-04","title":"続きまして、(2) 平成１８年度小・中学校新１年生希望申請結果等","agenda":"続きまして、(2) 平成１８年度小・中学校新１年生希望申請結果等","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"特に中学校の八潮南中学校が４人という状況なんですけど、どうするつもりなんですかね。現時点での考え方を説明を求めました。","respondent":"古里学務課長","answer":"石田議員の質問に対して回答させていただきましたけれども、合同教育、さまざまな工夫で教育効果を高めることは可能であります。区としては従来どおりの経過ですけれども、その学校を選択した児童生徒がいる限り、当該校を支援していくという考え方に変わりはございません。","id":"exchange-083"},{"speaker":"沢田委員","kind":"質問","question":"「学力で問題はないですか」と言ったら、ここまで行っちゃうとどうかなという気がするけれども、実際はどうなんですか。専門家としていかがなものか尋ねました。","respondent":"中島指導課長","answer":"逆に特色ある教育活動を考えてと回答していただいた、１８.５％、１９.９％という形でポイントを年々上げてきていただいている状況があります。６、７年生のより一体となった学びの場と内容を提供していこうという形で今、体制を組んでいる状況があります。","id":"exchange-084"},{"speaker":"沢田委員","kind":"質問","question":"希望申請をするのはどういう理由で自分の学区域外を選んだかというのは、それはやっぱり施設は７.８％ぐらいなんでしょうか。そのこと自身が回避していくあれにならないのかなというのがあるんだけれども、その辺に対していかがか尋ねました。","respondent":"古里学務課長","answer":"アンケートの中に希望申請をした保護者あるいは生徒たちの動向が読み取れると考えております。大半は皆さん、その地域の子どもたちを懸命に受け入れるように、特色ある学校づくりを進めているものと考えています。","id":"exchange-085"},{"speaker":"沢田委員","kind":"質問・要望","question":"これではいかに努力しても私は報われないのではないかという気になっちゃうんじゃないかと思います。４人でやっぱりすばらしい学力をつけ、ぜひそういう意味での援助を惜しまないでいただきたいということを言って、要望して終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"南委員","kind":"質問・要望","question":"果たしてそれだけでもいいのかどうかも含めて、きちんとした検証が必要だと思いますので、そのあたりを伺いたいというのが１点。それから３点目の質問は、インターホンで相手を確認してから、かぎをあけて入っていただくという対応をとっておられますね。","respondent":"中島指導課長、古里学務課長","answer":"１けた台の入学者ということでありまして、学校としてもその状況についてはいろいろと検討しています。「まもるっち」を持って、もちろん防犯ブザーで対応している学校もまだありますが、この件数は１学期に比べて… 私からは２つ目の兄弟枠の問題についてご回答しますが、ご案内のとおり、品川区の学校選択制の中では兄弟枠は設けてございません。仮に優先枠を設けた場合…","id":"exchange-087"},{"speaker":"南委員","kind":"質問・要望","question":"いろいろなケースがあるわけですから、判断をしていかなければいけないということを、私は教訓にするべきかなと考えています。もっともっと活性化できるように、ぜひいろいろな支援をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"松澤委員","kind":"質問","question":"私は荏原にいるものですから、荏原第四中学校、平塚中学校が少なくて、大騒ぎしていましたけれども、このごろ順調に増えてきている。そういうことで学校が、教職員が１つにまとまらなくてはできないことですから、学校そのものが１つの機能をし始めてよくなってきたと思うんです。","respondent":"古川教育次長","answer":"２年の中で、検討していくべき大きな内容を含んだことなのか、考えていく部分もあるのかなと思ってあります。現時点で４人ということで、なおかつ地域の大きな問題としてとらえていく必要があれば、それに対しても検討していくことが私どもの基本的な姿勢です。","id":"exchange-089"},{"speaker":"松澤委員","kind":"質問","question":"校長、副校長の努力だけじゃなくて、学校全体が１つにまとまっているということじゃないかなと思うんですね。顕彰制度というのはどうか尋ねました。","respondent":"中島指導課長","answer":"それぞれの学校がさまざまな努力をしているところでございまして、なかなか具体的に数字ですとか、目に見えないものも多くあろうかと思います。はそのチーム、こういったものを表彰する機会を設けてきてございまして、そういった中でも具現化をしていければと考えています。","id":"exchange-090"},{"speaker":"西本委員","kind":"確認","question":"数字を確認したいんですが、平成１７年度、平成１６年もですが、これは最終的に入学した数になりますね。あまり変動し過ぎちゃうと、また教職員の数にも非常に影響が出てきてしまうと思うんですが、それはどういう考えなんか尋ねました。","respondent":"古里学務課長","answer":"通知を出した後に、改めて指定校変更という手続が１２月の就学指定通知書が行った後で行われます。入学辞退を申し出てくるのも１２月に入ってからですので、その数がどう変質して出てくるかということも、ご理解いただきたいと思います。","id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"どうしてこんなにというところは、保護者の皆さんの希望というんですか、はっきりわからなくなっちゃうんだと思うんです。この傾向は来年も続いちゃうし、やはり集中校が出てきてしまうということで、今後の考え方はいかがか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"区民の方に教育内容をかなり説明はしてきたものの、まだまだ周知、通常の施設が分離している一貫校よりもできるものが多いと思うんですね。１年、２年とやっていくことによって、かなりの一貫教育ができるということをご理解いただけると考えております。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"全体の質問項目の中に入らないかもしれませんけれども、一貫教育をどう思うかとか、そういう項目を入れていいんじゃないかと思うんです。いい機会ですから、どういう考えで選択したのかということを入れていただきたいと思うんですが、いかがか尋ねました。","respondent":"古里学務課長、吉村小中一貫教育担当課長","answer":"私どもも長年、この項目でとってきましたけれども、若干意味が薄れている項目もあります。アンケートは継続性が非常に大事な部分もありますので、若干の変更、従来から考えてきたところです。 私どもも非常に大きな課題であり、今からある程度視点を決めて、一貫教育の効果というものを検証していこうと考えております。ですから、それとは別にまた一貫教育の検証という側面については…","id":"exchange-093"},{"speaker":"西本委員","kind":"質問・要望","question":"自分の子どもは自分で守っていかなきゃいけないわけですから、交通の事情を考えなければいけないし、そこは親としてやっていかなければいけない。これから続くのか、なくなるのかということを確認をさせてほしいと求めました。","respondent":"古里学務課長","answer":"ただ、私どもとしてこういう５校になる、もう少し丁寧な説明を申し上げた方がよろしいのかなということを今年の反省として持ってありますので。それから２つ目のご質問につきましては、今、私どもの方では全然もくろみしてございません。","id":"exchange-094"},{"speaker":"南委員","kind":"質問","question":"やっぱりあそこの地域で、選択ですから、どこでも自由に選べていける。だったらもっと、教育の中身的に他の地域と交流ができるような教育ができるような創意工夫というんですか、ぜひその辺は意見としてでいいですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-095"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270991?Template=document&Id=4554#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":81099,"voices":224}},{"id":"h17-20051128-5","meetingId":"h17-cm11","date":"2005年11月28日","dateIso":"2005-11-28","committee":"総務委員会","time":"午前１０時０４分～午後３時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"の２、議案審査","agenda":"の２、議案審査","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"一つは、今回区の職員が秘密漏えいした場合、地方公務員法上の罰則と条例でも罰則を科すというふうに二重にしているのですけれども、このねらいというか意味はどういうことなのか尋ねました。","respondent":"中川原広報広聴課長","answer":"私どもの条例では、３０万円以下の罰金になっておりまして、一般の方が漏えいした場合のほうが罰金が重くなってあります。ここのバランスを取るために条例に３０万円以下の罰金という形で入れたということになります。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"この対応というか、この辺のところは地方公務員法では罰則はある意味では軽くなっているという意味も出てくると思うんです。区でバランス、バランスと言ったら際限なしにいくのではないかと思うんですけれども、その辺はどうか尋ねました。","respondent":"中川原広報広聴課長","answer":"今回、行政機関個人情報保護法を横引きにいたしまして、個人情報の権利を擁護するという目的の法のもとに整理してきたものです。この規定を罰則の量刑について法定権については検察庁ともこの間協議をしてまいりまして、今回このような形で規定をさせていただいたものです。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問・要望","question":"もう１点、区と派遣労働者の関係は区のほうが指揮命令という関係が出てくるということで、そこの関係をもう少し詳しく説明をいただきたい。そもそも会社がどうなのかということが問われてくるのではないかと思うんですけれども、考え方はどうか尋ねました。","respondent":"中川原広報広聴課長","answer":"第３７条は、雇用主と労働者の指揮命令関係に基づく量罰規定を設けたものです。あくまで刑事罰ですので、今回はこの中に区が指揮命令監督をするという立場上、入ってこないということでご理解いただきたいと思います。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"意見","question":"そもそも罰則だけで、言葉は悪いですけれども脅しでいくのもあると思うんですけれども、やはりそもそもセキュリティのところが大事だと思うんです。最近、この間取りくんでいるところの考え方と特徴的なところがあったら併せて紹介してほしいと求めました。","respondent":"桑村人事課長","answer":"基本的には自由化されてきたということもございまして、資格を持った方をそのまま継続していきたいという動きもあって派遣を入れてきたものです。さらに派遣労働者も適用したほうが、脅しというわけではありませんけれども…","id":"exchange-004"},{"speaker":"本田委員","kind":"質問・要望","question":"一般的に考え方を教えていただきたいんですが、地方自治法第１４条ですか、第１５条ですか。地方自治法第１４条、基本のところでどのように解釈をされて私どもは理解しておけばいいのか、その辺を教えてほしいと求めました。","respondent":"中川原広報広聴課長","answer":"個人情報保護法では国の公務員のみを規定しておりまして、地方自治体はそれぞれの条例をもって定めるようにという役割分担になっております。今、お尋ねの地方自治法とは抵触しない関係になっていると考えております。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"地方自治法の確か第１４条だと思いますけれども、条例をつくる基本の問題で私は伺ったんです。そういう点から見れば、罰則的な内容なものですから、第１４条との関係はどうかということを尋ねたのです。","respondent":"中川原広報広聴課長","answer":"個人情報保護法の趣旨に範囲内で法律の委任を受けているものと解釈しております。","id":"exchange-006"},{"speaker":"本田委員","kind":"質問","question":"では、第１４条の枠内で、これは問題ないという解釈だという受けとめ方でいいんか尋ねました。","respondent":"濱野助役","answer":"先ほどの説明の中で地方公務員法の話が出てきてしまいましたので、それで話が少しあれになっているのかもしれません。地方自治法第１４条と条例との関係でいうと、それとの関係で言えば第１４条には抵触していないという認識です。","id":"exchange-007"},{"speaker":"高星委員","kind":"質問","question":"ただ、条例によって例えば人権や不利益な扱いをされた人たちの救済といった部分は、その辺のところでおさまりみたいなものは全然ないんですか。法律で、条例が変わったんですから、その辺は特別に関係ない話なのかどうなのか説明を求めました。","respondent":"新美企画部長","answer":"地方自治体は先ほどからご説明しているように、そういう意味では個人情報保護という観点で公務に携わる者。この法律とはまた別途の法律上の課題ですので、こことは直接には規定がされない領域というふうにご理解いただければと思います。","id":"exchange-008"},{"speaker":"高星委員","kind":"質問","question":"何とかわかりそうな気がするんだけれども、今回条例という形で新たに厳しい罰則が科せられているという。すっとこれだけ出てくるのかなと、そこのところが気になったので聞いてみたんですけれども、そこのところは議論されているのか尋ねました。","respondent":"新美企画部長","answer":"今、お尋ねの件は国会でどういう法律的な救済に関する法律をつくっていくかというのは、今まだ論議をされている段階と考えております。個人情報保護で今回は罰金の部分が重い量刑を科すという形に、法律との整合性を図ったという規定の仕方というふうにご理解いただきたく思いま…","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問","question":"部署的には先ほど保育園、選挙事務という説明だったんですけれども、今後どんな感じになっていくのかわからなかったので。それから、派遣法自体には罰金規定は多分入っていないと思うんですけれども、その辺を説明を求めました。","respondent":"桑村人事課長","answer":"児童センターは３０名、選挙のほうは選挙ごとになっておりますが１００名から１２０名程度、人事課で欠員の形で１０月から１月まで事務が２名います。その意味では、犯したところは登録が最終的に取り消される形になってあります。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"情報漏えいという問題ですから、最初の３万円という金額自体に納得がいかないんですけれども、この辺の改正というのは今後考えられていくのか。この辺も区としてどう考えているのかというのが一つと、どう考えたらいいのか、お聞きしてよければ聞きたいと思っていますけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"意見","question":"確か区の課長が受けたんですね。もし品川区であった場合どうするのかと前から疑問に思っていたことがあったのでとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"全体の量刑の重さについては、あくまで私ども行政機関の法律に基づいた形の横引きですので、今後国の考え方を注視したいと考えています。ただし、考え方ですので、そこまでオープンに課長の判断で出せるかどうかというのは疑問のところだと考えております。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今、おっしゃったＮＨＫがもし聞くときには、本人の了承を得てもう１回区に来るということですか。本人の了承を得ること自体は、相手がわかっているから区に確認に来る必要がないのではないかと思いますけれども。","respondent":"新美企画部長","answer":"第２５条に目的外利用および提供の制限についての規定をしておりまして、第２項５号に同一実施機関内で利用する場合、つまり目的外ですね。規定はそのようになっております。","id":"exchange-013"},{"speaker":"三村委員","kind":"質問","question":"派遣の方のだれがどういう情報に触ったというレベルまで庁内の情報の管理はされているのか。どういう人がどういう情報に触っているのか、それを記録として残していくのか、その辺のことについて教えていただけますか。","respondent":"小野情報システム課長","answer":"そして、この部分につきましては、職場の管理者の課長あるいは係長が必要と認めた情報以外はアクセスできないような形にシステムをつくっております。情報システムをそういう形で整理いたしまして、その後、実際の業務に使っていく形に進めていくところです。","id":"exchange-014"},{"speaker":"三村委員","kind":"質問","question":"アクセスは状況に応じてということだったんですけれども、パスワードの提供があると思うんですけれども、そういった場合は一定の期間で更新したり、新しい人が入った場合は古いパスワードは無効にするとか、そういった処理もされているんか尋ねました。","respondent":"小野情報システム課長","answer":"ＩＤパスワードの管理につきましては、派遣労働者とわかる識別ができて、それにおいてアクセス管理ができるＩＤパスワードを一人ひとり交付しまして、当然人がかわったときにはすべて入れ替えをするという管理をいたしております。","id":"exchange-015"},{"speaker":"藤田委員","kind":"質問","question":"区の職員が業務上知り得た情報について漏えいした場合、地方公務員法で罰せられるというのはよくわかるんですが、職員が退職した段階で、おそらく守秘義務というのはずっとつながってくると思うんですが、その辺をまずご説明いただけますか尋ねました。","respondent":"桑村人事課長","answer":"もちろん退職後も業務上知り得た情報については守るように科せられていますし、罰則規定もあります。この条例上も職員であった者というのも入ってありますので、同じような規定になると思います。","id":"exchange-016"},{"speaker":"藤田委員","kind":"質問","question":"そうしますと、現職で仕事をしていた場合は３０万円になるんですが、派遣労働の仕事をやめてしまったという場合はどういうふうになるのでしょうか。派遣労働者は一緒だといえども、そこまで条例を運用させていくには相当難しい部分が出てくるのではないかと思うんですが、その辺の率直な感想を。","respondent":"桑村人事課長","answer":"情報の与え方を職場の中で考えていただくということで、私どもとするとそこの課と十分話し合いをして、あるいは人事の者が会ってお話しをする。その方についても守秘義務は同じことだろうと考えていますので、どれだけ職場の中で情報を管理していくかだと考えています。","id":"exchange-017"},{"speaker":"藤田委員","kind":"質問・要望","question":"やはり公務員との意識の違いは当然あるわけですから、その歯止めをきちんとすべきではないかなと考えています。要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"言葉の関係ですけれども、「知り得た個人情報をみだりに他人に知らせ」の「みだり」と書いてあるんですけれども、みだりでない何かあるのでしょうか。例えばこの「みだり」というのは、どういうことなのか、そこのところはどんな想定をされているかお聞かせほしいと求めました。","respondent":"中川原広報広聴課長","answer":"第３４条ですと、もしくは盗用ということで、そういった目的で出してしまったというようなことです。第３６条では、知り得た情報を漏えいしてしまったという、それを「みだり」ということで一括して説明させていただきました。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"雇用関係がある意味強いですから、これがどういう歯止めになるのか、雇用関係がある会社も視野に入れておかないと不十分ではないかと思うんです。このことは指摘しておきたいと思うんですけれども、何か考えがあれば。","respondent":"本間総務部長","answer":"ただ、そこから派遣されている労働者個人には、今までは不正をやってもとがめる手立てが何もなかった。今までるる説明したようなことがあった場合には、こういう罰則をかけていきましょうですので、ひとつご理解のほどをよろしくお願いいたします。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"意見","question":"要するに、コップの水をお風呂の中に入れてしまう。お風呂から出ないからいいではないかという議論とは少し違うような気がするんですとの意見を述べました。","respondent":"本間総務部長","answer":"まさに先ほどのご質問の「みだり」に漏らさないというのは、自分が派遣労働者であった派遣元企業に、そういう情報は漏らさないということを、今回きちんと規定しているというふうにご理解をいただきたいと思います。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"確認","question":"確認すると、今みたいな例であっても、派遣されている労働者は会社の中の間であっても、それはだめだということになっているということでいいわけですね。","respondent":"本間総務部長","answer":"おっしゃるとおりです。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"意見","question":"１点聞きたいんですけれども、役務のところで、「複数年度にわたり契約締結することが妥当でない場合もあるため」ということですけれども、具体的にどういうことを想定しているのかとの意見を述べました。","respondent":"鷹倉経理課長","answer":"複数年度にわたって例えば平成１８年から２年、３年、相手方も契約金額を上げることができなくなってしまうということがあります。契約変更をやろうとしても、もしやったとしても一定金額を求められるということで、そういう不都合があるかと思います。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問","question":"派遣されて来る方にもよるのではないかと思うんです。今、具体的にどういうところが考えられているかというのはどうでしょうか、その相手方を見て考えるのか尋ねました。","respondent":"鷹倉経理課長","answer":"例えばこの契約内容で４年ないし５年いくというようなことでは、相手方もずっと通してきますし、割返したほうが安くなる。これは客観的に契約内容としてわかる場合については、複数年という形の契約に進めたいということを考えていきたいなと考えています。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問","question":"複数年度にやった場合、例えばいろいろ技術も発達してくる場合、複数年度でやっていくと大変な負担が出てくる。そういう場合には長くしていると、そういう場合の対応はどういうふうに考えているのか尋ねました。","respondent":"鷹倉経理課長","answer":"まさにした形で陳腐化するというおそれがあるという場合は、複数年度の５年にしないで３年に変えるとか、物の性質によってはそういうことも、ただし３年ごとですから、我々の金額が若干高くなるわけですけれども、そういう見極めをしながらやっていく必要があると考えています。","id":"exchange-025"},{"speaker":"原委員","kind":"質問・要望","question":"１点だけ確認させていただきたいんですけれども、リースも委託契約もそうですけれども、区の状況の中でどういう形が出てくるのでしょうか。例えば契約方法が相当変わってくるのか、あるいはほかの状況が出てくるのか、ある程度の試算ができると思うんですが、その辺との兼ね合いを。","respondent":"鷹倉経理課長","answer":"したがって、区側から見れば事務の煩雑さが軽減されるということと、それから業者側から見れば若干安心できるということがあろうかと思います。これは物品のリースの関係です。","id":"exchange-026"},{"speaker":"原委員","kind":"質問","question":"それでなければ組めなかったりするわけですから、そうすると条例が出てきたときには、特に機械警備とかそういうところに該当するのですか。そうではなくて、もっとほかの部分に波及するということがありますか。","respondent":"鷹倉経理課長","answer":"今のところ、来年４月以降は物品のリース関係のところをきちんと整理していきたいと、当面は考えてあります。役務のところについては、そういう案件が出てくるかどうかを見極めながら進めていきたいと考えています。","id":"exchange-027"},{"speaker":"原委員","kind":"質問","question":"そうすると、今までもリース契約そのものは整理されていない状況というのは、いろいろな契約状況が出ていたということですか。そうすると、それに対応するために役所のほうはどういう形を取っていらしたのかということですが、それは。","respondent":"鷹倉経理課長","answer":"先ほどの説明でもお話ししたのですけれども、２年目あたりまでやっていたけれども、３年目で解約することにしたと。今回は、そういうことがなくなるかと思います。","id":"exchange-028"},{"speaker":"原委員","kind":"質問","question":"要するに、５年契約をしていて、３年目でだめになって払えなくなった金額というのは、どういう形で処理されたのか尋ねました。","respondent":"鷹倉経理課長","answer":"区としては支払わないわけですから、業者の方が不利益とは言わなかったですけれども、若干のが行われたか、端的に言ってしまいますと、そういう形になります。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"結局、長期にわたったリース契約を結んでくれという要望というのは、法的に改正を求められていたのかどうか。１年目の契約は初期投資の部分をなさっていて、２年目から平年化した数字だけなのかどうか、その辺をまず教えてもらいたいと思います。","respondent":"鷹倉経理課長","answer":"今回の背景のところで説明申し上げたとおり、国のほうで規制改革事項という中で、そしてこれを入れていかれた背景があるかなと考えております。一定の初期投資をされて３年なら３年、５年なら５年で割返して金額の設定をしているという状況ですが…","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１年目には大きな数字が乗っているし、２年目以降に対しても当然乗せた数字が、入札自体も高く出ているのではないかと思うんです。行政側だから絶対大丈夫だと民間が見てくれているのかどうか、そういう見方というのはどうなのか考え方をお聞きしたいんですけれども。","respondent":"鷹倉経理課長、本間総務部長","answer":"確かに、民間の方が入札のときにどういう思惑でやられているか、非常に難しいところですが、その辺は思惑の部分で何とも申し上げられないですけれども、我々は適正に入札されているかと理解しています。 若干補足をしますと、今までは言い方を変えれば、電気、ガス、水道しか長期継続の契約を結べなかった。先ほど来経理課長が説明をさせていただいているとおり、それに実態がより相応しいものについては…","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"確認","question":"長期化することによって、そこが変わるのではないかということから今確認をさせてもらったんです。２年間でしたか、債務負担行為、それの長期化も持っていってもらいたいなという希望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"高星委員","kind":"質問","question":"僕らはマンションの関係でそんなことをやっているものですから、その辺の救済措置というのはないのかどうか。限度というのは、この辺だろうというやつをどこで積算というか、こちらのほうでチェックする機能がどの辺で働いているのかどうか聞きたいと思います。","respondent":"鷹倉経理課長","answer":"当然１年分は上がるわけですけれども、委員ご指摘のとおり、そういう結び方もあるのかなということがあります。したがって、区として一番安定的ないい職務サービスがきちんと受けられるような形のリースにする必要があると考えております。","id":"exchange-033"},{"speaker":"高星委員","kind":"意見","question":"先ほど来相応しい状況だという言葉もあったけれども、先ほど聞いたのは積算というか、その仕事の最低限のものをはじいて、それより下回っているものはおかしいのではないかというチェックというか、その辺のところがどうなっているのか…","respondent":"鷹倉経理課長","answer":"ここで契約を結んでいるわけですから、結んだとおりのサービスがなされているか、そして検査をしてお金を払っていると。長期継続契約でありますけれども、これはまた別の次元の話になってまいりますので、随意契約だから安心ということにはならないのかと考えています。","id":"exchange-034"},{"speaker":"藤田委員","kind":"質問","question":"そうすると、業者は３年間なり５年間なり契約できてよかったな。契約するときに非常に難しい選択、価格もそれ以上低く抑えようというようなことも当然考えられるのではないかと思うんですが、その辺はいかがか尋ねました。","respondent":"本間総務部長","answer":"契約事務の中で一定のきちんとした品質を確保した上で、一方では区内中小・零細企業の育成という視点も我々の一つの大きな課題として持っております。例えば長期の契約を考える場合でも、今後長期継続契約に臨んでいきたいと考えておりますので、よろしくお願いいたします。","id":"exchange-035"},{"speaker":"藤田委員","kind":"質問・要望","question":"今、総務部長がおっしゃったように、何でもかんでもではなくて、やはり事業を一つ一つ見ながら、これは３年がいい、これは５年がいいのではないか、これは単年度でいいのではないかという選択を真剣に考えていただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"工事内訳の円形管築造工のところに塩ビ管というのがあるんですけれども、まだ塩ビ管を材料で使うことが多いか尋ねました。","respondent":"原田下水道河川課長","answer":"塩ビ管は比較的遅くに入ってまいりまして、軽くて強度がありますので、そういう点で施工しやすいとか安いという部分があるので、その辺でまだ最近は、例えば昔は陶管と言われた、陶器の管にかわって比較的小さな管が主流です。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問・要望","question":"住民の方も希望していることですから、これはこれで良しとするんですけれども、どうも現実と違うかなという感じはしております。見直し等ができれば、ぜひ見直していただきたいなということを言っておきたいと思います。","respondent":"原田下水道河川課長","answer":"一応事情をご説明しますと、５０mm対応というのは大正時代から行っております状況があって、やはり都市化の進展で能力不足がある。河川の５０mm対応がまだ終わっていないという中で、我々がやっている５０mm対応が精一杯というところがありまして。","id":"exchange-038"},{"speaker":"高星委員","kind":"質問・要望","question":"例えば４０mmであっても、５０mmであっても、同様に商店街の店の中に浸水するということもあり得るだろうと思うんです。それがないと、結局一般区民の目から無駄金を使っているのではないかと言われるので、きちんとした考え方を示してほしいと求めました。","respondent":"原田下水道河川課長","answer":"取り込みの問題があるということは認識しておりまして、毎年６月に浸水対策強化月間ということで、対策も現地を見ながら一つ一つ対応しております。今回、例えば５０mmの雨で浸水被害が起こるようなことがないように…","id":"exchange-039"},{"speaker":"高星委員","kind":"質問","question":"逆のこともあり得るのではないかという質問が出たときに、課長が変更はないような感じがしたので、逆の発想というのはできないの。戸越幹線のほうがまだ余裕があるときに、逆のその時点から戸越幹線のほうに水を回すことができるのかできないのか。","respondent":"原田下水道河川課長","answer":"そこを通って戸越幹線のほうに水が流れておりますので、そういう意味からは貯留管がいっぱいになって、そこがあふれて戸越幹線はまだ余裕があるということはないと考えております。","id":"exchange-040"},{"speaker":"高星委員","kind":"質問","question":"私は正副で話しをしてもらって、こういうふうに思っているのだけれども、どうでしょうかというふうに仕切ってもらったほうがいいと思います。その辺のところで正副で決めてもらえればそれが一番よかったのだけれども、各委員に答えろと言うのだったら、今日は即決では難しいのかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"宮崎委員","kind":"意見","question":"そういうのがかなり遅れている関係で、その辺の整理が必要だという考え方が出てくるのではないかと思います。今日は写真撮影ということであれば、問題ないと思いますので、私は許可していいのではないかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"藤田委員","kind":"質問","question":"最終的に、これは報道関係ですから、皆さんも写真ぐらいならという話があったのではないかと思うんです。今、我々はもう少し議論を深めていくべきテーマであるなと思いますので、遠慮していただいたほうがよろしいのではないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"意見","question":"同じケースで、私は１年目だったのですけれども、ちょうど文教委員会のときでした。その諮り方をなさったので、全体的な話はまたこれから議会運営委員会かどうかわからないですけれども、そちらで話を詰めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"本田委員","kind":"質問・要望","question":"各委員の見解を求めると言われて、委員会は公開制ですから、撮れる機会もあるのではないかと思うんです。前もって撮れるかもしれないし、その辺は今ここでフラッシュをたくのがいいか悪いかということになれば、少し考えさせてもらいたいということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"三村委員","kind":"意見","question":"基本的に議会は公開していくべきだと思いますし、写真撮影等も認められる方向でお願いしたいと思います。ただ、議会がどういうふうに動いているのかというのは一般の方には見えにくい部分があるので、なるべく前向きに検討してほしいと求めました。","respondent":"塚本委員長","answer":"もちろん許可の権限は各委員会に委ねられておりますけれども、委員会の問題はあるという認識は持っております。〔「はい」と呼ぶ者あり〕","id":"exchange-046"}]},{"id":"topic-02","title":"平成１７年請願第１３号、公共工事における賃金確保法（公契約法）制定を国に求める意見書提出についての請願","agenda":"平成１７年請願第１３号、公共工事における賃金確保法（公契約法）制定を国に求める意見書提出についての請願","exchanges":[{"speaker":"高星委員","kind":"質問・要望","question":"それを下請・孫請のほうにいくわけですから、やはりかなり現場段階では厳しいものになっていくのかなと考えております。小間使いでありと、どういうふうに上がっているのかどうか、おさえているところがあったらお聞かせいただきたいと思うんですが。","respondent":"鷹倉経理課長","answer":"決算特別委員会でも質問があったかと思うんですが、私のところには直接なかったわけです。建設組合というのがあって要請をされているという状況はつかんです。","id":"exchange-047"},{"speaker":"高星委員","kind":"質問","question":"現場で働く若い人たちの中に退職金制度が制度として確立されていないものですから、執行部で知っている方は説明していただけますか。建設に従事する方々の退職金に絡む政府が行っている事業ですけれども、これを説明できる理事者の方は説明をお願いします。","respondent":"鷹倉経理課長","answer":"詳しくはあれですが、建設関係の方々が退職する際、退職金を確保するための共済制度という形で、個人が現場で就労した日数を確認できる共済手帳により、共済機構が直接労働者に退職金を支払うという制度があると聞いております。","id":"exchange-048"},{"speaker":"高星委員","kind":"質問","question":"これは企業がやっているというのではなく国の制度なものですから、ところが現実問題としては、そういった制度もきちんと履行されていない。したがいまして、最大限こういった方々の気持ちを酌んでというような取り組みを私どもはしなければいけないかなと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"理事者の方に答えていただけるかどうかわかりませんけれども、国の考え方を先に聞かせていただきたい。労働条件はこの中に出ているんですけれども、その辺はどちらが主体なのかというのを確認が取れればと思うんですが。","respondent":"鷹倉経理課長","answer":"ＩＬＯ第９４号条約の大綱に公共契約における労働条件に関する条約については１９４９年に実施されたということがあると聞いてあります。時間のずれがあった話なんですけれども。","id":"exchange-050"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほどの公共工事の労務単価、二省協定ですか、労働賃金この辺についても、例えばこれから区の中でこの数で積算をある程度していらっしゃる。それは一人幾らという単価だと思うんですけれども、熟練の方と未熟な方も同じ金額で出てくるわけか尋ねました。","respondent":"鷹倉経理課長","answer":"確か資料によりますと、先ほどの労務単価というのは、先ほど若干申し上げましたけれども、８時間当たりの単価ということで、時間外休日についての割増しのもの、あるいは手当についても含まれていないです。","id":"exchange-051"},{"speaker":"鈴木（真）委員","kind":"意見","question":"やはり、そういう人たちと同じ単価になってしまうように計算しているのかどうかというのがわからなかった。行政としてどういうチェックをしていかれるのか、行政の中の流れがわからないことがあったので、どういうふうに考えていったらいいのかという点でとの意見を述べました。","respondent":"宍戸施設担当課長、鷹倉経理課長","answer":"その際に非常に専門的な型枠ですとか、そういった人夫プラス一般工の補助というふうな、一般的にやった場合に専門的な人が何人要りますよと。これは当然高いわけですけれども、それと普通の単価という組み合わせ… そういう関係の法律を照らして、区あるいは都道府県かと思いますが、労働行政の流れが施行されているのかと。相まわないのか、これは国がどういう判断をされるか、その辺はちょっとわからない。","id":"exchange-052"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そこが労働基準法に絡んでくるのかどうか、どこまで係わるのか、行政側がそこまで入ってこなくてもというちょっと疑問があります。最初に聞いた法的な部分で、どこまで民間の契約に係わっている法律が何かあるのかなというところでいうと、何か現状においてはありますかとの意見を述べました。","respondent":"鷹倉経理課長","answer":"社会的弱者と言われている消費者を保護するために消費者保護法、労働だったら労働関係法があるということだと認識しています。したがって、今回こういう法律もそういうものと相まった形になるのかどうか、それは国あるいは判断されるかと考えています。","id":"exchange-053"},{"speaker":"三村委員","kind":"質問","question":"そういった労務管理の点も含めて、総合的な入札の評価方法みたいな、そういう仕組みは取り入れることが可能か尋ねました。","respondent":"鷹倉経理課長","answer":"その後の結果の部分ですので、適正な形で条件等を受け入れたということですので、最初の入札の段階で評価というのはなかなか難しいかなと。その次の履行の問題として、この業者が次から指名停止となるというようなことが考えられますが…","id":"exchange-054"},{"speaker":"三村委員","kind":"意見","question":"ある一定程度、前段階で施工している事例の中で、そういった不適当な事例が入っていないかどうかというチェックはできるかと思うんです。ある一定程度は技術だけではない部分も評価の仕組みの中に入れていくことは可能ではないかと思うんですけれども…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"本田委員","kind":"意見","question":"したがって、本請願については、このとおり今日採択をして、必要な意見書を提出するように取り計らったらいいのではないかと考えております。意見を申し上げますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"宮崎委員","kind":"質問・要望","question":"建設業者の方々からこういう要望が出るのは当然だと思います。やはり、しっかりした賃金が保障されて、しっかりした仕事ができると思いますし、そういう意味でぜひ今日採択ということがいいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"藤田委員","kind":"質問","question":"うちの堺議員も紹介議員になっておりますし、いろいろ話しを伺いました。そういうことも含めて、国はもっと議論をしてもらいたいと私も思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、仕事をしてから、職方の支払いですからすぐ払わなければいけないものが６カ月先にならないと現金にならないという状況を考えますと。その辺の文言を整理していただければ、私どもも採択ということでお願いして、意見書の中で調整していただければと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"中島副委員長","kind":"質問","question":"一昨日ですか、テレビで大阪のホームレスをなさっていた方が今はケースなんかをやって、高齢者の方がボランティアをやっていたんですね。ましてや技術を持った人たちは国にとっても大切なわけですから、そういう方たちの保障をしっかり考えていく。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"三村委員","kind":"質問・要望","question":"採択の方向で、そのような形で進めてほしいと求めました。国に意見書を上げるだけではなくて、品川区としてもどういったことの対応が可能か、ぜひ検討をしていただきたいということだけ意見として述べします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594587?Template=document&Id=1702#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":41065,"voices":151}},{"id":"h17-20051129-6","meetingId":"h17-cm11","date":"2005年11月29日","dateIso":"2005-11-29","committee":"区民委員会","time":"午前１０時０４分～午後４時０７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/678828?Template=document&Id=2444#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":3845,"voices":8}}]);
